function GO_Dot(p){ return React.createElement('span',{style:Object.assign({width:7,height:7,borderRadius:'50%',display:'inline-block',background:GO_rag(p.r)},p.style||{})}); }

function GO_Tile(p){ const t=p.t; const _sr=(t.series&&t.series.length>1)?t.series:null;
  const _stroke=t.rag==='r'?PAL.bad:t.rag==='g'?PAL.good:PAL.accent;
  const _statusTxt=t.rag==='g'?'On track':t.rag==='a'?'Watch':t.rag==='r'?'Off target':'—';
  return (
  <div className="go-tile" style={{background:GO_T.panel,border:'1px solid '+GO_T.line,borderRadius:'var(--radius-none)',padding:'14px 15px',position:'relative',boxShadow:'var(--shadow-panel)'}}>
    {t.rag && <GO_Dot r={t.rag} style={{position:'absolute',top:12,right:12}}/>}
    <div style={{fontSize:'var(--text-xs)',color:GO_T.mut,display:'flex',alignItems:'center',gap:5}}>{t.k}<span className="go-dot" style={{width:4,height:4,borderRadius:'50%',background:GO_T.accent,display:'inline-block'}}/></div>
    <div style={{fontFamily:GO_T.mono,fontSize:'var(--text-xl)',fontWeight:'var(--weight-semi)',margin:'8px 0 4px',letterSpacing:'var(--tracking-tight)',fontVariantNumeric:'tabular-nums'}}>{GO_fmt(t.v,t.fmt)}</div>
    <div style={{fontFamily:GO_T.mono,fontSize:'var(--text-xs)',color:t.d>0?GO_T.green:t.d<0?GO_T.red:GO_T.mut}}>{t.d!=null?GO_arrow(t.d)+GO_pctv(Math.abs(t.d)).replace('+','')+' ':''}<span style={{color:GO_T.dim}}>{t.cmp}</span></div>
    {t.tgt && <div style={{fontSize:'var(--text-xs)',color:GO_T.dim,marginTop:5}}>{t.tgt}</div>}
    <div className="go-pop">
      <div className="go-head">{_sr?(t.k+' · trend over selected timeframe'):(t.k+' · detail')}</div>
      {_sr && <R.ResponsiveContainer width="100%" height={64}>
        <R.LineChart data={t.series} margin={{top:4,right:6,left:-6,bottom:0}}>
          <R.CartesianGrid stroke={PAL.line} vertical={false}/>
          <R.XAxis dataKey="d" tick={{fill:GO_T.dim,fontSize:'var(--text-xs)'}} interval="preserveStartEnd" tickLine={false} axisLine={false}/>
          <R.YAxis tick={{fill:GO_T.dim,fontSize:'var(--text-xs)'}} width={30} tickFormatter={function(v){return Math.abs(v)>=1000?(v/1000).toFixed(0)+'k':Math.round(v);}}/>
          <R.Tooltip contentStyle={{fontSize:'var(--text-xs)',background:'var(--color-panel)',border:'1px solid '+GO_T.line,borderRadius:'var(--radius-md)',padding:'2px 6px'}} labelStyle={{color:GO_T.dim}} formatter={function(v){return [GO_fmt(v,t.fmt),t.k];}}/>
          <R.Line type="monotone" dataKey="v" stroke={svgCol(_stroke)} strokeWidth={2} dot={false} isAnimationActive={false}/>
        </R.LineChart>
      </R.ResponsiveContainer>}
      {t.d!=null && <div className="go-row"><span>Change vs prior</span><b style={{color:t.d>0?GO_T.green:t.d<0?GO_T.red:GO_T.mut}}>{GO_pctv(t.d).replace('-','−')}</b></div>}
      {t.cmp && <div className="go-row"><span>Detail</span><b>{t.cmp}</b></div>}
      {t.tgt && <div className="go-row"><span>Target</span><b>{t.tgt}</b></div>}
      <div className="go-row"><span>Status</span><b style={{color:GO_rag(t.rag)}}>{_statusTxt}</b></div>
      <div className="go-ask" onClick={function(e){e.stopPropagation(); if(window.__oiAsk) window.__oiAsk('About "'+t.k+'" (currently '+GO_fmt(t.v,t.fmt)+'): what is driving this over the selected timeframe, and what should I do?');}}>Ask Greta about {t.k} →</div>
    </div>
  </div>); }

function GO_Insight(p){ const i=p.i; return (
  <div style={{borderTop:'1px solid var(--color-line)',paddingTop:'var(--space-4)',marginTop:'var(--space-5)'}}>
    <div className="v3-kick" style={{marginBottom:'var(--space-2)'}}>Greta’s read</div>
    <p style={{margin:'0 0 var(--space-2)',fontSize:'var(--text-sm)',color:'var(--color-ink)'}}>{plainWords(i.text)}</p>
    <div style={{fontSize:'var(--text-sm)',background:'var(--color-accent-wash)',border:'1px solid var(--color-accent-line)',borderRadius:'var(--radius-none)',padding:'8px 11px',display:'flex',justifyContent:'space-between',gap:12,alignItems:'center'}}>
      <span>{plainWords(i.action)}</span><b style={{color:GO_T.accent2,fontFamily:GO_T.mono}}>{i.value}</b>
    </div>
  </div>); }

function GO_TierHead(p){ return (
  <div style={{display:'flex',alignItems:'baseline',gap:10,margin:'0 2px 16px'}}>
    <span style={{fontFamily:GO_T.mono,fontSize:'var(--text-xs)',color:GO_T.accent2,border:`1px solid ${PAL.panel}`,borderRadius:'var(--radius-md)',padding:'1px 6px'}}>{p.n}</span>
    <h2 style={{fontSize:'var(--text-base)',margin:0,letterSpacing:'var(--tracking-wide)'}}>{p.title}</h2>
    <span style={{fontSize:'var(--text-sm)',color:GO_T.dim}}>{p.sub}</span>
  </div>); }

// LLM performance read at the top of Overview. Grounded in the current snapshot (the same
// Business/Customer/Channel tiers shown below), framework-led, always linked to the present +
// the lever to pull. Live per view, cached per session by (brand, timeframe, period) so it
// only calls the relay once per timeframe. Reuses the ask-data relay (window.OI_ASK).
function OverviewSummary({d, tf}){
  const [txt, setTxt] = React.useState('');
  const [loading, setLoading] = React.useState(false);
  const [err, setErr] = React.useState('');
  React.useEffect(function(){
    // Wait for the rich snapshot to finish loading before calling the LLM — firing on a
    // half-loaded `d` (no channels / no pacing) produced a vague "not provided" read that
    // then got cached. Require the channel table + pacing to be present.
    if(!d || !d.hero || !Array.isArray(d.channel) || d.channel.length===0 || !d.pacing){ return; }
    var ASK = (typeof window!=='undefined' && window.OI_ASK) || (function(){ try{ return (window.parent && window.parent!==window) ? window.parent.OI_ASK : null; }catch(e){ return null; } })();
    if(!ASK || !ASK.endpoint){ setErr('nollm'); return; }
    // Key the cache to the ACTUAL numbers (CAM + revenue-to-date), not just the period label,
    // so the read can never show figures that no longer match the hero — a live data refresh
    // changes the signature → cache miss → regenerate, keeping the read and the hero in lockstep.
    var sig = Math.round(d.hero.cmAfterMkt||0)+'_'+Math.round((d.pacing&&d.pacing.revActual)||0);
    var key = 'oi_ovsum5_'+(ASK.brand_id||'')+'_'+(tf||'')+'_'+(d.periodLabel||'')+'_'+sig;
    try{ var cached = sessionStorage.getItem(key); if(cached){ setTxt(cached); setErr(''); setLoading(false); return; } }catch(e){}
    var C = d.cacBlock || null;
    var compact = {
      timeframe: tf, period: d.periodLabel, comparedTo: d.compareLabel,
      business: { contributionAfterMarketing: d.hero.cmAfterMkt, contributionMargin: d.hero.cm, contributionMarginPct: d.hero.cmPct, adSpend: d.hero.spend, operatingProfit: d.hero.opProfit },
      pacingVsPlan: d.pacing ? { pctVsTarget: d.pacing.pacePct, revActual: d.pacing.revActual, revTarget: d.pacing.revTarget,
        shortfall: (d.pacing.revTarget!=null && d.pacing.revActual!=null) ? Math.round(d.pacing.revTarget - d.pacing.revActual) : null, goalConfirmed: d.pacing.goalConfirmed } : null,
      businessMetrics: (d.business||[]).map(function(t){ return {metric:t.k, value:t.v, rag:t.rag}; }),
      customerMix: d.customer ? { newPct: d.customer.splitNew, returningPct: d.customer.splitRet, newRevenue: d.customer.newRev, returningRevenue: d.customer.retRev } : null,
      customerSegments: (d.customer && d.customer.rows) ? d.customer.rows.map(function(r){ return {segment:r.label, rag:r.rag, metrics:(r.cells||[]).map(function(c){ return {k:c.k, v:c.v}; })}; }) : null,
      acquisitionEconomics: C ? { rag:C.rag, cacActual:(C.cac&&C.cac.actual), cacBreakevenFirstOrder:(C.cac&&C.cac.first), cacBreakevenLtv:(C.cac&&C.cac.ltv), cacTarget:(C.cac&&C.cac.target), roasActual:(C.roas&&C.roas.actual), roasTarget:(C.roas&&C.roas.target), ordersPerCustomer:C.opc, repeatPct:C.repeatPct } : null,
      channels: Array.isArray(d.channel) ? d.channel.map(function(c){ return {name:c.name, role:(c.family==='email'?'email':(c.acquisition?'acquisition':'retention')), spend:c.spend, incrementalRevenue:c.incRev, contribution:c.contribution, iroas:c.iroas, marginalIroas:c.marginal, targetIroas:c.tgt, rag:c.rag, verdict:c.verdict}; }) : null,
      computedInsights: d.insights ? { business:d.insights.business, customer:d.insights.customer, channel:d.insights.channel } : null,
      highestPriorityAction: d.hero.action ? { title: d.hero.action.title, why: d.hero.action.why, value: d.hero.action.value } : null
    };
    var brand = (typeof OI_BRAND!=='undefined' && OI_BRAND) || {name:'the brand'};
    setLoading(true); setErr('');
    (async function(){
      try{
        // Pull the granular Meta campaign + ad performance already in the warehouse, so the read
        // can name the specific campaign / ad / creative that's dragging — not just the channel.
        try{
          var sb = (window.FRKL_LIVE && window.FRKL_LIVE.sb) || (function(){ try{ return window.parent && window.parent.FRKL_LIVE && window.parent.FRKL_LIVE.sb; }catch(e){ return null; } })();
          if(sb){
            var rc = await sb.from('vw_meta_campaign_perf_ui').select('campaign_name,spend,revenue,roas,cvr_pct,avg_frequency').eq('brand_id',ASK.brand_id).order('spend',{ascending:false}).limit(8);
            if(rc && rc.data && rc.data.length) compact.metaCampaigns = rc.data;
            var ra = await sb.from('vw_meta_ad_perf_ui').select('ad_name,call_to_action,spend,roas,cvr_pct,avg_frequency,roas_change_pct,fatigue_flag').eq('brand_id',ASK.brand_id).order('spend',{ascending:false}).limit(10);
            if(ra && ra.data && ra.data.length) compact.metaTopAds = ra.data;
            var gc = await sb.from('vw_google_campaign_perf_ui').select('campaign_name,channel_type,spend,roas,cvr_pct,impression_share_pct,lost_to_budget_pct,lost_to_rank_pct').eq('brand_id',ASK.brand_id).order('spend',{ascending:false}).limit(8);
            if(gc && gc.data && gc.data.length) compact.googleCampaigns = gc.data;
            var gw = await sb.from('vw_google_search_terms_ui').select('search_term,campaign_name,spend,conversions,roas').eq('brand_id',ASK.brand_id).eq('zero_conv_waste',true).order('spend',{ascending:false}).limit(8);
            if(gw && gw.data && gw.data.length) compact.googleWasteTerms = gw.data;
          }
        }catch(e){}
        var jwt=''; if(typeof ASK.getJwt==='function'){ try{ jwt=await ASK.getJwt(); }catch(e){} } else if(ASK.jwt){ jwt=ASK.jwt; }
        var headers = jwt ? {'content-type':'application/json','authorization':'Bearer '+jwt} : {'content-type':'application/json','x-internal-secret':ASK.token||''};
        var cur = (typeof curSym==='function') ? curSym() : '£';
        var system = 'You are a senior D2C growth operator for '+(brand.name||'the brand')+' ('+((brand.markets||'')+' '+(brand.vertical||'')).trim()+') working the CTC "hierarchy of metrics". All monetary values are in '+cur+' — always use '+cur+', never $. '
          + 'You are given the current Overview snapshot: Business (contribution-after-marketing = the arbiter, contribution margin, revenue vs plan + the '+cur+' shortfall); Customer (new-vs-returning mix, per-segment metrics, and acquisitionEconomics = CAC actual vs break-even vs target, ROAS/aMER actual vs target, repeat rate); Channels (per channel: role, spend, incremental revenue, contribution, iROAS vs targetIroas, marginalIroas, verdict — read a POSITIVE iROAS-minus-target gap as over-efficient / UNDER-spending, and a NEGATIVE gap as inefficient / OVER-spending); when present, metaCampaigns and metaTopAds give the ACTUAL Meta campaign- and ad-level performance (name, spend, ROAS, CVR %, frequency, roas_change_pct vs the prior period, fatigue_flag); googleCampaigns give Google Search/PMax performance including impression_share_pct and lost_to_budget_pct (a HIGH lost_to_budget_pct on a profitable campaign is the CLEAN PROOF of under-spending / a volume problem — quote it), and googleWasteTerms are search queries with spend but zero conversions; plus pre-computed insights per tier and the single highest-priority action. '
          + 'Write a SPECIFIC diagnostic read of 3-4 sentences (~70-100 words), plain prose — no lists, no headings, no markdown, no greeting. Follow the CTC logic and NAME NAMES: '
          + '(1) Lead with the business result for this '+(tf||'')+' window — contribution-after-marketing and whether it is ahead or behind PLAN, with the '+cur+' gap. '
          + '(2) DECOMPOSE the gap: state whether it is a VOLUME problem (too little profitable spend / too few new customers) or an EFFICIENCY problem (cost per new customer or real return on ad spend off target) — say which. '
          + '(3) PINPOINT the driver by NAME, preferring the actual campaign/ad over the generic channel: quote the specific Meta campaign or ad/creative from metaCampaigns/metaTopAds, or the Google campaign from googleCampaigns. When a Google campaign is the culprit, ALSO cite its impression-share signal from googleCampaigns — a high lost_to_rank_pct means it is uncompetitive (efficiency: fix creative/bids or cut), a high lost_to_budget_pct on a profitable campaign means under-spend (volume: fund it) — and, if any exist, name one googleWasteTerms query bleeding spend at zero conversions. Quote the real numbers (ROAS, CVR, frequency, roas_change_pct, impression share). Also weigh the customer segment (new vs returning, CAC vs target); lean on computedInsights. '
          + '(4) End on ONE specific lever: the precise reallocation or creative/campaign move, with the '+cur+' contribution impact if available. '
          + 'Never say "hold course" if any channel or campaign is off target or the business is behind plan. Be concrete, quantitative, operator-to-operator. Output only the read.';
        var user = 'Snapshot JSON:\n'+JSON.stringify(compact)+'\n\nWrite the diagnostic read now.';
        var resp = await fetch(ASK.endpoint, { method:'POST', headers, body: JSON.stringify({ system: system, messages:[{role:'user', content:user}], model:'claude-sonnet-4-5', brand_id: ASK.brand_id }) });
        if(!resp.ok){ throw new Error(String(resp.status)); }
        var data = await resp.json();
        if(data.error){ throw new Error(data.detail||data.error); }
        var out = (data.text||'').trim();
        if(!out){ throw new Error('empty'); }
        setTxt(out); try{ sessionStorage.setItem(key, out); }catch(e){}
      }catch(e){ setErr('unavailable'); }
      finally{ setLoading(false); }
    })();
  }, [d && d.periodLabel, tf, (d && Array.isArray(d.channel)) ? d.channel.length : 0, (d && d.pacing) ? d.pacing.revActual : null]);

  if(err==='nollm') return null;   // public / no-auth workspace: no relay, skip silently
  return (
    <div style={{background:GO_T.panel, border:'1px solid '+GO_T.line, borderRadius:'var(--radius-none)', padding:'13px 16px', margin:'2px 0 6px'}}>
      <div style={{fontSize:'var(--text-xs)', fontWeight:'var(--weight-bold)', letterSpacing:'var(--tracking-wide)', textTransform:'uppercase', color:GO_T.accent, marginBottom:5}}>Performance read</div>
      {(loading && !txt)
        ? <div style={{fontSize:'var(--text-sm)', color:GO_T.mut, fontStyle:'italic'}}>Reading the numbers…</div>
        : txt
          ? <div style={{fontSize:'var(--text-sm)', lineHeight:1.55, color:GO_T.ink}}>{txt}</div>
          : <div style={{fontSize:'var(--text-sm)', color:GO_T.mut}}>Performance read unavailable right now.</div>}
    </div>
  );
}
// Visual channel → campaign → ad drill-down. Reads the granular Meta perf views already in the
// warehouse (vw_meta_campaign_perf_ui / vw_meta_ad_perf_ui) so the operator can SEE which campaign
// and ad the spend goes to, RAG-coloured by ROAS + fatigue. Collapsible under the Channel tier.
function MetaAdDrilldown(){
  const [camps,setCamps]=React.useState(null);
  const [ads,setAds]=React.useState(null);
  const [open,setOpen]=React.useState(function(){ try{ return sessionStorage.getItem('oi_dd_meta')==='1'; }catch(e){ return false; } });
  React.useEffect(function(){
    try{
      var sb=(window.FRKL_LIVE&&window.FRKL_LIVE.sb)||null;
      var b=(window.FRKL_LIVE&&window.FRKL_LIVE.brandId)||null;
      if(!sb||!b) return;
      sb.from('vw_meta_campaign_perf_ui').select('campaign_name,spend,revenue,roas,cvr_pct,avg_frequency').eq('brand_id',b).order('spend',{ascending:false}).then(function(r){ if(r&&r.data&&r.data.length) setCamps(r.data); });
      sb.from('vw_meta_ad_perf_ui').select('ad_name,call_to_action,spend,roas,cvr_pct,avg_frequency,roas_change_pct,fatigue_flag').eq('brand_id',b).order('spend',{ascending:false}).limit(12).then(function(r){ if(r&&r.data&&r.data.length) setAds(r.data); });
    }catch(e){}
  },[]);
  if(!camps && !ads) return null;
  var roasCol=function(v){ return v==null?GO_T.dim : (v>=1.5?GO_T.green : (v>=1.0?GO_T.amber : GO_T.red)); };
  var th={textAlign:'right',color:GO_T.dim,fontWeight:'var(--weight-medium)',fontSize:'var(--text-xs)',textTransform:'uppercase',letterSpacing:'var(--tracking-wide)',padding:'6px 8px',borderBottom:'1px solid '+GO_T.line};
  var thL=Object.assign({},th,{textAlign:'left'});
  var td={textAlign:'right',fontFamily:GO_T.mono,fontSize:'var(--text-sm)',padding:'6px 8px',borderBottom:'1px solid '+GO_T.line};
  var tdL={textAlign:'left',fontSize:'var(--text-sm)',padding:'6px 8px',borderBottom:'1px solid '+GO_T.line};
  return (<div style={{marginTop:10}}>
    <div onClick={function(){ var n=!open; setOpen(n); try{sessionStorage.setItem('oi_dd_meta', n?'1':'0');}catch(e){} }} style={{cursor:'pointer',fontSize:'var(--text-xs)',color:GO_T.accent2,textTransform:'uppercase',letterSpacing:'var(--tracking-wide)',margin:'0 2px 6px',userSelect:'none'}}>
      <Icon name="chevron" size={12} style={{transform:open?'rotate(90deg)':'none', transition:'transform .15s', verticalAlign:'-1px', marginRight:'var(--space-2)'}}/>Meta campaign &amp; ad detail — where the paid-social spend actually goes
    </div>
    {open && <div>
      <div style={{fontSize:'var(--text-xs)',color:GO_T.dim,margin:'0 2px 8px',fontStyle:'italic'}}>return on ad spend below is raw / platform-reported; the Channel tier above uses incrementality-adjusted real return on ad spend, so the numbers differ.</div>
      {camps && <div style={{marginBottom:12}}>
        <div style={{fontSize:'var(--text-xs)',color:GO_T.mut,margin:'0 2px 4px'}}>Campaigns · last 30 days</div>
        <table style={{width:'100%',borderCollapse:'collapse'}}>
          <thead><tr><th style={thL}>Campaign</th><th style={th}>Spend</th><th style={th}>Claimed return</th><th style={th}>Visitors who buy</th><th style={th}>Freq</th></tr></thead>
          <tbody>{camps.map(function(c,i){return (<tr key={i}>
            <td style={tdL}>{c.campaign_name}</td>
            <td style={td}>{GO_gbp(c.spend)}</td>
            <td style={Object.assign({},td,{color:roasCol(c.roas)})}>{c.roas!=null?c.roas.toFixed(2)+'×':'—'}</td>
            <td style={td}>{c.cvr_pct!=null?c.cvr_pct+'%':'—'}</td>
            <td style={Object.assign({},td,{color:(c.avg_frequency>=5?GO_T.red:GO_T.ink)})}>{c.avg_frequency!=null?c.avg_frequency.toFixed(1)+'×':'—'}</td>
          </tr>);})}</tbody>
        </table>
      </div>}
      {ads && <div>
        <div style={{fontSize:'var(--text-xs)',color:GO_T.mut,margin:'0 2px 4px'}}>Top ads by spend · return on ad spend vs prior 30d</div>
        <table style={{width:'100%',borderCollapse:'collapse'}}>
          <thead><tr><th style={thL}>Ad</th><th style={th}>Spend</th><th style={th}>Claimed return</th><th style={th}>{'Δ'} vs prior</th><th style={th}>Visitors who buy</th><th style={th}>Freq</th></tr></thead>
          <tbody>{ads.map(function(a,i){return (<tr key={i}>
            <td style={Object.assign({},tdL,{maxWidth:230,overflow:'hidden',textOverflow:'ellipsis',whiteSpace:'nowrap'})}>{a.ad_name}{a.fatigue_flag?<span style={{color:GO_T.red,fontSize:'var(--text-xs)'}}> {'·'} fatigue</span>:null}</td>
            <td style={td}>{GO_gbp(a.spend)}</td>
            <td style={Object.assign({},td,{color:roasCol(a.roas)})}>{a.roas!=null?a.roas.toFixed(2)+'×':'—'}</td>
            <td style={Object.assign({},td,{color:(a.roas_change_pct!=null?(a.roas_change_pct<0?GO_T.red:GO_T.green):GO_T.dim)})}>{a.roas_change_pct!=null?((a.roas_change_pct>0?'+':'')+a.roas_change_pct+'%'):'—'}</td>
            <td style={td}>{a.cvr_pct!=null?a.cvr_pct+'%':'—'}</td>
            <td style={Object.assign({},td,{color:(a.avg_frequency>=5?GO_T.red:GO_T.ink)})}>{a.avg_frequency!=null?a.avg_frequency.toFixed(1)+'×':'—'}</td>
          </tr>);})}</tbody>
        </table>
      </div>}
    </div>}
  </div>);
}
// Google drill-down — campaign impression-share (lost-to-budget = under-spend proof) + wasteful
// search terms (spend, zero conversions). Empty until the extended sync-google-ads runs.
function GoogleAdDrilldown(){
  const [camps,setCamps]=React.useState(null);
  const [waste,setWaste]=React.useState(null);
  const [open,setOpen]=React.useState(function(){ try{ return sessionStorage.getItem('oi_dd_google')==='1'; }catch(e){ return false; } });
  React.useEffect(function(){
    try{
      var sb=(window.FRKL_LIVE&&window.FRKL_LIVE.sb)||null;
      var b=(window.FRKL_LIVE&&window.FRKL_LIVE.brandId)||null;
      if(!sb||!b) return;
      sb.from('vw_google_campaign_perf_ui').select('campaign_name,channel_type,spend,roas,cvr_pct,impression_share_pct,lost_to_budget_pct').eq('brand_id',b).order('spend',{ascending:false}).then(function(r){ if(r&&r.data&&r.data.length) setCamps(r.data); });
      sb.from('vw_google_search_terms_ui').select('search_term,campaign_name,spend,conversions,roas,zero_conv_waste').eq('brand_id',b).eq('zero_conv_waste',true).order('spend',{ascending:false}).limit(10).then(function(r){ if(r&&r.data&&r.data.length) setWaste(r.data); });
    }catch(e){}
  },[]);
  if(!camps && !waste) return null;
  var roasCol=function(v){ return v==null?GO_T.dim : (v>=1.5?GO_T.green : (v>=1.0?GO_T.amber : GO_T.red)); };
  var th={textAlign:'right',color:GO_T.dim,fontWeight:'var(--weight-medium)',fontSize:'var(--text-xs)',textTransform:'uppercase',letterSpacing:'var(--tracking-wide)',padding:'6px 8px',borderBottom:'1px solid '+GO_T.line};
  var thL=Object.assign({},th,{textAlign:'left'});
  var td={textAlign:'right',fontFamily:GO_T.mono,fontSize:'var(--text-sm)',padding:'6px 8px',borderBottom:'1px solid '+GO_T.line};
  var tdL={textAlign:'left',fontSize:'var(--text-sm)',padding:'6px 8px',borderBottom:'1px solid '+GO_T.line};
  return (<div style={{marginTop:8}}>
    <div onClick={function(){ var n=!open; setOpen(n); try{sessionStorage.setItem('oi_dd_google', n?'1':'0');}catch(e){} }} style={{cursor:'pointer',fontSize:'var(--text-xs)',color:GO_T.accent2,textTransform:'uppercase',letterSpacing:'var(--tracking-wide)',margin:'0 2px 6px',userSelect:'none'}}>
      <Icon name="chevron" size={12} style={{transform:open?'rotate(90deg)':'none', transition:'transform .15s', verticalAlign:'-1px', marginRight:'var(--space-2)'}}/>Google campaign &amp; search-term detail — impression share &amp; wasted spend
    </div>
    {open && <div>
      <div style={{fontSize:'var(--text-xs)',color:GO_T.dim,margin:'0 2px 8px',fontStyle:'italic'}}>return on ad spend below is raw / platform-reported; the Channel tier above uses incrementality-adjusted real return on ad spend, so the numbers differ.</div>
      {camps && <div style={{marginBottom:12}}>
        <div style={{fontSize:'var(--text-xs)',color:GO_T.mut,margin:'0 2px 4px'}}>Campaigns · last 30 days · lost-to-budget = under-spend on demand you could capture</div>
        <table style={{width:'100%',borderCollapse:'collapse'}}>
          <thead><tr><th style={thL}>Campaign</th><th style={th}>Spend</th><th style={th}>Claimed return</th><th style={th}>Visitors who buy</th><th style={th}>Impr share</th><th style={th}>Lost {'→'} budget</th></tr></thead>
          <tbody>{camps.map(function(c,i){return (<tr key={i}>
            <td style={tdL}>{c.campaign_name}{c.channel_type?<span style={{color:GO_T.dim,fontSize:'var(--text-xs)'}}> {'·'} {String(c.channel_type).toLowerCase()}</span>:null}</td>
            <td style={td}>{GO_gbp(c.spend)}</td>
            <td style={Object.assign({},td,{color:roasCol(c.roas)})}>{c.roas!=null?c.roas.toFixed(2)+'×':'—'}</td>
            <td style={td}>{c.cvr_pct!=null?c.cvr_pct+'%':'—'}</td>
            <td style={td}>{c.impression_share_pct!=null?c.impression_share_pct+'%':'—'}</td>
            <td style={Object.assign({},td,{color:(c.lost_to_budget_pct>=10?GO_T.red:(c.lost_to_budget_pct>=3?GO_T.amber:GO_T.ink))})}>{c.lost_to_budget_pct!=null?c.lost_to_budget_pct+'%':'—'}</td>
          </tr>);})}</tbody>
        </table>
      </div>}
      {waste && <div>
        <div style={{fontSize:'var(--text-xs)',color:GO_T.mut,margin:'0 2px 4px'}}>Wasteful search terms · spend, zero conversions (30d)</div>
        <table style={{width:'100%',borderCollapse:'collapse'}}>
          <thead><tr><th style={thL}>Search term</th><th style={thL}>Campaign</th><th style={th}>Spend</th></tr></thead>
          <tbody>{waste.map(function(t,i){return (<tr key={i}>
            <td style={tdL}>{t.search_term}</td>
            <td style={Object.assign({},tdL,{color:GO_T.mut})}>{t.campaign_name||'—'}</td>
            <td style={Object.assign({},td,{color:GO_T.red})}>{GO_gbp(t.spend)}</td>
          </tr>);})}</tbody>
        </table>
      </div>}
    </div>}
  </div>);
}
function GretaOverviewTiers(){
  const [tf,setTf] = React.useState('monthly');
  const [,GO_force] = React.useState(0);
  React.useEffect(function(){ var h=function(){ GO_force(function(x){return x+1;}); };
    window.addEventListener('frkl-overview-updated', h);
    window.addEventListener('frkl-data-updated', h);
    return function(){ window.removeEventListener('frkl-overview-updated', h); window.removeEventListener('frkl-data-updated', h); };
  },[]);
  const isFrkl = (typeof window!=='undefined' && window.OI_BRAND && window.OI_BRAND.slug==='frkl');
  const live = (typeof window!=='undefined' && window.FRKL_OVERVIEW) || null;
  // The frkl fallback tiles were retired on 2026-09-25: with no live data every brand
  // now sees the same 'connect your sources' state rather than another brand's numbers.
  const src = live;
  const d = React.useMemo(()=> src ? (src[tf]||src.monthly||null) : null, [src,tf]);

  const wrap = { maxWidth:1180, margin:'0 auto', padding:'8px 4px 60px', background:GO_T.bg, color:GO_T.ink };
  const toggle = (
    <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',marginTop:6,marginBottom:6}}>
      <div style={{fontSize:'var(--text-sm)',color:GO_T.dim}}>{d?('Snapshot · '):''}{d && <span style={{fontFamily:GO_T.mono}}>{d.periodLabel}</span>} {d?d.compareLabel:''}</div>
      <div className="go-tf" style={{display:'inline-flex',background:GO_T.panel,border:'1px solid '+GO_T.line,borderRadius:'var(--radius-none)',padding:3}}>
        {GO_TIMEFRAMES.map(x=> <button key={x} onClick={()=>setTf(x)} style={{background:x===tf?GO_T.accent:'none',color:x===tf?PAL.panel:GO_T.mut,fontWeight:x===tf?'var(--weight-semi)':'var(--weight-normal)',border:0,fontSize:'var(--text-sm)',padding:'6px 12px',borderRadius:'var(--radius-md)',cursor:'pointer',textTransform:'capitalize'}}>{x}</button>)}
      </div>
    </div>);

  if(!d) return (
    <div style={wrap}>{toggle}
      <div style={{background:GO_T.panel,border:'1px solid '+GO_T.line,borderRadius:'var(--radius-none)',padding:'26px',textAlign:'center',color:GO_T.mut,marginTop:10}}>
        Overview is loading this brand's live data. <GoLink sec="settings" sub="connections">Connect Shopify, GA4, Meta, Google &amp; Klaviyo</GoLink> to populate the tiers.
      </div>
    </div>);

  return (
    <div style={wrap}>
      {toggle}
      <TrackRecord/>
      <div style={{background:'linear-gradient(180deg,'+GO_T.panel+','+GO_T.panel2+')',border:'1px solid '+GO_T.line,borderRadius:'var(--radius-none)',padding:'20px 24px',margin:'8px 0 6px',display:'flex',justifyContent:'space-between',gap:24,flexWrap:'wrap'}}>
        <div>
          <div style={{fontSize:'var(--text-xs)',letterSpacing:'var(--tracking-wide)',textTransform:'uppercase',color:GO_T.dim}}>Profit after ads · this period</div>
          <div style={{fontFamily:GO_T.mono,fontSize:'var(--text-data)',fontWeight:'var(--weight-semi)',margin:'4px 0 2px',letterSpacing:'var(--tracking-tight)'}}>{GO_gbp(d.hero.cmAfterMkt)}</div>
          <div style={{fontSize:'var(--text-sm)',color:GO_T.mut}}>CM {GO_gbp(d.hero.cm)} ({d.hero.cmPct}%) − ad spend {GO_gbp(d.hero.spend)}{d.hero.targetEstimated && <span style={{color:GO_T.amber}}> · target auto-estimated — not yet confirmed</span>}</div>
        {d.hero.opProfit!=null && d.hero.fixedMonthly>0 && <div style={{fontSize:'var(--text-sm)',marginTop:2,color:(d.hero.opProfit>=0?GO_T.green:GO_T.red)}}>{'Operating profit '+GO_gbp(d.hero.opProfit)+' · after '+GO_gbp(d.hero.fixedMonthly)+'/mo fixed costs'}</div>}
        {d.pacing && (function(){
          var pct=d.pacing.pacePct;
          var col = pct==null?GO_T.mut : pct>=-5?GO_T.green : pct>=-15?GO_T.amber : GO_T.red;
          var lab = pct==null?'No pace yet' : pct>=5?'Ahead of plan' : pct>=-5?'On track' : pct>=-15?'Watch' : 'Behind plan';
          var fill = pct==null?0:Math.max(0,Math.min(140,100+pct));
          return (
          <div style={{marginTop:10, maxWidth:470}}>
            <div style={{display:'flex',alignItems:'center',gap:9,marginBottom:5,flexWrap:'wrap'}}>
              <span style={{display:'inline-flex',alignItems:'center',background:col,color:PAL.panel,fontSize:'var(--text-xs)',fontWeight:'var(--weight-bold)',letterSpacing:'var(--tracking-wide)',padding:'2px 10px',borderRadius:'var(--radius-md)'}}>{lab.toUpperCase()}</span>
              <span style={{fontSize:'var(--text-sm)',color:GO_T.mut}}>{GO_gbp(d.pacing.revActual)+' of '+GO_gbp(d.pacing.revTarget)+' expected to date'+(pct!=null?(' · '+(pct>=0?'+':'')+pct+'%'):'')}</span>
            </div>
            <div style={{position:'relative',height:8,borderRadius:'var(--radius-none)',background:'var(--color-surface)',overflow:'hidden'}}>
              <div style={{position:'absolute',left:0,top:0,bottom:0,width:(fill/140*100)+'%',background:col,opacity:.9}}/>
              <div style={{position:'absolute',left:(100/140*100)+'%',top:-1,bottom:-1,width:2,background:GO_T.dim}}/>
            </div>
            <div style={{fontSize:'var(--text-xs)',color:GO_T.dim,marginTop:4}}>{d.pacing.goalConfirmed ? 'vs your confirmed plan · the mark is exactly on pace' : <>vs auto-estimated target — <GoLink sec="home" sub="plansetup">confirm it in Goal &amp; costs</GoLink> · the mark is exactly on pace</>}</div>
          </div>);
        })()}
        </div>
        <div style={{minWidth:300,flex:1,background:'var(--color-panel)',border:'1px solid '+GO_T.line,borderRadius:'var(--radius-none)',padding:'13px 15px'}}>
          <div><span style={{fontSize:'var(--text-xs)',fontFamily:GO_T.mono,letterSpacing:'var(--tracking-wide)',color:GO_T.accent2,border:`1px solid ${PAL.panel}`,borderRadius:'var(--radius-md)',padding:'1px 6px',marginRight:6}}>DO FIRST</span><span style={{fontSize:'var(--text-xs)',fontFamily:GO_T.mono,letterSpacing:'var(--tracking-wide)',color:GO_T.red,border:'1px solid #4a2b2b',borderRadius:'var(--radius-md)',padding:'1px 6px'}}>{d.hero.action.value}</span></div>
          <h3 style={{margin:'8px 0 5px',fontSize:'var(--text-base)'}}>{d.hero.action.title}</h3>
          <p style={{margin:0,color:GO_T.mut,fontSize:'var(--text-sm)'}}>{d.hero.action.why}</p>
        </div>
      </div>
      <div style={{fontSize:'var(--text-xs)',color:GO_T.dim,margin:'4px 2px 0'}}>Factual read of synced Shopify · GA4 · Meta · Google · Klaviyo — not a projection. RAG is vs target; arrows vs previous period.</div>

      <OverviewSummary d={d} tf={tf}/>

      <div style={{margin:'28px 0 10px'}}>
        <GO_TierHead n="01" title="Business" sub="how the business is performing"/>
        {/* Column count follows the tile count (+1 for Best sellers) so every row is full:
            twelve tiles in five columns left a row of two and overflowed a laptop-width column. */}
        <div className="go-tile-grid" data-cols={GO_cols(d.business.length+1)} style={{display:'grid',gap:12,gridTemplateColumns:'repeat('+GO_cols(d.business.length+1)+',minmax(0,1fr))'}}>
          {d.business.map((t,i)=><GO_Tile key={i} t={t}/>)}
          <div style={{background:'var(--color-surface)',border:`1px solid ${PAL.panel}`,borderRadius:'var(--radius-none)',padding:'14px 15px'}}>
            <div style={{fontSize:'var(--text-xs)',color:GO_T.mut}}>Best sellers →</div>
            <div style={{fontSize:'var(--text-sm)',color:GO_T.mut,marginTop:6,lineHeight:1.7}}>{d.bestSellers.map((s,i)=><div key={i}>{s.name} · {GO_gbp(s.rev)}</div>)}</div>
          </div>
        </div>
        {d.pacing && d.pacing.days && d.pacing.days.length>0 && <div style={{background:GO_T.panel,border:'1px solid '+GO_T.line,borderRadius:'var(--radius-none)',padding:'10px 12px 4px',boxShadow:'var(--shadow-panel)',marginTop:10}}><div style={{fontSize:'var(--text-xs)',color:GO_T.dim,textTransform:'uppercase',letterSpacing:'var(--tracking-wide)',marginBottom:6}}>Sales &amp; spend vs target</div><R.ResponsiveContainer width="100%" height={160}><R.ComposedChart data={d.pacing.days} margin={{top:5,right:8,left:0,bottom:0}}><R.CartesianGrid strokeDasharray="2 4" stroke={PAL.line}/><R.XAxis dataKey="date" tick={{fontSize:'var(--text-xs)',fill:'var(--color-muted)'}} interval="preserveStartEnd"/><R.YAxis tick={{fontSize:'var(--text-xs)',fill:'var(--color-muted)'}} width={44} tickFormatter={function(v){return '£'+Math.round(v/1000)+'k';}}/><R.Tooltip formatter={function(v){return '£'+Number(v).toLocaleString('en-GB');}}/><R.Bar dataKey="sales" name="Sales" fill={PAL.good} radius={[2,2,0,0]}/><R.Bar dataKey="spend" name="Spend" fill={PAL.accent} radius={[2,2,0,0]}/><R.Line dataKey="tSales" name="Target sales" stroke="var(--color-success)" strokeDasharray="4 3" dot={false} strokeWidth={1.5}/><R.Line dataKey="tSpend" name="Target spend" stroke={PAL.accent} strokeDasharray="4 3" dot={false} strokeWidth={1.5}/></R.ComposedChart></R.ResponsiveContainer></div>}
        <GO_Insight i={d.insights.business}/>
      </div>

      <div style={{margin:'28px 0 10px'}}>
        <GO_TierHead n="02" title="Customer" sub="returning · new · paid-incremental (CTC)"/>
        <div style={{background:GO_T.panel,border:'1px solid '+GO_T.line,borderRadius:'var(--radius-none)',padding:'13px 15px',boxShadow:'var(--shadow-panel)',marginBottom:10}}>
          <div style={{fontSize:'var(--text-xs)',color:GO_T.mut,marginBottom:6}}>New vs returning revenue</div>
          <div style={{display:'flex',height:9,borderRadius:'var(--radius-md)',overflow:'hidden',marginBottom:6}}><div style={{width:d.customer.splitNew+'%',background:GO_T.accent}}/><div style={{width:d.customer.splitRet+'%',background:PAL.data3}}/></div>
          <div style={{fontFamily:GO_T.mono,fontSize:'var(--text-xs)'}}><span style={{color:GO_T.accent}}>New {d.customer.splitNew}% · {GO_gbp(d.customer.newRev)}</span> &nbsp; <span style={{color:PAL.data3}}>Ret {d.customer.splitRet}% · {GO_gbp(d.customer.retRev)}</span></div>
        </div>
        {(d.customer.rows||[]).map(function(row,ri){return (
          <div key={ri} style={{marginTop:ri>0?20:2,marginBottom:6}}>
            <div style={{display:'flex',alignItems:'center',gap:8,margin:'0 0 10px',paddingBottom:7,borderBottom:'1px solid '+GO_T.line}}><GO_Dot r={row.rag}/> <span style={{fontSize:'var(--text-sm)',fontWeight:'var(--weight-bold)',color:GO_T.ink,letterSpacing:'var(--tracking-wide)'}}>{row.label}</span></div>
            <div style={{display:'grid',gridTemplateColumns:'repeat(auto-fill,minmax(200px,1fr))',gap:12}}>
              {row.cells.map(function(c,ci){var ex=GO_EXPLAIN[c.k];return <div key={ci} className="go-tile" style={{background:GO_T.panel,border:'1px solid '+GO_T.line,borderRadius:'var(--radius-none)',padding:'14px 15px',boxShadow:'var(--shadow-panel)'}}><div style={{fontSize:'var(--text-xs)',color:GO_T.mut}}>{c.k}</div><div style={{fontFamily:GO_T.mono,fontSize:'var(--text-xl)',fontWeight:'var(--weight-semi)',margin:'8px 0 4px'}}>{c.v}</div>{ex&&<div className="go-pop"><div className="go-head">{row.label} · {c.k}</div><div style={{fontSize:'var(--text-xs)',color:GO_T.mut,lineHeight:1.5}}>{ex}</div></div>}</div>;})}
            </div>
          </div>);})}
                {d.cacBlock && (function(){ var C=d.cacBlock;
          var g2=function(x){return fmtMoney(x,2);};
          var rx=function(x){return x==null?"—":Number(x).toFixed(2)+"×";};
          var col=C.rag==="g"?GO_T.green:C.rag==="a"?GO_T.amber:C.rag==="r"?GO_T.red:GO_T.dim;
          var cell=function(k,v,sub,hi){var ex=GO_EXPLAIN[(String(v).indexOf("×")>=0?"return on ad spend:":"cost per new customer:")+k]||GO_EXPLAIN[k]||"";return <div className="go-tile" style={{background:GO_T.panel,border:"1px solid "+(hi||GO_T.line),borderRadius:'var(--radius-none)',padding:"14px 15px",boxShadow:"var(--shadow-panel)"}}><div style={{fontSize:'var(--text-xs)',color:GO_T.mut}}>{k}</div><div style={{fontFamily:GO_T.mono,fontSize:'var(--text-xl)',fontWeight:'var(--weight-semi)',margin:"8px 0 4px"}}>{v}</div><div style={{fontSize:'var(--text-xs)',color:GO_T.dim}}>{sub}</div>{ex&&<div className="go-pop"><div className="go-head">{k}</div><div style={{fontSize:'var(--text-xs)',color:GO_T.mut,lineHeight:1.5}}>{ex}</div></div>}</div>;};
          var ltvSub=C.opc.toFixed(2)+" orders/cust"+(C.repeatPct!=null?" · "+C.repeatPct+"% repeat":"");
          var tgtSub=C.goalConfirmed?"from your goal":"profit-safe default";
          return <div style={{marginTop:2,marginBottom:6}}>
            <div style={{fontSize:'var(--text-xs)',color:GO_T.dim,textTransform:"uppercase",letterSpacing:'var(--tracking-wide)',margin:"0 2px 6px"}}>Acquisition efficiency · break-even &amp; optimal</div>
            <div style={{fontSize:'var(--text-xs)',color:GO_T.mut,margin:"0 2px 4px"}}>cost per new customer — most you can pay per new customer</div>
            <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(200px,1fr))",gap:12,marginBottom:9}}>
              {cell("New-customer cost (paid)",g2(C.cac.actual),"spend ÷ new custs",col)}
              {cell("Break-even · 1st order",g2(C.cac.first),"CM-positive on order 1")}
              {cell("Break-even · lifetime",g2(C.cac.ltv),ltvSub)}
              {cell("Target / optimal cost per new customer",g2(C.cac.target),tgtSub)}
            </div>
            <div style={{fontSize:'var(--text-xs)',color:GO_T.mut,margin:"0 2px 4px"}}>return on ad spend — least you can accept (sales per £ of ads for new customers)</div>
            <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(200px,1fr))",gap:12}}>
              {cell("Actual return on ad spend (sales per £ of ads for new customers)",rx(C.roas.actual),"new rev ÷ spend",col)}
              {cell("Break-even · 1st order",rx(C.roas.first),"= 1 ÷ contribution")}
              {cell("Break-even · lifetime",rx(C.roas.ltv),"customer lifetime value-adjusted floor")}
              {cell("Target / optimal return on ad spend",rx(C.roas.target),tgtSub)}
            </div>
            <div style={{fontSize:'var(--text-xs)',color:col,marginTop:7,display:"flex",gap:6,alignItems:"baseline"}}><GO_Dot r={C.rag} style={{marginTop:4}}/> <span>{C.verdict}</span></div>
          </div>; })()}
        <GO_Insight i={d.insights.customer}/>
      </div>

      <div style={{margin:'28px 0 10px'}}>
        <GO_TierHead n="03" title="Channel" sub="avg vs marginal real return on ad spend — where the next £ goes (CTC)"/>
        <div style={{background:GO_T.panel,border:'1px solid '+GO_T.line,borderRadius:'var(--radius-none)',padding:'2px 4px',overflowX:'auto'}}>
          <table style={{width:'100%',borderCollapse:'collapse',fontSize:'var(--text-sm)'}}>
            <thead><tr>{['Channel','Spend','Incr rev','CM','iROAS','Marginal','Verdict'].map((h,i)=><th key={i} style={{textAlign:i===0?'left':'right',color:GO_T.dim,fontWeight:'var(--weight-medium)',fontSize:'var(--text-xs)',textTransform:'uppercase',letterSpacing:'var(--tracking-wide)',padding:'8px 9px',borderBottom:'1px solid '+GO_T.line}}>{h}</th>)}</tr></thead>
            <tbody>{d.channel.map((c,i)=>(
              <tr key={i} style={{background:c.family==='email'?'var(--color-surface)':'none'}}>
                <td style={{textAlign:'left',padding:'8px 9px',borderBottom:'1px solid '+GO_T.line}}>{c.name} <span style={{fontSize:'var(--text-xs)',color:c.family==='email'?GO_T.accent2:GO_T.mut}}>{c.family==='email'?'email':(c.acquisition?'acq':'retn')}{c.phi!=null?' · φ'+c.phi:''}</span></td>
                <td style={{textAlign:'right',fontFamily:GO_T.mono,padding:'8px 9px',borderBottom:'1px solid '+GO_T.line}}>{GO_gbp(c.spend)}</td>
                <td style={{textAlign:'right',fontFamily:GO_T.mono,padding:'8px 9px',borderBottom:'1px solid '+GO_T.line}}>{GO_gbp(c.incRev)}</td>
                <td style={{textAlign:'right',fontFamily:GO_T.mono,color:(c.contribution!=null&&c.contribution<0)?GO_T.red:GO_T.ink,padding:'8px 9px',borderBottom:'1px solid '+GO_T.line}}>{c.contribution!=null?GO_gbp(c.contribution):'—'}</td>
                <td style={{textAlign:'right',fontFamily:GO_T.mono,color:c.rag==='r'?GO_T.red:c.rag==='g'?GO_T.green:GO_T.ink,padding:'8px 9px',borderBottom:'1px solid '+GO_T.line}}>{c.iroas!=null?c.iroas.toFixed(2)+'×':'—'}</td>
                <td style={{textAlign:'right',fontFamily:GO_T.mono,color:c.marginal!=null?(c.marginal>=c.tgt?GO_T.green:GO_T.amber):GO_T.dim,padding:'8px 9px',borderBottom:'1px solid '+GO_T.line}}>{c.marginal!=null?c.marginal.toFixed(2)+'×':'—'}</td>
                <td style={{textAlign:'right',fontSize:'var(--text-xs)',padding:'8px 9px',borderBottom:'1px solid '+GO_T.line}}><GO_Dot r={c.rag}/> {c.verdict}</td>
              </tr>))}</tbody>
          </table>
        </div>
        {d.emailBlock && (function () { var E = d.emailBlock; var cell = function (k, v, sub) { return <div style={{ background: GO_T.panel, border: '1px solid ' + GO_T.line, borderRadius:'var(--radius-none)', padding: '9px 11px', boxShadow: 'var(--shadow-panel)' }}><div style={{ fontSize: 'var(--text-xs)', color: GO_T.mut }}>{k}</div><div style={{ fontFamily: GO_T.mono, fontSize: 'var(--text-base)', fontWeight:'var(--weight-semi)', marginTop: 2 }}>{v}</div><div style={{ fontSize: 'var(--text-xs)', color: GO_T.dim }}>{sub}</div></div>; }; return <div style={{ marginTop: 10 }}><div style={{ fontSize: 'var(--text-xs)', color: GO_T.dim, textTransform: 'uppercase', letterSpacing: 'var(--tracking-wide)', margin: '0 2px 6px' }}>Email breakdown · Klaviyo</div><div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill,minmax(130px,1fr))', gap: 8 }}>{cell('Email revenue', GO_gbp(E.total_rev), E.total_orders + ' orders')}{cell('Campaign rev', GO_gbp(E.campaign_rev), E.campaign_orders + ' orders')}{cell('Flow rev', GO_gbp(E.flow_rev), E.flow_orders + ' orders')}{cell('Rev / 1k sent', GO_gbp(E.rev_per_1k_sent), Math.round(E.total_sends / 1000) + 'k sent')}</div></div>; })()}
        <GO_Insight i={d.insights.channel}/>
        <MetaAdDrilldown/>
        <GoogleAdDrilldown/>
      </div>
    </div>);
}

// ── Plan panel (readiness gate + target setter) ──────────────────────────────
// Added 2026-07-14. Wires steps 1-2 of the targets workstream: shows the plan-readiness
// gate (vw_brand_plan_readiness), lets the user set a quarter goal in EITHER contribution
// (CAM) or revenue and see the full derived target set (both units), then confirm it as the
// plan of record (mos_business_goal.confirmed=true). Global-scope, GP_* namespaced. Data +
// writes live in window.FRKL_PLAN (greta-plan-data.js). Confirm is user-initiated only.
// Same as GO_T: these values are used in the spend-curve SVG as well as in styles.
var GP_T = { bg:'transparent', panel:PAL.panel, panel2:PAL.surface, line:PAL.line, ink:PAL.ink,
  mut:PAL.muted, dim:PAL.faint, accent:PAL.accent, accent2:PAL.accent, green:PAL.good, amber:PAL.warn, red:PAL.bad,
  mono:'var(--font-mono)' };
var GP_gbp = function (x) { return fmtMoney(x); };
var GP_rag = function (s) { return s === 'ready' ? GP_T.green : s === 'unconfirmed' || s === 'stale' ? GP_T.amber : GP_T.red; };

function GP_Dot(p) { return React.createElement('span', { style: { width: 8, height: 8, borderRadius: '50%', display: 'inline-block', background: p.c } }); }
// vw_brand_plan_readiness names its checks for an analyst ("Paid efficiency (φ/iROAS)", "Cohort
// LTV"). The view keeps its keys; the owner reads these.
const GP_PLAIN_ITEM = {
  'Gross margin': 'Margin on products without a cost',
  'Variable costs': 'Per-order costs',
  'Fixed costs / month': 'Monthly overheads',
  'Discount rate (annual)': 'Cost of money',
  'Contribution margin %': 'Profit before ads, % of sales',
  'New-customer CAC': 'New-customer cost',
  'Cohort LTV': 'What a customer is worth over time',
  'Returning-revenue run-rate': 'Sales from returning customers',
  'Quarter goal set': 'A goal for this quarter',
  'Goal confirmed as plan': 'Goal confirmed',
  'Paid efficiency (φ/iROAS)': 'What ad channels really earn',
  'Email data (for email effect)': 'Email data',
  'Sales feed fresh': 'Sales data up to date',
};

// The view's detail column is shorthand ("set 78%", "86 returning-days (90d)"). Say the
// answer instead; anything unrecognised falls through with money and dates formatted.
function GP_plainDetail(r) {
  var d = String(r.detail || '');
  var m;
  if (r.status !== 'ready' && !r.blocks_targets) return 'Optional';
  if (d === 'set') return 'Entered';
  if ((m = d.match(/^set (\d+(?:\.\d+)?)%$/))) return m[1] + '%';
  if ((m = d.match(/^(\d+) returning-days \((\d+)d\)$/))) return m[1] + ' of ' + m[2] + ' days';
  if ((m = d.match(/^(\d+) paid channels modelled$/))) return m[1] + ' measured';
  if (d === 'no goal for current quarter') return 'Not set';
  if (d === 'goal exists for this period') return 'Set';
  if (d === 'confirmed') return 'Yes';
  if (d === 'set a goal first') return 'After the goal';
  if ((m = d.match(/^(\w+) to (\d{4}-\d{2}-\d{2})$/))) return m[1] + ', to ' + v3Day(m[2], true);
  return v3Money(d).replace(/(\d{4})-(\d{2})-(\d{2})/g, function (x) { return v3Day(x, true); });
}

// The kit's stat tile; hi marks the figures the plan is steered by (accent, not a second style).
function GP_Metric(p) {
  return (
    <div className="v3-stat">
      <div className="v3-stat-lab"><span>{p.k}</span></div>
      <div className="v3-stat-val" style={p.hi ? { color: 'var(--color-accent)' } : undefined}>{p.v}</div>
      {p.sub && <div className="v3-stat-foot"><span className="v3-muted">{p.sub}</span></div>}
    </div>
  );
}

// ── The plan, explained ───────────────────────────────────────────────────────
// Where the quarter's sales come from (returning customers at no ad cost, new customers bought with
// the budget), what each new customer earns against what it costs, the months — the season and
// Black Friday — last year's same quarter, the seasonal pattern used and every caveat the model
// raised. All figures are fn_plan_quarter's (0232); nothing is recomputed here. It replaces
// "Why are these the targets?", whose text was written for the profit basis and printed
// "−£163 ÷ 60% + £25,865 ≈ £150,000" on the sales basis.
const GP_FLAG_TEXT = {
  beyond_spend_seen: 'At least one month asks for more than 1.5× the most you have ever spent on ads in a month. Greta extends your spend curve to get there, so treat that month as a stretch, not a forecast.',
  below_spend_seen: 'At least one month plans less than half the least you have ever spent in a month — below anything the curve has seen.',
  capped_at_spend_seen: 'Greta stopped the growth at three times your biggest month of ad spend: beyond that the curve is guesswork, not evidence.',
  goal_above_max: 'That profit is beyond what Greta can see a way to this quarter, so the plan below is the most profitable one instead.',
  met_by_returning: 'Returning customers alone are on course to reach this, so no ad budget is needed for it.',
  no_ad_history: 'There is no ad-spend history yet, so new-customer sales are carried at their current rate and no budget is planned.',
  short_base: 'There are fewer than three full months of trading behind this, so the starting point is thin.'
};
const GP_MONTH_NAME = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
function gpMonthName(iso) { return GP_MONTH_NAME[Number(String(iso).slice(5, 7)) - 1] || ''; }

function GP_PlanBreakdown({ d }) {
  const st = React.useState(false), open = st[0], setOpen = st[1];
  if (!d || !d.breakdown) return null;   // an old-shaped result (server not updated) renders no breakdown
  const b = d.breakdown, s = d.seasonality || {}, months = d.months || [], ly = d.last_year, ceil = d.ceiling, inp = d.inputs || {};
  const flags = (d.flags || []).filter(f => GP_FLAG_TEXT[f]);
  const retShare = d.revenue_target > 0 ? b.returning_sales / d.revenue_target : null;
  const newPays = b.new_profit_after_ads >= 0;
  const peak = months.length ? months.reduce((a, m) => (Number(m.sales) > Number(a.sales) ? m : a), months[0]) : null;
  const doubling = inp.beta != null ? Math.pow(2, Number(inp.beta)) : null;
  const planMonths = months.map(m => Number(String(m.month).slice(5, 7)));
  const idx = (s.months || []).map(m => Number(m.sales_idx));
  const hi = Math.max(1, ...idx);
  const basisLine = d.basis === 'revenue'
    ? <>You asked for <b>{GP_gbp(d.goal)}</b> of sales. Returning customers bring <b>{GP_gbp(b.returning_sales)}</b> on their own — their recent rate, adjusted for the season. The other <b>{GP_gbp(b.new_sales)}</b> has to come from new customers, and Greta found the ad budget that buys it, given how your new-customer sales respond to spend and when demand peaks.</>
    : d.basis === 'cam' && (d.flags || []).indexOf('goal_above_max') >= 0
    ? <>You asked for <b>{GP_gbp(d.goal)}</b> of profit after ads. That is more than any budget reaches this quarter, so Greta planned the budget that makes the most: past it, each extra pound of ads brings back less than a pound of profit.</>
    : d.basis === 'cam'
    ? <>You asked for <b>{GP_gbp(d.goal)}</b> of profit after ads, and Greta treats it as a floor: this is the most growth that still clears it — the biggest budget at which profit after ads stays at your goal{(d.flags || []).indexOf('capped_at_spend_seen') >= 0 ? ', stopped at three times your biggest month of spend' : ''}.</>
    : <>No goal set, so this carries your recent ad spend — about <b>{GP_gbp(inp.base_monthly_spend)}</b> a month — through the quarter, spread toward the months where it buys most.</>;

  return (<div className="gp-plan">
    {flags.length > 0 && (<ul className="gp-plan-flags" aria-label="What to bear in mind">
      {flags.map(f => <li key={f}>{GP_FLAG_TEXT[f]}</li>)}
    </ul>)}

    <section className="gp-plan-sec">
      <h3 className="gp-plan-h">Where the {GP_gbp(d.revenue_target)} comes from</h3>
      <table className="gp-plan-tbl">
        <thead><tr><th scope="col"/><th scope="col">Sales</th><th scope="col">Profit before ads</th><th scope="col">Ads</th><th scope="col">Profit after ads</th></tr></thead>
        <tbody>
          <tr><th scope="row">Returning customers</th><td>{GP_gbp(b.returning_sales)}</td><td>{GP_gbp(b.returning_profit)}</td><td>—</td><td>{GP_gbp(b.returning_profit)}</td></tr>
          <tr><th scope="row">New customers</th><td>{GP_gbp(b.new_sales)}</td><td>{GP_gbp(b.new_profit_before_ads)}</td><td>−{GP_gbp(b.ads)}</td>
            <td className={newPays ? 'gp-pos' : 'gp-neg'}>{GP_gbp(b.new_profit_after_ads)}</td></tr>
          <tr className="gp-plan-total"><th scope="row">The quarter</th><td>{GP_gbp(d.revenue_target)}</td><td>{GP_gbp(d.product_cm_target)}</td><td>−{GP_gbp(d.spend_cap)}</td><td>{GP_gbp(d.cam_target)}</td></tr>
        </tbody>
      </table>
      <p className="gp-plan-say">{retShare != null ? 'Returning customers bring ' + fmtPctN(retShare) + ' of the sales and ' + GP_gbp(b.returning_profit) + ' of profit at no ad cost. ' : ''}
        {b.ads > 0 ? (newPays
          ? 'New customers cover their own ads with ' + GP_gbp(b.new_profit_after_ads) + ' to spare.'
          : 'New customers cost ' + GP_gbp(-b.new_profit_after_ads) + ' more in ads than their first orders earn this quarter — the return comes when they buy again.') : ''}</p>
    </section>

    {b.cost_per_new_customer != null && (<section className="gp-plan-sec">
      <h3 className="gp-plan-h">Each new customer</h3>
      <div className="gp-plan-stats">
        <div><span className="gp-plan-k">First order</span><span className="gp-plan-v">{fmtMoney(b.new_aov, 2)}</span><span className="gp-plan-sub">{fmtMoney(b.first_order_profit, 2)} profit before ads</span></div>
        <div><span className="gp-plan-k">Average cost to win one</span><span className="gp-plan-v">{fmtMoney(b.cost_per_new_customer, 2)}</span><span className="gp-plan-sub">ad budget ÷ new customers</span></div>
        <div><span className="gp-plan-k">Cost of the last ones bought</span><span className="gp-plan-v">{fmtMoney(b.marginal_cost_per_new_customer, 2)}</span><span className="gp-plan-sub">each extra £ of ads buys fewer</span></div>
      </div>
      <p className="gp-plan-say">{b.first_order_profit >= b.cost_per_new_customer
        ? 'On average a new customer pays for themselves on the first order. '
        : 'On average a new customer costs more than their first order earns, so the plan relies on them coming back. '}
        {b.marginal_cost_per_new_customer > b.first_order_profit
          ? 'The last customers the budget buys cost ' + fmtMoney(b.marginal_cost_per_new_customer, 2) + ' each — more than the ' + fmtMoney(b.first_order_profit, 2) + ' their first order earns. That is the edge of what is worth buying.'
          : 'Even the last customers the budget buys earn back their cost on the first order, so there is room to spend more.'}</p>
    </section>)}

    {months.length > 0 && (<section className="gp-plan-sec">
      <h3 className="gp-plan-h">Month by month</h3>
      <table className="gp-plan-tbl">
        <thead><tr><th scope="col">Month</th><th scope="col">Sales</th><th scope="col">From returning</th><th scope="col">New customers</th><th scope="col">Ad budget</th><th scope="col">Profit after ads</th></tr></thead>
        <tbody>{months.map(m => {
          const mo = Number(String(m.month).slice(5, 7)), isPeak = peak && m.month === peak.month && Number(m.season_new) >= 1.25;
          return (<tr key={m.month} className={isPeak ? 'gp-plan-peak' : undefined}>
            <th scope="row">{gpMonthName(m.month)}{mo === 11 && isPeak ? <span className="gp-plan-tag">Black Friday</span> : isPeak ? <span className="gp-plan-tag">Peak</span> : null}
              {Number(m.spend_vs_max_seen) > 1.5 && <span className="gp-plan-tag gp-plan-tag-warn">beyond your biggest month</span>}</th>
            <td>{GP_gbp(m.sales)}</td><td>{GP_gbp(m.returning)}</td><td>{fmtCount(m.new_customers)}</td><td>{GP_gbp(m.spend)}</td>
            <td className={Number(m.cam) < 0 ? 'gp-neg' : undefined}>{GP_gbp(m.cam)}</td>
          </tr>);
        })}</tbody>
      </table>
      <p className="gp-plan-say">The budget is spread toward the months where a pound of ads buys most{peak ? ', so ' + gpMonthName(peak.month) + ' gets ' + fmtPctN(Number(peak.spend) / Math.max(1, d.spend_cap)) + ' of it' : ''}. Today paces against these months, so a quiet month is not read as falling behind.</p>
    </section>)}

    {ly && (<section className="gp-plan-sec">
      <h3 className="gp-plan-h">The same months last year</h3>
      <p className="gp-plan-say">{GP_gbp(ly.sales)} of sales on {GP_gbp(ly.spend)} of ads, about {GP_gbp(ly.cam)} of profit after ads at today’s margin.
        {ly.sales > 0 ? ' This plan is ' + fmtPctN(d.revenue_target / ly.sales - 1) + (d.revenue_target >= ly.sales ? ' more' : ' less') + ' in sales' + (ly.spend > 0 ? ' on ' + v3WalkDp(d.spend_cap / ly.spend, 1) + '× the ad spend.' : '.') : ''}</p>
    </section>)}

    <section className="gp-plan-sec">
      <h3 className="gp-plan-h">The seasonal pattern behind it</h3>
      {idx.length === 12 && (<figure className="gp-plan-season">
        <svg viewBox="0 0 240 64" preserveAspectRatio="none" role="img" aria-label="Sales by month of the year against an average month">
          <line x1="0" x2="240" y1={64 - 64 / hi} y2={64 - 64 / hi} stroke={PAL.line} strokeWidth="1"/>
          {idx.map((v, i) => {
            const h = Math.max(1, v / hi * 64), on = planMonths.indexOf(i + 1) >= 0;
            return <rect key={i} x={i * 20 + 2} y={64 - h} width="16" height={h} fill={on ? PAL.accent : PAL.quiet}><title>{GP_MONTH_NAME[i] + ': ' + v3WalkDp(v, 2) + '× an average month'}</title></rect>;
          })}
        </svg>
        <figcaption><span>Jan</span><span>Sales against an average month · this quarter highlighted</span><span>Dec</span></figcaption>
      </figure>)}
      <p className="gp-plan-say">{s.source === 'own'
        ? 'Worked out from your own ' + (s.years || '') + ' years of trading, with your growth taken out so a good year does not read as a busy season.'
        : s.source === 'blended'
          ? 'Worked out from your first year of trading, blended with a typical UK online-retail pattern because one year is thin evidence. It sharpens as your history builds.'
          : 'Greta does not have a full year of your trading yet, so this uses a typical UK online-retail pattern — soft spring and summer, a lift into October, a November and December peak. It is replaced by your own pattern once you have a year.'}
        {' '}How far to lean on it: <b>{(V3_CONF[s.confidence] && V3_CONF[s.confidence].label) || s.confidence}</b>{s.year_to_year_spread != null && Number(s.year_to_year_spread) > 0.35 ? ' — your years differ quite a lot from each other' : ''}.</p>
      {doubling != null && <p className="gp-plan-say">Doubling the ad budget buys about {v3WalkDp(doubling, 2)}× the new-customer sales, not 2× — {inp.beta_source === 'measured' ? 'measured from your own spend history' : 'a standard assumption until Greta can measure yours'}. The starting point is your last {inp.base_months} full month{inp.base_months === 1 ? '' : 's'} ({inp.base_from ? gpMonthName(inp.base_from) : ''} to {inp.base_to ? gpMonthName(inp.base_to) : ''}) with the season taken out.</p>}
      {ceil && ceil.best_cam != null && <p className="gp-plan-say">The most profit after ads Greta can see this quarter is about <b>{GP_gbp(ceil.best_cam)}</b>, at about {GP_gbp(ceil.best_spend)} of ads and {GP_gbp(ceil.best_sales)} of sales. Spending past that buys sales but costs profit.</p>}
    </section>

    <button type="button" className="gp-plan-more" aria-expanded={open} onClick={() => setOpen(!open)}>
      <Icon name="chevron" size={12} style={{ transform: open ? 'rotate(90deg)' : 'none' }}/> How Greta worked this out
    </button>
    {open && (<div className="gp-plan-how">
      <p className="gp-plan-say">{basisLine}</p>
      <p className="gp-plan-say">Every pound of sales keeps {fmtPctN(d.cm_ratio_used)} after product and order costs — that is profit before ads. Profit after ads is that, less the ad budget. New customers are counted at a new customer’s order value ({fmtMoney(b.new_aov, 2)}), not the average across all orders.</p>
    </div>)}
  </div>);
}

function GP_ChannelHealth(p){
  var h = p.h;
  var es = React.useState(false), edit = es[0], setEdit = es[1];
  var fs = React.useState(null), f = fs[0], setF = fs[1];
  var bs = React.useState(false), busy = bs[0], setBusy = bs[1];
  var ms = React.useState(null), msg = ms[0], setMsg = ms[1];
  if(!h) return null;
  var noData = !h.has_data;
  var ragCol = h.rag==='g'?GP_T.green : h.rag==='a'?GP_T.amber : h.rag==='r'?GP_T.red : GP_T.dim;
  var ret = Number(h.returning_rev_share_pct)||0;
  var prret = h.prior_returning_share_pct!=null?Number(h.prior_returning_share_pct):null;
  var lo = Number(h.ret_low), hi = Number(h.ret_high);
  var SCALE = 80, clamp = function(x){ return Math.max(0, Math.min(100, x/SCALE*100)); };
  var d = prret!=null ? ret-prret : null;
  var emailLc = h.email_share_lastclick_pct!=null?Number(h.email_share_lastclick_pct):null;
  var emailPr = h.prior_email_share_lastclick_pct!=null?Number(h.prior_email_share_lastclick_pct):null;
  var ed = (emailLc!=null && emailPr!=null) ? emailLc-emailPr : null;
  function openEdit(){ setF({ retLow:String(Math.round(lo)), retHigh:String(Math.round(hi)), emailLow:String(Math.round(Number(h.email_low))), emailHigh:String(Math.round(Number(h.email_high))) }); setMsg(null); setEdit(true); }
  function setK(k,v){ setF(function(o){ var n=Object.assign({},o); n[k]=v.replace(/[^0-9.]/g,''); return n; }); }
  function save(){ if(!window.FRKL_PLAN||!window.FRKL_PLAN.saveBands) return; setBusy(true); setMsg(null);
    window.FRKL_PLAN.saveBands(f).then(function(r){ setBusy(false); if(r.ok){ setEdit(false); } else { setMsg(r.error||'failed'); } }); }
  var inp = { backgroundColor: 'var(--color-surface)', border:'1px solid '+GP_T.line, borderRadius:'var(--radius-md)', color:GP_T.ink, fontFamily:GP_T.mono, fontSize:'var(--text-sm)', padding:'6px 8px', width:'100%', boxSizing:'border-box' };
  return (
    <div style={{ background: GP_T.panel, border:'1px solid '+GP_T.line, borderRadius:'var(--radius-none)', padding:'14px 16px', marginBottom:16 }}>
      <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center', marginBottom:4 }}>
        <h2 className="v3-sec-title gp-h">Retention balance <span className="v3-muted">new vs returning</span></h2>
        <span style={{ fontSize:'var(--text-xs)', color:GP_T.dim }}>{h.category} &middot; {h.band_source==='brand_override'?'custom band':'category default'}{!edit ? <button onClick={openEdit} style={{ marginLeft:8, fontSize:'var(--text-xs)', color:GP_T.mut, background:'none', border:'1px solid '+GP_T.line, borderRadius:'var(--radius-md)', padding:'2px 7px', cursor:'pointer' }}>Edit band</button> : null}</span>
      </div>
      {edit && f ? (
        <div style={{ marginTop:8 }}>
          <div style={{ fontSize:'var(--text-sm)', color:GP_T.dim, marginBottom:8 }}>Set the healthy band for this brand. Leave as-is to keep the {h.category}-category default.</div>
          <div style={{ display:'grid', gridTemplateColumns:'1fr 1fr', gap:10 }}>
            <label style={{ fontSize:'var(--text-xs)', color:GP_T.mut }}>Returning share &mdash; low (%)<input style={Object.assign({marginTop:4},inp)} value={f.retLow} onChange={function(e){setK('retLow',e.target.value);}}/></label>
            <label style={{ fontSize:'var(--text-xs)', color:GP_T.mut }}>Returning share &mdash; high (%)<input style={Object.assign({marginTop:4},inp)} value={f.retHigh} onChange={function(e){setK('retHigh',e.target.value);}}/></label>
            <label style={{ fontSize:'var(--text-xs)', color:GP_T.mut }}>Email share &mdash; low (%)<input style={Object.assign({marginTop:4},inp)} value={f.emailLow} onChange={function(e){setK('emailLow',e.target.value);}}/></label>
            <label style={{ fontSize:'var(--text-xs)', color:GP_T.mut }}>Email share &mdash; high (%)<input style={Object.assign({marginTop:4},inp)} value={f.emailHigh} onChange={function(e){setK('emailHigh',e.target.value);}}/></label>
          </div>
          <div style={{ display:'flex', alignItems:'center', gap:10, marginTop:12 }}>
            <button onClick={save} disabled={busy} style={{ borderRadius:'var(--radius-md)', padding:'8px 15px', fontSize:'var(--text-sm)', border:'1px solid '+GP_T.accent, background:GP_T.accent, color:PAL.panel, fontWeight:'var(--weight-semi)', cursor:'pointer' }}>{busy?'Saving…':'Save band'}</button>
            <button onClick={function(){ setEdit(false); }} disabled={busy} style={{ borderRadius:'var(--radius-md)', padding:'8px 12px', fontSize:'var(--text-sm)', border:'1px solid '+GP_T.line, background:GP_T.panel, color:GP_T.ink, cursor:'pointer' }}>Cancel</button>
            {msg ? <span style={{ fontSize:'var(--text-sm)', color:GP_T.red }}>{msg}</span> : null}
          </div>
        </div>
      ) : noData ? (
        <div style={{ fontSize:'var(--text-sm)', color:GP_T.dim }}>{h.guidance}</div>
      ) : (
        <div>
          <div style={{ position:'relative', height:10, borderRadius:'var(--radius-none)', background:'var(--color-surface)', margin:'12px 0 5px' }}>
            <div style={{ position:'absolute', left:clamp(lo)+'%', width:(clamp(hi)-clamp(lo))+'%', top:0, bottom:0, background:GP_T.green, opacity:0.28, borderRadius:'var(--radius-none)' }}/>
            <div style={{ position:'absolute', left:'calc('+clamp(ret)+'% - 1px)', top:-3, bottom:-3, width:2, background:ragCol }}/>
          </div>
          <div style={{ display:'flex', justifyContent:'space-between', fontSize:'var(--text-xs)', color:GP_T.dim }}>
            <span>0%</span><span>healthy {Math.round(lo)}&ndash;{Math.round(hi)}% returning</span><span>{SCALE}%</span>
          </div>
          <div style={{ fontSize:'var(--text-sm)', color:ragCol, fontWeight:'var(--weight-semi)', margin:'11px 0 5px' }}>
            {ret.toFixed(0)}% returning / {(100-ret).toFixed(0)}% new{d!=null ? <span style={{ fontSize:'var(--text-xs)', color:GP_T.dim, fontWeight:'var(--weight-normal)' }}> &middot; {(d>=0?'+':'−')+Math.abs(d).toFixed(0)+' pts on the 30 days before'}</span> : null}
          </div>
          <div style={{ fontSize:'var(--text-sm)', color:GP_T.mut, lineHeight:1.55 }}>{h.guidance}</div>
          <div style={{ display:'flex', gap:20, marginTop:11, paddingTop:10, borderTop:'1px solid '+GP_T.line, flexWrap:'wrap' }}>
            <div>
              <div style={{ fontSize:'var(--text-xs)', color:GP_T.dim }}>Email &middot; last-click</div>
              <div style={{ fontFamily:GP_T.mono, fontSize:'var(--text-base)' }}>{emailLc!=null?emailLc.toFixed(1)+'%':'—'}{ed!=null ? <span style={{ fontSize:'var(--text-xs)', color:ed>=0?GP_T.green:GP_T.red, marginLeft:5 }}>{(ed>=0?'+':'−')+Math.abs(ed).toFixed(1)}</span> : null}</div>
              <div style={{ fontSize:'var(--text-xs)', color:GP_T.dim }}>target {Math.round(Number(h.email_low))}&ndash;{Math.round(Number(h.email_high))}%</div>
            </div>
            <div>
              <div style={{ fontSize:'var(--text-xs)', color:GP_T.dim }}>Email &middot; Klaviyo</div>
              <div style={{ fontFamily:GP_T.mono, fontSize:'var(--text-base)' }}>{h.email_share_klaviyo_pct!=null?Number(h.email_share_klaviyo_pct).toFixed(0)+'%':'—'}</div>
              <div style={{ fontSize:'var(--text-xs)', color:GP_T.dim }}>over-counts &mdash; context</div>
            </div>
          </div>
          <div style={{ fontSize:'var(--text-xs)', color:GP_T.dim, marginTop:9, lineHeight:1.5 }}>Email is the main lever on this balance. Last-click is the reconciled floor; Klaviyo credits far more via open/click attribution. Bands are per-category and editable per brand.</div>
        </div>
      )}
    </div>
  );
}

function GP_ChannelMix(p){
  var mix = p.mix || [];
  var cur = mix.filter(function(r){ return r.window_label==='current_30d'; });
  if(!cur.length) return null;
  var prior = {}; mix.forEach(function(r){ if(r.window_label==='prior_30d') prior[r.channel]=Number(r.net_revenue); });
  cur = cur.slice().sort(function(a,b){ return Number(b.net_revenue)-Number(a.net_revenue); });
  var total = cur.reduce(function(a,r){ return a+Number(r.net_revenue); },0) || 1;
  var LBL = {paid_social:'Paid social', paid_search:'Paid search', email:'Email', referral:'Referral', direct:'Direct', organic_social:'Organic social', organic_search:'Organic search', sms:'SMS'};
  var PAID = {paid_social:1, paid_search:1};
  var paidRev = cur.reduce(function(a,r){ return a + (PAID[r.channel]?Number(r.net_revenue):0); },0);
  return (
    <div style={{ background: GP_T.panel, border:'1px solid '+GP_T.line, borderRadius:'var(--radius-none)', padding:'14px 16px', marginBottom:16 }}>
      <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center', marginBottom:4 }}>
        <h2 className="v3-sec-title gp-h">Where revenue comes from <span className="v3-muted">last 30 days</span></h2>
        <span style={{ fontSize:'var(--text-xs)', color:GP_T.dim }}>paid {Math.round(100*paidRev/total)}% &middot; non-paid {Math.round(100*(1-paidRev/total))}%</span>
      </div>
      <div style={{ fontSize:'var(--text-sm)', color:GP_T.dim, marginBottom:10 }}>Shopify last-click attribution, reconciled to your total Shopify sales &mdash; the basis for each channel's target.</div>
      {cur.map(function(r,i){
        var rev=Number(r.net_revenue), pct=rev/total*100;
        var pr=prior[r.channel], d=(pr && pr>0)?(rev/pr-1)*100:null;
        var ret=Number(r.orders)>0?Math.round(100*Number(r.returning_orders)/Number(r.orders)):0;
        var col=PAID[r.channel]?GP_T.accent:GP_T.green;
        return (
          <div key={i} style={{ padding:'7px 0', borderTop:'1px solid '+GP_T.line }}>
            <div style={{ display:'flex', justifyContent:'space-between', alignItems:'baseline', gap:8, fontSize:'var(--text-sm)' }}>
              <span style={{ fontWeight:'var(--weight-semi)' }}>{LBL[r.channel]||r.channel}{r.channel==='referral' && Number(r.orders_with_discount)>0 ? <span style={{ color:GP_T.dim, fontWeight:'var(--weight-normal)' }}> &middot; {r.orders_with_discount} coded</span> : null}</span>
              <span style={{ fontFamily:GP_T.mono }}>{GP_gbp(rev)} <span style={{ color:GP_T.dim }}>({pct.toFixed(0)}%)</span>{d!=null ? <span style={{ color:d>=0?GP_T.green:GP_T.red, marginLeft:6 }}>{(d>=0?'+':'−')+Math.abs(d).toFixed(0)+'%'}</span> : null}</span>
            </div>
            <div style={{ position:'relative', height:5, borderRadius:'var(--radius-sm)', background:'var(--color-surface)', margin:'5px 0 3px', overflow:'hidden' }}>
              <div style={{ position:'absolute', left:0, top:0, bottom:0, width:pct+'%', background:col, opacity:0.8 }}/>
            </div>
            <div style={{ fontSize:'var(--text-xs)', color:GP_T.dim }}>{r.new_orders} new &middot; {r.returning_orders} returning ({ret}% ret) &middot; average order value {GP_gbp(r.aov)}</div>
          </div>
        );
      })}
      <div style={{ fontSize:'var(--text-xs)', color:GP_T.dim, marginTop:9, lineHeight:1.5 }}>Influencer/affiliate currently sits inside Referral &amp; Direct via discount codes &mdash; tag creator codes to split it out. Email is last-click here; Klaviyo credits more via open/click attribution.</div>
    </div>
  );
}


// ── Spend curve (the "k curve") ────────────────────────────────────────────────────────────
// The forecast models revenue as a Hill saturation R(S) = Vmax*S/(K+S); K is the
// half-saturation spend. Operationally the brand meets it as its CAC elasticity beta — the
// log-log slope of cost-per-customer on spend. beta -> 0 is a flat curve, beta -> 1 is severe
// saturation.
//
// TWO LAYERS, deliberately separated, because they carry different certainty:
//   MEASURED  — the monthly (spend, CAC) points and how many sat above contribution.
//               No model. True regardless of whether the fit is identified.
//   MODELLED  — where the profitable ceiling sits. Carries a 95% band and a `verdict`.
//
// When verdict = 'indeterminate' the current spend sits inside the identified ceiling range,
// so we render the BAND and say we cannot yet call it. Drawing one confident line would
// contradict vw_marginal_econ_gate, which already says "a wide range, not a target".
function GP_SpendCurve(p) {
  var c = p.curve, pts = (p.points || []).filter(function (d) { return Number(d.spend) > 0 && Number(d.cac) > 0; });
  if (!c || pts.length < 6) return null;

  var beta = Number(c.beta), cm = Number(c.cm_per_order), cur = Number(c.current_spend) || 0;
  var aMid = Number(c.intercept_a), aLo = Number(c.intercept_a_ci_low), aHi = Number(c.intercept_a_ci_high);
  var bLo = Number(c.ci_low), bHi = Number(c.ci_high);
  var indet = c.verdict === 'indeterminate' || c.verdict === 'unknown';

  var W = 620, H = 250, ML = 48, MR = 16, MT = 14, MB = 32;
  var pw = W - ML - MR, ph = H - MT - MB;
  var maxSpend = Math.max(cur, Math.max.apply(null, pts.map(function (d) { return Number(d.spend); })));
  var maxCac = Math.max(cm, Math.max.apply(null, pts.map(function (d) { return Number(d.cac); })));
  var x1 = maxSpend * 1.08, y1 = maxCac * 1.18;
  var X = function (s) { return ML + (s / x1) * pw; };
  var Y = function (v) { return MT + ph - (v / y1) * ph; };
  var cac = function (s, a, b) { return Math.exp(a + b * Math.log(s)); };

  // Sample the band. Taking min/max per x keeps the polygon simple: the two boundary curves
  // CROSS at the data centroid (that is where the evidence is strongest), so a naive
  // forward/reverse polygon would self-intersect.
  var s0 = Math.max(200, maxSpend * 0.08), steps = 48, lo = [], hi = [], mid = [];
  for (var i = 0; i <= steps; i++) {
    var s = s0 + (x1 - s0) * (i / steps);
    var a1 = cac(s, aLo, bLo), a2 = cac(s, aHi, bHi);
    lo.push([X(s), Y(Math.min(a1, a2))]);
    hi.push([X(s), Y(Math.max(a1, a2))]);
    mid.push([X(s), Y(cac(s, aMid, beta))]);
  }
  var poly = hi.map(function (q) { return q.join(','); }).join(' ') + ' ' +
             lo.slice().reverse().map(function (q) { return q.join(','); }).join(' ');
  var line = function (arr) { return arr.map(function (q, i) { return (i ? 'L' : 'M') + q[0] + ' ' + q[1]; }).join(' '); };

  var above = pts.filter(function (d) { return d.cac_above_contribution; });
  var recent = pts.slice(-4);
  var recentAbove = recent.filter(function (d) { return d.cac_above_contribution; }).length;

  var chip = function (txt, col) {
    return <span style={{ fontSize: 'var(--text-xs)', fontWeight:'var(--weight-bold)', letterSpacing: 'var(--tracking-wide)', textTransform: 'uppercase',
      color: col, border: '1px solid ' + col, borderRadius: 'var(--radius-md)', padding: '2px 6px' }}>{txt}</span>;
  };
  var tick = function (v) { return fmtMoneyK(v); };

  return (
    <div style={{ borderTop: '1px solid ' + GP_T.line, padding: 'var(--space-6) 0' }}>
      <div style={{ display: 'flex', alignItems: 'baseline', gap: 10, flexWrap: 'wrap', marginBottom: 4 }}>
        <h2 className="v3-sec-title gp-h">Spend curve</h2>
        {indet ? chip('range, not a target', GP_T.amber)
               : chip(c.verdict === 'over' ? 'over the ceiling' : 'under the ceiling',
                      c.verdict === 'over' ? GP_T.red : GP_T.green)}
      </div>
      <div style={{ fontSize: 'var(--text-sm)', color: GP_T.mut, lineHeight: 1.6, maxWidth: 620, marginBottom: 14 }}>
        Every pound of media buys customers at a rising price. This is that price, measured over{' '}
        <b style={{ color: GP_T.ink }}>{c.n_months} months</b> across a{' '}
        <b style={{ color: GP_T.ink }}>{Number(c.spend_range_x).toFixed(1)}×</b> spend range.
      </div>

      {/* MEASURED — no model involved */}
      <div style={{ fontSize: 'var(--text-xs)', letterSpacing: 'var(--tracking-wide)', textTransform: 'uppercase', color: GP_T.dim, marginBottom: 8 }}>What you have measured</div>
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit,minmax(150px,1fr))', gap: 10, marginBottom: 8 }}>
        <GP_Metric k="An average order contributes" v={fmtMoney(cm, 2)} />
        <GP_Metric k="Last month's cost per customer" v={fmtMoney(pts[pts.length - 1].cac, 2)}
          hi={pts[pts.length - 1].cac_above_contribution} sub={pts[pts.length - 1].month ? String(pts[pts.length - 1].month).slice(0, 7) : null} />
        <GP_Metric k="Months above contribution" v={above.length + ' of ' + pts.length}
          sub={recentAbove + ' of the last ' + recent.length} />
      </div>
      {recentAbove > 0 && (
        <div style={{ fontSize: 'var(--text-sm)', color: GP_T.red, lineHeight: 1.6, marginBottom: 14 }}>
          {recentAbove} of your last {recent.length} months cost more to acquire a customer than an average
          order returns. That is measured, not modelled — it holds whatever the curve turns out to be.
        </div>
      )}

      <svg viewBox={'0 0 ' + W + ' ' + H} width="100%" role="img"
        aria-label={'Monthly ad spend against cost per new customer over ' + c.n_months + ' months, with the fitted curve and its 95% band'}
        style={{ display: 'block', overflow: 'visible' }}>
        {[0.25, 0.5, 0.75, 1].map(function (f, i) {
          return <g key={i}>
            <line x1={ML} x2={W - MR} y1={Y(y1 * f)} y2={Y(y1 * f)} stroke={svgCol(GP_T.line)} strokeWidth="1" />
            <text x={ML - 8} y={Y(y1 * f) + 3.5} textAnchor="end" fontSize="11" fill={svgCol(GP_T.dim)} fontFamily={GP_T.mono}>{tick(y1 * f)}</text>
          </g>;
        })}
        <polygon points={poly} fill={svgCol(GP_T.accent)} opacity="0.13" />
        <path d={line(mid)} fill="none" stroke={svgCol(GP_T.accent)} strokeWidth="2" />
        <line x1={ML} x2={W - MR} y1={Y(cm)} y2={Y(cm)} stroke={svgCol(GP_T.red)} strokeWidth="1.5" strokeDasharray="5 4" />
        <text x={W - MR} y={Y(cm) - 6} textAnchor="end" fontSize="11" fill={svgCol(GP_T.red)}>an order contributes £{cm.toFixed(0)}</text>
        {cur > 0 && <line x1={X(cur)} x2={X(cur)} y1={MT} y2={MT + ph} stroke={svgCol(GP_T.dim)} strokeWidth="1.5" strokeDasharray="2 3" />}
        {cur > 0 && <text x={X(cur) - 6} y={MT + 10} textAnchor="end" fontSize="11" fill={svgCol(GP_T.dim)}>now</text>}
        {pts.map(function (d, i) {
          var bad = !!d.cac_above_contribution;
          return <circle key={i} cx={X(Number(d.spend))} cy={Y(Number(d.cac))} r="4"
            fill={svgCol(bad ? GP_T.red : GP_T.accent)} opacity={bad ? 0.95 : 0.7}>
            <title>{String(d.month).slice(0, 7) + ' · ' + GP_gbp(d.spend) + ' spend · £' + Number(d.cac).toFixed(2) + ' per customer'}</title>
          </circle>;
        })}
        <line x1={ML} x2={W - MR} y1={MT + ph} y2={MT + ph} stroke={svgCol(GP_T.line)} strokeWidth="1" />
        {[0.25, 0.5, 0.75, 1].map(function (f, i) {
          return <text key={i} x={X(x1 * f)} y={H - 10} textAnchor="middle" fontSize="11" fill={svgCol(GP_T.dim)} fontFamily={GP_T.mono}>{tick(x1 * f)}</text>;
        })}
        <text x={ML} y={H - 10} textAnchor="start" fontSize="11" fill={svgCol(GP_T.dim)}>monthly spend →</text>
      </svg>

      {/* MODELLED — carries the band */}
      <div style={{ fontSize: 'var(--text-xs)', letterSpacing: 'var(--tracking-wide)', textTransform: 'uppercase', color: GP_T.dim, margin: '14px 0 8px' }}>What the curve models</div>
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit,minmax(150px,1fr))', gap: 10 }}>
        <GP_Metric k="How fast customers get dearer" v={beta.toFixed(2)} sub={'0 = no rise · 1 = costs rise as fast as spend · range ' + bLo.toFixed(2) + '–' + bHi.toFixed(2)} />
        <GP_Metric k="The next customer costs you" v={fmtMoney(c.marginal_cac_now, 2)}
          hi={c.marginal_cac_now != null && Number(c.marginal_cac_now) > cm} sub={'at ' + GP_gbp(cur) + '/mo'} />
        <GP_Metric k="Most you can spend and still profit" hi={!indet}
          v={c.ceiling_low == null && c.ceiling_high == null ? '—'
             : GP_gbp(c.ceiling_low != null ? c.ceiling_low : c.ceiling_mid) + '–' + GP_gbp(c.ceiling_high)}
          sub={c.ci_admits_no_ceiling ? 'band also admits no ceiling' : 'where the next customer costs what one is worth'} />
      </div>

      <div style={{ fontSize: 'var(--text-sm)', color: GP_T.mut, lineHeight: 1.65, marginTop: 12 }}>
        {indet ? (
          <span>
            Your spend of <b style={{ color: GP_T.ink }}>{GP_gbp(cur)}/mo</b> sits <b style={{ color: GP_T.ink }}>inside</b> that
            range, so the curve cannot yet tell you which end you are on. Spend and discount depth move
            together here (r² {Number(c.r2).toFixed(2)}), so the fit cannot separate them.{' '}
            <b style={{ color: GP_T.ink }}>To narrow it:</b> hold discount steady and step spend deliberately
            for a few weeks, or run a geo-holdout. More months alone will not do it.
          </span>
        ) : (
          <span>
            Your spend of <b style={{ color: GP_T.ink }}>{GP_gbp(cur)}/mo</b> is{' '}
            <b style={{ color: c.verdict === 'over' ? GP_T.red : GP_T.green }}>
              {c.verdict === 'over' ? 'above' : 'below'}
            </b>{' '}the whole identified range, so this read holds across the band.
          </span>
        )}
      </div>
      {c.reason && (
        <div style={{ fontSize: 'var(--text-xs)', color: GP_T.dim, marginTop: 8, lineHeight: 1.5 }}>Model gate: {c.reason}</div>
      )}
    </div>
  );
}

// ── Curve extensions, mounted 2026-09-25 ─────────────────────────────────────
// Written in Sep 2026 and left in docs/UI-curve-constraint-history-levers.jsx with no
// mount, so the engine could say why the curve bends, how the read has changed and
// what would move it — and no screen ever said it. Adopted verbatim apart from this
// note; the views (0145) have been live throughout.
// ── Why the curve bends: auction or conversion ────────────────────────────────────────────────
// CAC = CPC / customers-per-click is an IDENTITY, so beta splits exactly:
//   beta = beta_CPC - beta_CVR.
// Rendered as a diverging bar because the two legs can pull in OPPOSITE directions and that is
// the most useful thing on the chart — frkl's auction leg is negative, meaning clicks get cheaper
// as it scales, and 100% of its saturation is conversion decay. A stacked bar would hide the sign.
function GP_CurveConstraint(p) {
  var d = p.dec;
  if (!d || d.dominant_constraint === 'no_saturation') return null;
  var bCpc = Number(d.beta_cpc), bCvr = Number(d.beta_cvr);
  var auction = bCpc, conversion = -bCvr;           // contributions, summing to beta
  var beta = auction + conversion;
  // A zero or missing curve can't be split into shares ("NaN% of your saturation"): treat it as unidentified.
  var indet = d.dominant_constraint === 'indeterminate' || !(Math.abs(beta) > 0) || !isFinite(beta);

  var W = 620, H = 92, ML = 96, MR = 16;
  var pw = W - ML - MR;
  var lim = Math.max(Math.abs(auction), Math.abs(conversion), Math.abs(beta)) * 1.15 || 1;
  var zero = ML + pw / 2;
  var X = function (v) { return zero + (v / lim) * (pw / 2); };

  var bar = function (label, val, y, col, t) {
    var x0 = Math.min(X(0), X(val)), w = Math.abs(X(val) - X(0));
    return (
      <g>
        <text x={ML - 10} y={y + 13} textAnchor="end" fontSize="11" fill={GP_T.mut}>{label}</text>
        <rect x={x0} y={y} width={Math.max(w, 1)} height="18" fill={col} opacity={indet ? 0.35 : 0.85} rx="2" />
        <text x={val >= 0 ? x0 + w + 6 : x0 - 6} y={y + 13} textAnchor={val >= 0 ? 'start' : 'end'}
          fontSize="11" fontFamily={GP_T.mono} fill={GP_T.ink}>
          {(val >= 0 ? '+' : '') + val.toFixed(2)}
          {t != null && isFinite(t) ? <tspan fill={GP_T.dim}>{'  t ' + Number(t).toFixed(1)}</tspan> : null}
        </text>
      </g>
    );
  };

  return (
    <div style={{ borderTop: '1px solid ' + GP_T.line,
      padding: '16px 18px', marginTop: 12 }}>
      <h2 className="v3-sec-title gp-h">Why the curve bends</h2>
      <div style={{ fontSize: 'var(--text-sm)', color: GP_T.mut, lineHeight: 1.6, maxWidth: 620, marginBottom: 12 }}>
        Rising cost per customer has exactly two causes, and they have opposite fixes. Your CAC alone
        cannot tell them apart — this splits it.
      </div>

      <svg viewBox={'0 0 ' + W + ' ' + H} width="100%" role="img"
        aria-label="Saturation split into its auction and conversion components"
        style={{ display: 'block', overflow: 'visible' }}>
        <line x1={zero} x2={zero} y1="4" y2={H - 22} stroke={GP_T.line} strokeWidth="1" />
        {bar('Auction (CPC)', auction, 6, auction > 0 ? GP_T.red : GP_T.green, d.t_auction)}
        {bar('Conversion (conversion rate)', conversion, 34, conversion > 0 ? GP_T.red : GP_T.green, d.t_conversion)}
        <line x1={ML} x2={W - MR} y1={62} y2={62} stroke={GP_T.line} strokeWidth="1" />
        {bar('= your curve (β)', beta, 66, GP_T.accent, null)}
      </svg>

      <div style={{ fontSize: 'var(--text-sm)', color: GP_T.mut, lineHeight: 1.65, marginTop: 10 }}>
        {indet ? (
          <span>Neither leg is distinguishable from zero yet, so the cause is <b style={{ color: GP_T.ink }}>not
            identified</b>. More months at distinct spend levels will separate them.</span>
        ) : auction < 0 ? (
          <span>
            Your cost per click <b style={{ color: GP_T.green }}>falls</b> as you spend more — there is no
            auction penalty at all. <b style={{ color: GP_T.ink }}>All</b> of your saturation is conversion:
            the traffic you buy at the margin converts worse. Cheaper media will not raise your ceiling.
          </span>
        ) : (
          <span>
            Conversion accounts for <b style={{ color: GP_T.ink }}>{Math.round((conversion / beta) * 100)}%</b> of
            your saturation, the auction <b style={{ color: GP_T.ink }}>{Math.round((auction / beta) * 100)}%</b>.
          </span>
        )}
      </div>
    </div>
  );
}

// ── Has the curve moved? ──────────────────────────────────────────────────────────────────────
// EXPANDING window, never rolling. Overlapping rolling windows share most of their observations
// and draw a smooth line that is mostly overlap, not signal. This plots what Greta could have said
// at each month-end on the data it had then, so the honest reading is whether the ESTIMATE is
// converging — which is NOT the same claim as "your curve changed".
function GP_CurveHistory(p) {
  var rows = (p.rows || []).filter(function (r) { return r.beta != null && r.ci_low != null; });
  if (rows.length < 3) return null;

  var W = 620, H = 200, ML = 44, MR = 16, MT = 14, MB = 34;
  var pw = W - ML - MR, ph = H - MT - MB;
  var lo = Math.min.apply(null, rows.map(function (r) { return Number(r.ci_low); }));
  var hi = Math.max.apply(null, rows.map(function (r) { return Number(r.ci_high); }));
  lo = Math.min(lo, -0.1); hi = Math.max(hi, 1.1);
  var X = function (i) { return ML + (i / (rows.length - 1)) * pw; };
  var Y = function (v) { return MT + ph - ((v - lo) / (hi - lo)) * ph; };

  var band = rows.map(function (r, i) { return X(i) + ',' + Y(Number(r.ci_high)); }).join(' ') + ' ' +
             rows.slice().reverse().map(function (r, i) {
               return X(rows.length - 1 - i) + ',' + Y(Number(r.ci_low)); }).join(' ');
  var line = rows.map(function (r, i) { return (i ? 'L' : 'M') + X(i) + ' ' + Y(Number(r.beta)); }).join(' ');

  var first = rows[0], last = rows[rows.length - 1];
  var narrowed = Number(last.ci_high) - Number(last.ci_low) < Number(first.ci_high) - Number(first.ci_low);

  return (
    <div style={{ borderTop: '1px solid ' + GP_T.line,
      padding: '16px 18px', marginTop: 12 }}>
      <h2 className="v3-sec-title gp-h">How the read has changed</h2>
      <div style={{ fontSize: 'var(--text-sm)', color: GP_T.mut, lineHeight: 1.6, maxWidth: 620, marginBottom: 12 }}>
        What Greta could have told you at each month-end, on the data it had then. The shaded band is
        the 95% interval — watch it narrow as evidence accumulates.
      </div>

      <svg viewBox={'0 0 ' + W + ' ' + H} width="100%" role="img"
        aria-label="Fitted curvature and its confidence interval at each month-end"
        style={{ display: 'block', overflow: 'visible' }}>
        {[0, 0.5, 1].map(function (v, i) {
          return <g key={i}>
            <line x1={ML} x2={W - MR} y1={Y(v)} y2={Y(v)} stroke={GP_T.line} strokeWidth="1"
              strokeDasharray={v === 1 ? '4 4' : undefined} />
            <text x={ML - 8} y={Y(v) + 3.5} textAnchor="end" fontSize="11" fill={GP_T.dim}
              fontFamily={GP_T.mono}>{v.toFixed(1)}</text>
          </g>;
        })}
        {/* above beta = 1 there is no finite ceiling at all */}
        <text x={W - MR} y={Y(1) - 5} textAnchor="end" fontSize="11" fill={GP_T.dim}>
          β ≥ 1 · no ceiling exists
        </text>
        <polygon points={band} fill={GP_T.accent} opacity="0.13" />
        <path d={line} fill="none" stroke={GP_T.accent} strokeWidth="2" />
        {rows.map(function (r, i) {
          return <circle key={i} cx={X(i)} cy={Y(Number(r.beta))} r="2.6" fill={GP_T.accent}>
            <title>{String(r.month).slice(0, 7) + ' · β ' + Number(r.beta).toFixed(2) +
              ' (95% ' + Number(r.ci_low).toFixed(2) + '–' + Number(r.ci_high).toFixed(2) +
              ') on ' + r.n + ' months'}</title>
          </circle>;
        })}
        <line x1={ML} x2={W - MR} y1={MT + ph} y2={MT + ph} stroke={GP_T.line} strokeWidth="1" />
        <text x={ML} y={H - 10} fontSize="11" fill={GP_T.dim}>{String(first.month).slice(0, 7)}</text>
        <text x={W - MR} y={H - 10} textAnchor="end" fontSize="11" fill={GP_T.dim}>
          {String(last.month).slice(0, 7)}
        </text>
      </svg>

      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit,minmax(150px,1fr))',
        gap: 10, marginTop: 12 }}>
        <GP_Metric k="Interval then" v={(Number(first.ci_high) - Number(first.ci_low)).toFixed(2)}
          sub={'on ' + first.n + ' months'} />
        <GP_Metric k="Interval now" v={(Number(last.ci_high) - Number(last.ci_low)).toFixed(2)}
          sub={'on ' + last.n + ' months'} />
        <GP_Metric k="Curvature now" v={Number(last.beta).toFixed(2)}
          sub={'95% ' + Number(last.ci_low).toFixed(2) + '–' + Number(last.ci_high).toFixed(2)} />
      </div>

      {/* The distinction this whole panel turns on. Do not soften it. */}
      <div style={{ fontSize: 'var(--text-sm)', color: GP_T.mut, lineHeight: 1.65, marginTop: 12 }}>
        {narrowed
          ? <span>The interval is <b style={{ color: GP_T.ink }}>narrowing</b> — the estimate is getting
              sharper as months accumulate. That is a statement about what Greta knows, <b
              style={{ color: GP_T.ink }}>not</b> evidence that your curve itself has moved; a formal
              test for that is not significant on this data.</span>
          : <span>The interval has <b style={{ color: GP_T.ink }}>stopped narrowing</b>. More months of
              the same spending pattern will not sharpen this — it needs deliberate variation in spend,
              or a geo-holdout.</span>}
      </div>
    </div>
  );
}

// ── What moves the curve ──────────────────────────────────────────────────────────────────────
// Two tiers, deliberately separated, because they carry different certainty:
//   CERTAIN — what the lever does to CM or CAC. Arithmetic on the CM identity, no beta.
//   BANDED  — what that does to affordable spend. Needs beta, inherits its whole interval.
function GP_CurveLevers(p) {
  var levers = (p.levers || []).filter(function (l) { return l.ceiling_multiplier_mid != null; });
  if (levers.length < 2) return null;
  levers = levers.slice().sort(function (a, b) {
    return Number(b.ceiling_multiplier_mid) - Number(a.ceiling_multiplier_mid); });
  var max = Number(levers[0].ceiling_multiplier_mid) - 1;
  var LABEL = { aov: 'Average order value', gross_margin: 'Gross margin', refund_rate: 'Refund rate',
    per_order_costs: 'Per-order costs', cvr: 'Visitors who buy', cpc: 'Cost per click' };

  return (
    <div style={{ borderTop: '1px solid ' + GP_T.line,
      padding: '16px 18px', marginTop: 12 }}>
      <h2 className="v3-sec-title gp-h">What moves it</h2>
      <div style={{ fontSize: 'var(--text-sm)', color: GP_T.mut, lineHeight: 1.6, maxWidth: 620, marginBottom: 14 }}>
        The ceiling is where the curve meets what a customer is worth. You can move the{' '}
        <b style={{ color: GP_T.ink }}>line</b> up (worth more) or the{' '}
        <b style={{ color: GP_T.ink }}>curve</b> down (cost less). Each row is a 10% improvement in
        one thing, holding everything else fixed.
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: '1fr auto auto', gap: '0 14px',
        alignItems: 'center', fontSize: 'var(--text-xs)', letterSpacing: 'var(--tracking-wide)', textTransform: 'uppercase',
        color: GP_T.dim, paddingBottom: 6, borderBottom: '1px solid ' + GP_T.line }}>
        <div>Lever</div><div style={{ textAlign: 'right' }}>Certain effect</div>
        <div style={{ textAlign: 'right' }}>Affordable spend</div>
      </div>

      {levers.map(function (l, i) {
        var gain = Number(l.ceiling_multiplier_mid) - 1;
        var certain = l.cm_effect_pct != null
          ? 'margin +' + (Number(l.cm_effect_pct) * 100).toFixed(1) + '%'
          : 'new-customer cost ' + (Number(l.cac_effect_pct) >= 0 ? '+' : '−') + (Math.abs(Number(l.cac_effect_pct)) * 100).toFixed(1) + '%';
        return (
          <div key={i} style={{ display: 'grid', gridTemplateColumns: '1fr auto auto',
            gap: '0 14px', alignItems: 'center', padding: '9px 0',
            borderBottom: '1px solid ' + GP_T.line }}>
            <div>
              <div style={{ fontSize: 'var(--text-sm)', color: GP_T.ink }}>{LABEL[l.lever] || l.lever}</div>
              <div style={{ fontSize: 'var(--text-xs)', color: GP_T.dim, marginTop: 2 }}>
                moves the {l.moves === 'line' ? 'line' : 'curve'}
              </div>
              <div style={{ height: 3, marginTop: 5, background: GP_T.line, borderRadius: 'var(--radius-sm)' }}>
                <div style={{ height: 3, width: Math.max(2, (gain / max) * 100) + '%',
                  background: GP_T.accent, borderRadius: 'var(--radius-sm)' }} />
              </div>
            </div>
            <div style={{ textAlign: 'right', fontSize: 'var(--text-sm)', fontFamily: GP_T.mono, color: GP_T.mut }}>
              {certain}
            </div>
            <div style={{ textAlign: 'right', fontSize: 'var(--text-sm)', fontFamily: GP_T.mono, color: GP_T.ink }}>
              +{Math.round(gain * 100)}%
            </div>
          </div>
        );
      })}

      <div style={{ fontSize: 'var(--text-xs)', color: GP_T.dim, lineHeight: 1.6, marginTop: 12 }}>
        <b style={{ color: GP_T.mut }}>Certain effect</b> is arithmetic — it holds whatever your curve
        turns out to be. <b style={{ color: GP_T.mut }}>Affordable spend</b> is modelled through β and
        carries its full interval{p.ciAdmitsNoCeiling ? ', which here is open at the flat end' : ''}.
        These are not independent dials: bundling that lifts order value often costs conversion.
      </div>
    </div>
  );
}

// Split for UI V3 (2026-09-25): `show` picks which half renders — 'goal' (readiness,
// costs and the quarter goal) or 'growth' (forecast, channel targets, spend curve).
// Default 'all' keeps the original combined panel for the pre-V3 app.
// Costs used to be typed into three other places that only ever saved to this browser
// (the cost modal, the profit-breakdown card, the cash editor). Those surfaces now send
// people here, so anything they left behind is offered back as a suggestion — filled into
// the form, never saved on their behalf.
// The per-order lines a brand may enter as £ per order or as % of sales, and every variable_costs
// key this page owns. One definition: SQL reads the same keys through fn_vc_per_order / fn_vc_pct.
var GP_LINES = ['shipping', 'packaging', 'fulfilment', 'other'];
var GP_VC_KEYS = ['payPct', 'payFixed', 'refundPct'].concat(GP_LINES, GP_LINES.map(function (k) { return k + 'Pct'; }));
var GP_LINE_LABEL = { shipping: 'Shipping', packaging: 'Packaging', fulfilment: 'Pick, pack and dispatch', other: 'Other per-order costs' };
function GP_BrowserCosts({ econ, setEcon }) {
  var stash = React.useMemo(function () {
    try {
      var c = JSON.parse(localStorage.getItem('frkl-contrib-inputs') || '{}') || {};
      var cash = JSON.parse(localStorage.getItem('oi_cash_v1') || 'null');
      var keys = ['shipping', 'packaging', 'fulfilment', 'payPct', 'payFixed', 'refundPct'];
      var found = keys.filter(function (k) { return c[k] != null && c[k] !== ''; });
      if (!found.length && !(cash && cash.overheads)) return null;
      return { c: c, cash: cash, found: found };
    } catch (e) { return null; }
  }, []);
  var d = React.useState(false), done = d[0], setDone = d[1];
  if (!stash || done || !econ) return null;
  var use = function () {
    var next = Object.assign({}, econ);
    stash.found.forEach(function (k) { if (!next[k]) next[k] = String(stash.c[k]); });
    if (stash.cash && stash.cash.overheads && !next.fixed) next.fixed = String(stash.cash.overheads);
    setEcon(next); setDone(true);
  };
  return (
    <div style={{ border: '1px solid ' + GP_T.accent, background: 'var(--accent-bg)', padding: '10px 12px', marginBottom: 12, fontSize: 'var(--text-sm)', display: 'flex', gap: 10, alignItems: 'center', flexWrap: 'wrap' }}>
      <span>Costs were saved in this browser before ({stash.found.join(', ') || 'monthly overheads'}). They were never sent to Greta.</span>
      <button onClick={use} style={{ minHeight: 36, padding: '0 12px', border: '1px solid ' + GP_T.accent, background: GP_T.accent, color: PAL.panel, borderRadius: 'var(--radius-md)', fontFamily: 'inherit', fontSize: 'var(--text-sm)', fontWeight:'var(--weight-semi)', cursor: 'pointer' }}>Fill them in</button>
      <button onClick={function () { setDone(true); }} style={{ minHeight: 36, padding: '0 12px', border: '1px solid ' + GP_T.line, background: 'transparent', color: GP_T.mut, borderRadius: 'var(--radius-md)', fontFamily: 'inherit', fontSize: 'var(--text-sm)', cursor: 'pointer' }}>Ignore</button>
    </div>
  );
}

function GretaPlanPanel({ show } = {}) {
  var SHOW = show || 'all';
  var isGoal = SHOW === 'all' || SHOW === 'goal';
  var isGrowth = SHOW === 'all' || SHOW === 'growth';
  // V3 shows readiness on its own at the foot of Goal & costs (show="readiness"); the goal half no
  // longer opens on a checklist.
  var isReady = SHOW === 'all' || SHOW === 'readiness' || (SHOW === 'goal' && !UI_V3);
  // The baseline rows quoted vw_brand_plan_readiness's own figures — the fit engine's 57% margin, a
  // £20 customer and a £49 customer value — beside pages showing 61%, £39 and £59. Show the app's.
  var ueQ = useV3Rows('cust-ue', V3_UE_Q);
  var UE = (ueQ.rows || [])[0] || null;
  var canon = {
    'Contribution margin %': oiCmRatio() != null ? fmtPctN(oiCmRatio()) : null,
    'New-customer CAC': UE && Number(UE.cac) > 0 ? fmtMoney(UE.cac) + ' · last 90 days' : null,
    'Cohort LTV': UE && Number(UE.ltv_contribution) > 0 ? fmtMoney(UE.ltv_contribution) + ' · first year' : null
  };
  var P = (typeof window !== 'undefined' && window.FRKL_PLAN) || { readiness: [], goal: null, period: { start: '', end: '' } };
  // The Growth feeds are fetched here rather than on page load: two of them take 26s and 10s,
  // and they were holding connections on every screen, not just this one. Asking for them when
  // this panel actually mounts costs nothing anywhere else. Idempotent in the loader.
  React.useEffect(function () {
    if (isGrowth && window.FRKL_PLAN && window.FRKL_PLAN.loadDetail) window.FRKL_PLAN.loadDetail();
  }, [isGrowth]);
  var s = React.useState(0), tick = s[0], setTick = s[1];
  var b = React.useState('cam'), basis = b[0], setBasis = b[1];
  var a = React.useState(''), amount = a[0], setAmount = a[1];
  var d = React.useState(null), derived = d[0], setDerived = d[1];
  var z = React.useState(false), busy = z[0], setBusy = z[1];
  var m = React.useState(null), msg = m[0], setMsg = m[1];
  var ec = React.useState(null), econ = ec[0], setEcon = ec[1];
  var em = React.useState(null), ecMsg = em[0], setEcMsg = em[1];

  React.useEffect(function () {
    var h = function () { setTick(function (x) { return x + 1; }); };
    window.addEventListener('frkl-plan-updated', h);
    // In V3 the page lead (V3GoalLead) already runs the pace plan; a second and third copy here (one per
    // mounted half) ran fn_plan_quarter four times at once and timed out under load. The setter works
    // the plan out when asked.
    if (window.FRKL_PLAN && !derived && !UI_V3) window.FRKL_PLAN.derive(null, 'auto').then(function (r) { if (r) setDerived(r); });
    return function () { window.removeEventListener('frkl-plan-updated', h); };
  }, []);

  // Goal & costs' "Re-plan the quarter" fills the setter and works the plan out on the current model.
  React.useEffect(function () {
    if (!(SHOW === 'goal' || SHOW === 'all')) return;
    var h = function (e) {
      var q = (e && e.detail) || {};
      setBasis(q.basis || 'revenue'); setAmount(q.amount != null ? String(q.amount) : ''); setBusy(true); setMsg(null);
      window.FRKL_PLAN.derive(q.amount == null ? null : q.amount, q.amount == null ? 'auto' : (q.basis || 'revenue')).then(function (r) { setDerived(r); setBusy(false); });
    };
    window.addEventListener('greta-replan', h);
    return function () { window.removeEventListener('greta-replan', h); };
  }, []);
  React.useEffect(function () {
    // A brand with no saved costs has no config row: start it on an empty form, not "Loading…".
    var c = window.FRKL_PLAN && (window.FRKL_PLAN.config || (window.FRKL_PLAN.configLoaded ? {} : null));
    if (c && econ === null) {
      var v = c.variable_costs || {};
      var next = {
        gm: c.gross_margin != null ? String(Math.round(c.gross_margin * 1000) / 10) : '',
        fixed: c.fixed_costs_monthly != null ? String(c.fixed_costs_monthly) : '',
        payPct: v.payPct != null ? String(v.payPct) : '', payFixed: v.payFixed != null ? String(v.payFixed) : '',
        refundPct: v.refundPct != null ? String(v.refundPct) : ''
      };
      // Shipping, packaging, dispatch and other are each stored as £ per order OR % of sales (0221).
      GP_LINES.forEach(function (k) {
        var pct = v[k + 'Pct'];
        next[k + 'U'] = pct != null ? 'pct' : 'gbp';
        next[k] = pct != null ? String(pct) : (v[k] != null ? String(v[k]) : '');
      });
      setEcon(next);
    }
  }, [tick]);

  var readiness = P.readiness || [];
  var blocking = readiness.filter(function (r) { return r.blocks_targets && r.status !== 'ready'; });
  var readyCount = readiness.filter(function (r) { return r.status === 'ready'; }).length;
  var sections = {};
  readiness.forEach(function (r) { (sections[r.section] = sections[r.section] || []).push(r); });

  function calc() {
    setBusy(true); setMsg(null);
    window.FRKL_PLAN.derive(amount === '' ? null : amount, amount === '' ? 'auto' : basis).then(function (r) { setDerived(r); setBusy(false); });
  }
  function confirm() {
    if (!derived) return;
    setBusy(true); setMsg(null);
    window.FRKL_PLAN.confirm(derived).then(function (res) {
      setBusy(false); setMsg(res.ok ? 'ok' : ('err:' + (res.error || 'failed')));
      if (res.ok) { try { window.dispatchEvent(new Event('greta-goal-updated')); } catch (e) {} }
    });
  }

  function saveEcon() {
    if (!econ) return;
    setBusy(true); setEcMsg(null);
    var base = (window.FRKL_PLAN.config && window.FRKL_PLAN.config.variable_costs) || {};
    // The blob is replaced whole, so rebuild every key this form owns (a line switched from £ to %
    // must lose its £ key) and keep anything else that is in there.
    var vc = {};
    Object.keys(base).forEach(function (k) { if (GP_VC_KEYS.indexOf(k) < 0) vc[k] = base[k]; });
    var bad = null;
    ['payPct', 'payFixed', 'refundPct'].forEach(function (k) { if (econ[k] !== '' && econ[k] != null) vc[k] = Number(econ[k]); });
    GP_LINES.forEach(function (k) {
      if (econ[k] === '' || econ[k] == null) return;
      var n = Number(econ[k]);
      if (econ[k + 'U'] === 'pct') { if (n > 100) bad = 'A percentage of sales can’t be more than 100.'; vc[k + 'Pct'] = n; } else vc[k] = n;
    });
    ['payPct', 'refundPct'].forEach(function (k) { if (vc[k] > 100) bad = 'A percentage of sales can’t be more than 100.'; });
    if (bad) { setBusy(false); setEcMsg('err:' + bad); return; }
    var fields = { gross_margin: econ.gm === '' ? null : Number(econ.gm) / 100, fixed_costs_monthly: econ.fixed === '' ? null : Number(econ.fixed), variable_costs: vc };
    window.FRKL_PLAN.saveEconomics(fields).then(function (res) { setBusy(false); setEcMsg(res.ok ? 'ok' : ('err:' + (res.error || 'failed'))); });
  }
  function setE(k, val) { setEcon(function (o) { var n = Object.assign({}, o); n[k] = val.replace(/[^0-9.]/g, ''); return n; }); }

  // No inset of its own: the page sets the edges, and every section sits on them (it was 6px in).
  var wrap = { color: GP_T.ink };
  // The plan feed never starts when the workspace did not load, so "Loading…" would wait for ever.
  var gpLiveDown = !!(window.FRKL_LIVE && window.FRKL_LIVE.session && !window.FRKL_LIVE.brandId && /^(error|static-only)$/.test(window.FRKL_LIVE.status || ''));
  var cfg = (window.FRKL_PLAN && window.FRKL_PLAN.config) || null;
  var perDays = (P.period && P.period.start && P.period.end) ? Math.max(1, Math.round((new Date(P.period.end) - new Date(P.period.start)) / 864e5) + 1) : 90;
  var fixedForPeriod = cfg && cfg.fixed_costs_monthly ? Number(cfg.fixed_costs_monthly) * (perDays / 30) : 0;
  var opTarget = derived ? (Number(derived.cam_target || 0) - fixedForPeriod) : null;
  var targetCac = (derived && derived.new_customer_target > 0) ? (derived.spend_cap / derived.new_customer_target) : null;
  var g = P.goal;

  return (
    <div style={wrap} className="gp-wrap">
      {/* The page head already names the page and asks its question; this only says which period. */}
      {!(UI_V3 && SHOW !== 'growth') && <div className="v3-kick">This quarter · {v3Day(P.period.start)} – {v3Day(P.period.end, true)}</div>}

      {/* readiness gate */}
      {isReady && (<div style={{ borderTop: '1px solid ' + GP_T.line, padding: 'var(--space-6) 0', marginBottom: 16 }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 10 }}>
          <h2 className="v3-sec-title gp-h">Data readiness</h2>
          {/* "0 of 0 ready · ready to plan" was what a failed read looked like. */}
          {readiness.length
            ? <div style={{ fontSize: 'var(--text-sm)', color: blocking.length ? GP_T.amber : GP_T.green }}>{readyCount} of {readiness.length} ready{blocking.length ? ' · ' + blocking.length + ' still needed before Greta can set targets' : ' · ready to plan'}</div>
            : <div style={{ fontSize: 'var(--text-sm)', color: GP_T.dim }}>{gpLiveDown ? 'Couldn’t check your data' : (window.FRKL_PLAN && window.FRKL_PLAN.readinessErr) ? 'Couldn’t check your data just now' : 'Checking your data…'}</div>}
        </div>
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill,minmax(300px,1fr))', gap: '6px 22px' }}>
          {Object.keys(sections).map(function (sec) {
            return (
              <div key={sec}>
                <div style={{ fontSize: 'var(--text-xs)', color: GP_T.dim, textTransform: 'uppercase', letterSpacing: 'var(--tracking-wide)', margin: '4px 0 3px' }}>{sec}</div>
                {sections[sec].map(function (r, i) {
                  return (
                    <div key={i} style={{ display: 'flex', alignItems: 'center', gap: 8, padding: '3px 0', fontSize: 'var(--text-sm)' }}>
                      <GP_Dot c={r.status !== 'ready' && !r.blocks_targets ? 'var(--color-line-strong)' : GP_rag(r.status)} />
                      <span style={{ flex: 1 }}>{GP_PLAIN_ITEM[r.item] || r.item}</span>
                      <span className="oi-num" style={{ color: GP_T.dim, fontSize: 'var(--text-xs)', whiteSpace: 'nowrap' }}>{(UI_V3 && r.status === 'ready' && canon[r.item]) || GP_plainDetail(r)}</span>
                    </div>
                  );
                })}
              </div>
            );
          })}
        </div>
      </div>)}

      {isGrowth && !UI_V3 && (<GP_ChannelHealth h={P.channelHealth}/>)}
      {/* "Where revenue comes from" repeated the lead section's "Where your sales came from" (same view). */}

      {/* economics editor — operating costs feed Operating Profit on the Overview */}
      {isGoal && SHOW !== 'readiness' && (<div style={{ borderTop: '1px solid ' + GP_T.line, padding: 'var(--space-6) 0', marginBottom: 16 }}>
        <V3Anchor id="margin"/>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 4 }}>
          <h2 className="v3-sec-title gp-h">What things cost you</h2>
          <span style={{ fontSize: 'var(--text-xs)', color: GP_T.dim }}>used in every profit figure</span>
        </div>
        <GP_BrowserCosts econ={econ} setEcon={setEcon} />
        <div style={{ fontSize: 'var(--text-sm)', color: GP_T.dim, marginBottom: 'var(--space-3)' }}>Overheads are what you pay every month whatever you sell — rent, wages, software. Operating profit is your profit after ads, less these.</div>
        {econ ? (
          <div>
            {/* One place for what the business and each order cost (0221). Units sit inside the box:
                currency before, % after. */}
            <div className="v3-form-grid">
              {[['gm', 'Margin on products without a cost', '', '%'], ['fixed', 'Overheads a month', '£', '']].map(function (f) {
                return (
                  <label key={f[0]} className="v3-field">
                    <span>{f[1]}</span>
                    <span className="v3-affix" data-pre={f[2] ? curSym() : undefined} data-post={f[3] || undefined}>
                      <input className="oi-num" inputMode="decimal" value={econ[f[0]]} onChange={function (e) { setE(f[0], e.target.value); }} />
                    </span>
                  </label>
                );
              })}
            </div>
            <p className="v3-note v3-measure">Product costs come from Shopify, one product at a time, under “Product costs” below. The margin here only fills in for products that have no cost yet.</p>

            <h3 className="v3-sub v3-gap-top">Each order</h3>
            <p className="v3-note v3-measure">Enter each one the way your invoices show it — a fixed amount per order, or a share of sales.</p>
            <div className="v3-form-grid">
              {GP_LINES.map(function (k) {
                var pct = econ[k + 'U'] === 'pct';
                var setU = function (u) { setEcon(function (o) { var n = Object.assign({}, o); n[k + 'U'] = u; return n; }); };
                return (
                  <div key={k} className="v3-field">
                    <span className="v3-field-head"><span>{GP_LINE_LABEL[k]}</span>
                      <span className="v3-unit" role="group" aria-label={GP_LINE_LABEL[k] + ': per order or share of sales'}>
                        <button type="button" aria-pressed={!pct} onClick={function () { setU('gbp'); }}>{curSym()} per order</button>
                        <button type="button" aria-pressed={pct} onClick={function () { setU('pct'); }}>% of sales</button>
                      </span></span>
                    <span className="v3-affix" data-pre={pct ? undefined : curSym()} data-post={pct ? '%' : undefined}>
                      <input className="oi-num" inputMode="decimal" aria-label={GP_LINE_LABEL[k]} value={econ[k]} onChange={function (e) { setE(k, e.target.value); }} />
                    </span>
                  </div>
                );
              })}
            </div>
            <div className="v3-form-grid v3-gap-top">
              {[['payPct', 'Payment fee', '', '%'], ['payFixed', 'Payment fee per order', '£', ''], ['refundPct', 'Refunds', '', '% of sales']].map(function (f) {
                return (
                  <label key={f[0]} className="v3-field">
                    <span>{f[1]}</span>
                    <span className="v3-affix" data-pre={f[2] ? curSym() : undefined} data-post={f[3] || undefined}>
                      <input className="oi-num" inputMode="decimal" value={econ[f[0]]} onChange={function (e) { setE(f[0], e.target.value); }} />
                    </span>
                  </label>
                );
              })}
            </div>
            <div style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-3)', marginTop: 'var(--space-4)', flexWrap: 'wrap' }}>
              <button className="v3-btn v3-btn-p" onClick={saveEcon} disabled={busy}>{busy ? 'Saving…' : 'Save costs'}</button>
              {ecMsg === 'ok' && <span style={{ color: GP_T.green, fontSize: 'var(--text-sm)' }}>Saved — every profit figure now uses these costs.</span>}
              {ecMsg && ecMsg.indexOf('err') === 0 && <span style={{ color: GP_T.red, fontSize: 'var(--text-sm)' }}>{ecMsg.slice(4)}</span>}
              
            </div>
          </div>
        ) : (
          <div style={{ fontSize: 'var(--text-sm)', color: GP_T.dim }}>{gpLiveDown ? v3NoBrand('your costs') : (window.FRKL_PLAN && window.FRKL_PLAN.configErr) ? 'Greta couldn’t load your costs just now. Refreshing the page usually sorts it.' : 'Loading your costs…'}</div>
        )}
      </div>)}

      {/* "Forecast vs goal" used to repeat here, comparing the after-ads forecast with the BEFORE-ads
          target (contribution_margin_target). The lead section of Growth plan shows it once, against
          the after-ads goal. Removed 2026-10-02. */}
      {/* channel efficiency vs targets — CTC: CM-first, normalized iROAS, fix before scale */}
      {isGrowth && !UI_V3 && P.channels && P.channels.length ? (
        <div style={{ borderTop: '1px solid ' + GP_T.line, padding: 'var(--space-6) 0', marginBottom: 16 }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 10 }}>
            <h2 className="v3-sec-title gp-h">Channel efficiency vs targets</h2>
            <button onClick={function () { window.FRKL_PLAN.deriveChannelPlan(true); }} style={{ fontSize: 'var(--text-xs)', color: GP_T.mut, background: 'none', border: '1px solid ' + GP_T.line, borderRadius: 'var(--radius-md)', padding: '4px 9px', cursor: 'pointer' }}>{(P.channels[0] && P.channels[0].plan_confirmed) ? 'Re-derive plan from goal' : 'Set plan from goal'}</button>
          </div>
          <table style={{ width: '100%', fontSize: 'var(--text-sm)', borderCollapse: 'collapse' }}>
            <thead><tr style={{ color: GP_T.mut, fontSize: 'var(--text-xs)' }}>
              <th style={{ textAlign: 'left', fontWeight:'var(--weight-normal)' }}>Channel</th>
              <th style={{ textAlign: 'right', fontWeight:'var(--weight-normal)' }}>Spend 30d</th>
              <th style={{ textAlign: 'right', fontWeight:'var(--weight-normal)' }}>Real return per £</th>
              <th style={{ textAlign: 'right', fontWeight:'var(--weight-normal)' }}>New-customer cost</th>
              <th style={{ textAlign: 'right', fontWeight:'var(--weight-normal)' }}>Planned</th>
              <th style={{ textAlign: 'right', fontWeight:'var(--weight-normal)' }}>Pace</th>
              <th style={{ textAlign: 'right', fontWeight:'var(--weight-normal)', paddingLeft: 10 }}>Verdict</th>
            </tr></thead>
            <tbody>
              {P.channels.map(function (c, i) {
                var col = c.status === 'fix' ? GP_T.red : c.status === 'scale' ? GP_T.green : c.status === 'ease' ? GP_T.amber : GP_T.mut;
                var pace = c.spend_pace_pct_of_plan;
                var paceCol = pace == null ? GP_T.dim : ((c.status === 'fix' && pace > 100) || pace > 140) ? GP_T.red : pace < 80 ? GP_T.amber : GP_T.dim;
                var tgt = c.plan_target_iroas != null ? c.plan_target_iroas : (c.target_marginal_iroas != null ? c.target_marginal_iroas : c.break_even_iroas);
                return (
                  <tr key={i} style={{ borderTop: '1px solid ' + GP_T.line }}>
                    <td style={{ textAlign: 'left', padding: '4px 0' }}>{String(c.channel_type).replace(/_/g, ' ')}</td>
                    <td style={{ textAlign: 'right', fontFamily: GP_T.mono }}>{GP_gbp(c.spend_30d)}</td>
                    <td style={{ textAlign: 'right', fontFamily: GP_T.mono, color: col }}>{Number(c.avg_iroas).toFixed(2)}×</td>
                    {/* The measured cost of a new customer on this channel, red above what one is worth on the
                        first order (or the plan's own cap). It showed the plan's TARGET under this heading,
                        coloured against a fixed £100. */}
                    <td style={{ textAlign: 'right', fontFamily: GP_T.mono, color: (function () { var cap = c.plan_target_cac != null ? Number(c.plan_target_cac) : (c.max_cac_first_order != null ? Number(c.max_cac_first_order) : null); return (c.marginal_cac != null && cap != null && Number(c.marginal_cac) > cap) ? GP_T.red : GP_T.dim; })() }}>{c.marginal_cac == null ? '—' : fmtMoney(c.marginal_cac, 2)}</td>
                    <td style={{ textAlign: 'right', fontFamily: GP_T.mono }}>{c.planned_spend == null ? '—' : GP_gbp(c.planned_spend)}</td>
                    <td style={{ textAlign: 'right', fontFamily: GP_T.mono, color: paceCol }}>{pace == null ? '—' : pace + '%'}</td>
                    <td style={{ textAlign: 'right', color: col, fontSize: 'var(--text-xs)', paddingLeft: 10 }}>{({ fix: 'Fix first', scale: 'Spend more', ease: 'Ease off', hold: 'Hold' })[c.status] || v3Sentence(String(c.status || '—').replace(/_/g, ' '))}</td>
                  </tr>
                );
              })}
            </tbody>
          </table>
          <div style={{ fontSize: 'var(--text-xs)', color: GP_T.dim, marginTop: 8 }}>
            Focus: <b style={{ color: GP_T.ink }}>{String(P.channels[0].channel_type).replace(/_/g, ' ')}</b> — {P.channels[0].action}
            {P.channels[0].phi_is_assumed ? <span> · real return on ad spend uses <b>benchmark</b> incrementality (φ), not yet measured — run a holdout to confirm.</span> : null}
          </div>
        </div>
      ) : null}

      {isGrowth && (<GP_SpendCurve curve={P.spendCurve} points={P.spendCurvePoints} />)}
      {/* What the engine already knew about that curve but never showed (views live since 0145). */}
      {isGrowth && (<GP_CurveConstraint dec={P.curveDecomposition} beta={P.spendCurve && P.spendCurve.beta} />)}
      {isGrowth && (<GP_CurveHistory rows={P.curveHistory} />)}
      {isGrowth && (<GP_CurveLevers levers={P.curveLevers} verdict={P.spendCurve && P.spendCurve.verdict}
                                    ciAdmitsNoCeiling={!!(P.spendCurve && P.spendCurve.band_admits_no_ceiling)} />)}

      {/* goal setter */}
      {isGoal && (<div className="v3-raised" style={{ padding: 'var(--space-6)' }}>
        <V3Anchor id="goal-set"/>
        <h2 style={{ margin: '0 0 var(--space-1)' }}>{UI_V3 && g ? 'Change this quarter’s goal' : 'Set this quarter’s goal'}</h2>
        <p className="micro muted" style={{ margin: '0 0 var(--space-4)' }}>Pick what you want to aim for. Greta works out the sales, ad budget and new customers it takes.</p>
        <div style={{ display: 'flex', gap: 'var(--space-3)', alignItems: 'flex-end', flexWrap: 'wrap' }}>
          <div className="v3-seg" role="group" aria-label="Goal basis">
            <button aria-pressed={basis === 'cam'} onClick={function () { setBasis('cam'); }}>Profit after ads</button>
            <button aria-pressed={basis === 'revenue'} onClick={function () { setBasis('revenue'); }}>Sales</button>
          </div>
          <div>
            <div style={{ fontSize: 'var(--text-xs)', color: GP_T.mut, marginBottom: 'var(--space-1)' }}>{basis === 'cam' ? 'Profit after ads' : 'Sales'} for the quarter (£)</div>
            <input className="oi-num" inputMode="decimal" value={amount} onChange={function (e) { setAmount(e.target.value.replace(/[^0-9.]/g, '')); }} placeholder={basis === 'cam' ? 'e.g. 25000' : 'e.g. 90000'} />
          </div>
          <button className="v3-btn" onClick={calc} disabled={busy}>{busy ? 'Working it out…' : 'Work out the plan'}</button>
          <span style={{ fontSize: 'var(--text-xs)', color: GP_T.dim }}>Leave it blank to see where your current pace lands.</span>
        </div>

        {/* Only render targets Greta actually derived. When the derivation returns nothing the tiles
            used to print "NaN", "MER undefined" and "aMER undefined" — a new brand saw that first. */}
        {derived && derived.revenue_target == null && (
          <p className="v3-note" style={{ marginTop: 'var(--space-4)' }}>{derived.message || 'Greta could not work a goal out from your trading yet — it needs a full month of sales.'} You can still type the goal you have in mind above.</p>
        )}
        {derived && derived.revenue_target != null && (
          <div style={{ marginTop: 'var(--space-5)' }}>
            <div className="v3-stat-grid">
              <GP_Metric k="Sales" v={GP_gbp(derived.revenue_target)} sub="for the quarter" />
              <GP_Metric k="Profit before ads" v={GP_gbp(derived.product_cm_target)} sub={derived.cm_ratio_used != null ? fmtPctN(derived.cm_ratio_used) + ' of sales' : ''} />
              <GP_Metric k="Profit after ads" v={GP_gbp(derived.cam_target)} hi={true} sub="the number Today paces against" />
              <GP_Metric k="Ad budget" v={GP_gbp(derived.spend_cap)} sub={derived.mer_target != null ? Number(derived.mer_target).toFixed(1) + '× sales per £ of ads' : ''} />
              <GP_Metric k="New customers" v={fmtCount(derived.new_customer_target)} sub={derived.amer_used != null ? Number(derived.amer_used).toFixed(1) + '× new-customer sales per £ of ads' : ''} />
              <GP_Metric k="Sales from returning customers" v={GP_gbp(derived.returning_revenue_target)} sub="at your current rate" />
              <GP_Metric k="Average cost per new customer" v={fmtMoney(targetCac, 2)} hi={true} sub="ad budget ÷ new customers" />
              <GP_Metric k="Operating profit" v={opTarget == null ? '—' : GP_gbp(opTarget)} sub={fixedForPeriod > 0 ? 'after ' + GP_gbp(fixedForPeriod) + ' of overheads' : 'add your overheads above'} />
            </div>
            <GP_PlanBreakdown d={derived}/>
            {g && !UI_V3 && (
              <div style={{ fontSize: 'var(--text-xs)', color: GP_T.dim, marginTop: 'var(--space-2)' }}>
                Current goal ({g.confirmed ? 'confirmed' : 'not yet confirmed'}): sales {GP_gbp(g.revenue_target)} · profit before ads {GP_gbp(g.contribution_margin_target)} · ad budget {GP_gbp(g.spend_cap)}
              </div>
            )}
            <div style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-3)', marginTop: 'var(--space-4)', flexWrap: 'wrap' }}>
              <button className="v3-btn v3-btn-p" onClick={confirm} disabled={busy}>Make this my plan</button>
              {msg === 'ok' && <span style={{ color: GP_T.green, fontSize: 'var(--text-sm)' }}>Done — Today now tracks your pace against this plan.</span>}
              {msg && msg.indexOf('err') === 0 && <span style={{ color: GP_T.red, fontSize: 'var(--text-sm)' }}>{msg.slice(4)}</span>}
              <span style={{ fontSize: 'var(--text-xs)', color: GP_T.dim }}>{derived.months ? 'Confirming stores the month-by-month plan, and Today paces against it.' : 'Worked out from what you keep after product and order costs (' + fmtPctN(derived.cm_ratio_used) + ').'}</span>
            </div>
          </div>
        )}
      </div>)}
    </div>
  );
}

