// Anchor target for a deep link that used to open a sub-tab.
function V3Anchor({ id }) {
  const ref = React.useRef(null);
  React.useEffect(() => {
    const go = () => {
      if (window.__oiV3Anchor === id && ref.current) {
        window.__oiV3Anchor = null;
        // The page above the anchor is usually still loading, so its position moves after the
        // first scroll. Re-align as it settles — unless the person has started scrolling.
        let touched = false;
        const stop = () => { touched = true; };
        ['wheel', 'touchmove', 'keydown'].forEach(ev => window.addEventListener(ev, stop, { once: true, passive: true }));
        [60, 700, 1600, 3000].forEach((ms, i) => setTimeout(() => {
          if (touched || !ref.current) return;
          const top = ref.current.getBoundingClientRect().top;
          if (i === 0 || Math.abs(top) > 24) { try { ref.current.scrollIntoView({ behavior: i === 0 ? 'smooth' : 'auto', block: 'start' }); } catch (e) {} }
        }, ms));
      }
    };
    go();
    // A jump on the page already open does not re-render this anchor, so it listens as well.
    window.addEventListener('oi-v3-anchor', go);
    return () => window.removeEventListener('oi-v3-anchor', go);
  });
  return <span ref={ref} id={'v3-' + id} className="v3-anchor"/>;
}

// The nav is the only thing on every screen, so it is the cheapest place to make the product feel
// connected rather than like sixteen separate pages. Both signals come from GRETA_HEADLINE, which
// Today has already loaded — no extra request, and nothing renders until there is something true
// to say.
function useV3NavSignals() {
  const [sig, setSig] = React.useState(() => ({}));
  const board = useV3Board();
  React.useEffect(() => {
    const read = () => {
      const h = (typeof window !== 'undefined' && window.GRETA_HEADLINE) || null;
      if (!h) return;
      setSig({
        actions: Number(h.board_actions) || 0,
        feedAlert: h.spend_is_stale === true,
      });
    };
    read();
    window.addEventListener('greta-headline-updated', read);
    return () => window.removeEventListener('greta-headline-updated', read);
  }, []);
  // Same count as the Actions page lists, once the board has landed.
  return board.rows ? { ...sig, actions: board.rows.length } : sig;
}

// The one number the whole product is about, carried onto every other page.
//
// The 16 destinations each answer a good question, but once you leave Today nothing
// on screen says what you are trying to move. An operator reading channel iROAS or
// stock cover is three clicks from the profit figure those numbers exist to change,
// and has to remember it. That is the difference between a tour of dashboards and a
// journey through one business.
//
// So: profit after ads and the pace sentence, in one line, on every page but Today
// (where the hero already says it) -- same values, same formatter and same wording
// as V3Today, read from the same GRETA_HEADLINE row, so the thread can never say
// something the hero does not. Click it to go back to the top of the story.
function V3Thread({ dest, go }) {
  const h = useV3Headline();
  const gc = useV3GoalCheck();
  if (!h || dest === 'today') return null;
  if (h.can_show_cm === false) return null;
  const cam = h.cm_after_marketing_30d;
  if (cam == null) return null;
  const target = h.cam_target_monthly;
  const diff = target != null ? cam - target : null;
  const unreliable = h.pace_is_reliable === false;
  return (
    <button type="button" className="v3-thread" onClick={() => go('today')}
            title="Back to Today">
      <span className="v3-thread-lab">Profit after ads</span>
      <span className="v3-thread-val">{v3Gbp(cam)}</span>
      <span className="v3-muted">last 30 days</span>
      {diff != null && (gc.stale || gc.early) && !gc.pending && (
        <span className="v3-thread-pace">{gc.stale ? 'goal needs re-planning' : 'goal pace from ' + v3Day(gc.paceFrom)}</span>
      )}
      {diff != null && !(gc.stale || gc.early || gc.pending) && (
        <span className={'v3-thread-pace' + (unreliable ? '' : diff >= 0 ? ' good' : ' bad')}>
          {unreliable
            ? 'pace too close to call'
            : (diff >= 0 ? v3Gbp(Math.abs(diff)) + ' ahead' : v3Gbp(Math.abs(diff)) + ' behind')}
        </span>
      )}
    </button>
  );
}

// Mono on the figures the stylesheet cannot reach.
//
// The house rule is mono for anything countable and sans for language. In the deep pages
// most figures live in table cells, and CSS has no way to tell "GBP 1,317" from "Gold Charm
// Necklace" -- so a blanket `td { font-family: mono }` would set every product name in a
// typewriter face, and doing it properly in JSX is a class on several hundred call sites.
//
// This tags leaf elements whose ENTIRE text is a figure, and the stylesheet does the rest
// via .oi-num. Presentation only: it adds one class, never changes text or structure. Cheap
// and safe to re-run -- leaves only, skips anything already tagged, bails on long strings
// before the regex, and is rAF-debounced so a burst of renders costs one pass. If React
// rewrites a className the next pass puts it back.
// A figure, a short date (06-13, 2026-09-29) or a figure with a unit. Anything with a
// letter run in it is language and is left alone.
const OI_NUM_RE = /^([-+]?[£$€]?\s?[\d,]+(\.\d+)?\s?(%|pp|x|×|\/mo|\/day|\/100|d|k|m)?|\d{1,4}-\d{1,2}(-\d{1,2})?)$/i;
function tagFigures(root) {
  if (!root) return;
  const els = root.querySelectorAll('td,th,span,b,strong,div,em,i,tspan');
  for (let i = 0; i < els.length; i++) {
    const el = els[i];
    if (el.firstElementChild) continue;                 // leaves only
    if (el.classList.contains('oi-num')) continue;
    const t = el.textContent;
    if (!t || t.length > 24) continue;
    const s = t.trim();
    if (s.length < 1 || !OI_NUM_RE.test(s)) continue;
    el.classList.add('oi-num');
  }
}
// Prose gets its measure the same way figures get their typeface: by looking at the
// text, because CSS cannot. A paragraph and a layout row are both an unclassed <div>
// with an inline style, and the sentences that were still running to 217 characters are
// all written that way. Same test as tagFigures - leaves only, judged on content - with
// two extra guards, because capping the width of something that is actually laying out
// its siblings would break a column.
var PROSE_MIN_CHARS = 72, PROSE_MIN_WORDS = 12;
function tagProse(root) {
  if (!root) return;
  // span too: a <span style="display:block"> is a paragraph, and two of the longest
  // lines left in the product were exactly that. The display test below is what keeps
  // an ordinary inline span out.
  const els = root.querySelectorAll('div,p,li,span,section,article');
  for (let i = 0; i < els.length; i++) {
    const el = els[i];
    if (el.classList.contains('v3-prose')) continue;
    const t = el.textContent;
    if (!t || t.length < PROSE_MIN_CHARS) continue;
    const s = t.trim();
    if (s.length < PROSE_MIN_CHARS || s.split(/\s+/).length < PROSE_MIN_WORDS) continue;
    // A paragraph may contain <b> or <a>; it does not contain blocks.
    let lays = false;
    for (let c = el.firstElementChild; c; c = c.nextElementSibling) {
      const d = getComputedStyle(c).display;
      if (d === 'block' || d === 'flex' || d === 'grid' || d === 'table' || d === 'list-item') { lays = true; break; }
    }
    if (lays) continue;
    const cs = getComputedStyle(el);
    if (cs.display !== 'block') continue;
    // Skipping every flex and grid child was too blunt: the description under a step
    // heading and the text beside a bullet are exactly the things that needed capping.
    // What must not be capped is something the layout DRAWS to a width - a bar, a
    // track, a tinted panel. Twelve words of prose is already a strong filter; this
    // is the rest of it.
    if (cs.backgroundImage !== 'none') continue;
    // A LEFT border is the accent bar on a callout, which is drawn to a width. A TOP
    // border is a hairline between stacked things, which is the house separator and
    // sits on plenty of ordinary paragraphs - .board-comm-line among them.
    if (parseFloat(cs.borderLeftWidth)) continue;
    if (el.closest('table')) continue;
    el.classList.add('v3-prose');
  }
}
function useFigureTypography(dep) {
  React.useEffect(() => {
    const main = document.querySelector('.v3-main') || document.querySelector('main');
    if (!main) return;
    // A timer, not requestAnimationFrame: rAF is paused while the tab is hidden, so a
    // dashboard opened in a background tab would render every figure in the wrong face
    // until it was looked at. 50ms coalesces a burst of renders into one pass.
    let t = 0;
    const run = () => { t = 0; try { tagFigures(main); } catch (e) {} try { tagProse(main); } catch (e) {} };
    const schedule = () => { if (!t) t = setTimeout(run, 50); };
    schedule();
    const mo = new MutationObserver(schedule);
    mo.observe(main, { childList: true, subtree: true });
    return () => { mo.disconnect(); if (t) clearTimeout(t); };
  }, [dep]);
}

// ── Walkthroughs ─────────────────────────────────────────────────────────────
// A dashboard shows; a walkthrough tells. The owner picks an area and a horizon on Today, and a
// guide docked to the foot of the screen walks the app page by page: one question per stop, the
// answer in a sentence, the figures against the period before AND the same period last year, and
// the actions that belong to that stop. It ends on one ranked list of what to do.
//
// Every comparison comes from ONE server call, fn_brand_period_compare (0227): complete periods
// (last full week / month / quarter), so a part-week is never set against a whole one, plus the
// same move a year earlier, so a drop can be read against the season. The guide counts nothing
// itself — it only words what the server counted. Where a window is unusable (GA4 break, ad days
// missing, no history yet) the step says so rather than comparing across the hole.
const V3_WALK_H = [
  { id: 'week',    label: 'Short term',  short: 'Week',    sub: 'week on week' },
  { id: 'month',   label: 'Medium term', short: 'Month',   sub: 'month on month' },
  { id: 'quarter', label: 'Medium term', short: 'Quarter', sub: 'quarter on quarter' },
  { id: 'year',    label: 'Long term',   short: 'Year',    sub: 'the last 12 months against the 12 before' },
];
const V3_WALK_HGROUPS = ['Short term', 'Medium term', 'Long term'];
const V3_WALKS = [
  { id: 'business',  label: 'The whole business', q: 'How is the business trading?',
    steps: ['sales', 'profit', 'customers', 'efficiency', 'stock'], cats: null },
  { id: 'products',  label: 'Products', q: 'Which products carry the business, and which are slipping?',
    steps: ['topProducts', 'movers', 'leaks', 'stock'], cats: ['product'] },
  { id: 'marketing', label: 'Marketing', q: 'Is marketing bringing in the right customers?',
    steps: ['traffic', 'customers', 'efficiency', 'retention'], cats: ['site', 'paid'] },
  { id: 'paid',      label: 'Paid ads', q: 'Are the ads paying for themselves?',
    steps: ['spend', 'channels', 'profit'], cats: ['paid'] },
  { id: 'customers', label: 'Customers', q: 'Are customers coming back, and what are they worth?',
    steps: ['customers', 'retention', 'sales'], cats: [] },
  { id: 'stock',     label: 'Stock & operations', q: 'Will anything run out, and is cash stuck on the shelf?',
    steps: ['stock', 'reorder', 'cash', 'leaks'], cats: ['product'] },
  { id: 'npd',       label: 'New products', q: 'Are new products earning their place?',
    steps: ['newProducts', 'adFit', 'stock'], cats: ['product'] },
];

// Store: one walkthrough at a time, shared by the launcher on Today and the dock in the shell.
// The position survives a reload (sessionStorage); the chosen horizon is remembered per viewer.
const V3_WALK = (() => {
  let s = null;
  try { s = JSON.parse(sessionStorage.getItem('greta_walk') || 'null'); } catch (e) {}
  return { id: (s && s.id) || null, step: (s && s.step) || 0, horizon: (s && s.horizon) || null, min: false, subs: new Set() };
})();
function v3WalkSet(patch) {
  Object.assign(V3_WALK, patch);
  try {
    if (V3_WALK.id) sessionStorage.setItem('greta_walk', JSON.stringify({ id: V3_WALK.id, step: V3_WALK.step, horizon: V3_WALK.horizon }));
    else sessionStorage.removeItem('greta_walk');
  } catch (e) {}
  V3_WALK.subs.forEach(f => { try { f(); } catch (e) {} });
}
function v3WalkHorizon() {
  if (V3_WALK.horizon) return V3_WALK.horizon;
  try { const h = localStorage.getItem('greta_walk_h'); if (V3_WALK_H.some(o => o.id === h)) return h; } catch (e) {}
  return 'month';
}
function v3WalkSetHorizon(h) {
  try { localStorage.setItem('greta_walk_h', h); } catch (e) {}
  v3WalkSet({ horizon: h });
}
function v3WalkStart(id, horizon) {
  try { localStorage.setItem('greta_walk_h', horizon); } catch (e) {}
  v3WalkSet({ id: id, step: 0, horizon: horizon, min: false });
  try { track('walkthrough_start', { walk: id, horizon: horizon }, 'today'); } catch (e) {}
}
function v3WalkEnd(toToday) {
  const id = V3_WALK.id;
  if (V3_WALK.savedRange !== undefined && window.__oiSetRange) {
    const r = V3_WALK.savedRange || {};
    window.__oiSetRange(r.s || '', r.e || '', r.p);
  }
  V3_WALK.savedRange = undefined;
  v3WalkSet({ id: null, step: 0, min: false });
  try { track('walkthrough_end', { walk: id }, 'today'); } catch (e) {}
  if (toToday && window.__oiGo) window.__oiGo('today');
}
function useV3Walk() {
  const [, bump] = React.useState(0);
  React.useEffect(() => {
    const f = () => bump(n => n + 1);
    V3_WALK.subs.add(f);
    return () => { V3_WALK.subs.delete(f); };
  }, []);
  return V3_WALK;
}

// ── Wording ──
const V3_MONTH_FULL = ['January','February','March','April','May','June','July','August','September','October','November','December'];
function v3WalkChg(c, p) {
  const a = Number(c), b = Number(p);
  if (c == null || p == null || !isFinite(a) || !isFinite(b) || b === 0) return null;
  return (a - b) / Math.abs(b);
}
// "up 12%", "down 44%", "flat". Under 2% either way is noise, not news.
function v3WalkMove(x) {
  if (x == null) return null;
  return Math.abs(x) < 0.02 ? 'flat' : (x > 0 ? 'up ' : 'down ') + fmtPctN(Math.abs(x));
}
function v3WalkNames(h, P) {
  const mon = iso => V3_MONTH_FULL[Number(String(iso).slice(5, 7)) - 1] || '';
  const yr = iso => String(iso).slice(0, 4);
  const qtr = x => mon(x.start).slice(0, 3) + '–' + mon(x.end).slice(0, 3);
  if (h === 'week') {
    const c = v3Day(P.cur.start);
    return { cur: 'the week of ' + c, prev: 'the week before', ly: 'the same week last year',
             lyPair: 'the same two weeks last year', col: ['Week of ' + c, 'Week before', 'Last year'],
             line: 'Week of ' + c + ' (Mon–Sun), against the week before and the same week last year' };
  }
  if (h === 'year') {
    const span = x => mon(x.start).slice(0, 3) + ' ' + yr(x.start) + '–' + mon(x.end).slice(0, 3) + ' ' + yr(x.end);
    return { cur: 'the last 12 months', prev: 'the 12 months before', ly: 'two years ago', lyPair: null,
             col: ['Last 12 months', '12 months before', 'Two years ago'],
             line: span(P.cur) + ', against the 12 months before (' + span(P.prev) + ')' };
  }
  if (h === 'quarter') {
    const c = qtr(P.cur), p = qtr(P.prev), l = qtr(P.ly) + ' ' + yr(P.ly.start);
    return { cur: c, prev: p, ly: l, lyPair: qtr(P.lyprev) + ' to ' + l, col: [c, p, l],
             line: c + ' ' + yr(P.cur.start) + ', against ' + p + ' and against ' + l };
  }
  const c = mon(P.cur.start), p = mon(P.prev.start), l = mon(P.ly.start) + ' ' + yr(P.ly.start);
  return { cur: c, prev: p, ly: l, lyPair: mon(P.lyprev.start) + ' to ' + l, col: [c, p, l],
           line: c + ' ' + yr(P.cur.start) + ', against ' + p + ' and against ' + l };
}
// "Sales were £28,313 in September — down 44% on August, and up 104% on September 2025."
function v3WalkVs(X, key) {
  const { P, N } = X, bits = [];
  const a = P.prev.has_history ? v3WalkMove(v3WalkChg(P.cur[key], P.prev[key])) : null;
  const b = P.ly.has_history ? v3WalkMove(v3WalkChg(P.cur[key], P.ly[key])) : null;
  if (a) bits.push(a + ' on ' + N.prev);
  if (b) bits.push(b + ' on ' + N.ly);
  return bits.length ? ' — ' + bits.join(', and ') : '';
}
// Is the move from last period normal for the time of year? Set it against the same move a year ago.
function v3WalkSeason(X, key) {
  const { P, N } = X;
  if (!P.lyprev || !P.lyprev.has_history) return null;
  const now = v3WalkChg(P.cur[key], P.prev[key]), then = v3WalkChg(P.ly[key], P.lyprev[key]);
  if (now == null || then == null || Math.abs(now) < 0.05) return null;
  const was = 'Last year the same move (' + N.lyPair + ') was ' + v3WalkMove(then);
  const d = now - then;
  if (Math.abs(d) < 0.08) return was + ', so most of this is the time of year, not a problem.';
  return was + (d < 0 ? ', so this is worse than the season explains.' : ', so this is better than the season alone would give you.');
}
// Ad spend is only as good as the days that reported. Name the gap rather than compare across it.
function v3WalkGaps(X) {
  const { P, N } = X, out = [];
  const ran = k => ['cur', 'prev', 'ly'].some(j => P[j] && Number(P[j][k]) > 0);
  [['cur', N.cur], ['prev', N.prev], ['ly', N.ly]].forEach(([k, nm]) => {
    const x = P[k];
    if (!x || !x.has_history) return;
    if (ran('meta_spend') && x.meta_days < x.days) out.push('Meta has figures for ' + x.meta_days + ' of ' + x.days + ' days in ' + nm);
    if (ran('google_spend') && x.google_days < x.days) out.push('Google Ads has figures for ' + x.google_days + ' of ' + x.days + ' days in ' + nm);
  });
  return out.length ? out.join('; ') + '. If ads ran on the missing days, spend there reads low and profit after ads high.' : null;
}
// A scoreboard row is a platform AND a channel type (Meta prospecting, Meta retargeting…), so the
// platform alone names two rows the same. The scoreboard's own rule, lifted so both say the same.
function v3ChanName(p, c) {
  return V3_CH[String(c || '').toLowerCase()]
    || (String(c || p || '').replace(/_/g, ' ').replace(/^(meta|google|tiktok|facebook)\s*/i, '').trim().replace(/^./, x => x.toUpperCase()) || p);
}
const v3WalkG2 = n => fmtMoney(n, 2);
const v3WalkTitle = t => { const s = String(t || '').trim(); return s ? s.charAt(0).toUpperCase() + s.slice(1) : 'Unnamed product'; };

// ── The stops ──
// Each builds { say: [sentences], tbl?: [rows], list?: {head, rows}, note? } from the context X.
// say[0] is the takeaway: the summary collects it, so it must stand on its own.
const V3_WALK_STEP = {
  sales: { q: 'Are sales growing?', dest: 'profit', build: X => {
    const { P } = X, c = P.cur;
    const say = ['Sales were ' + v3Gbp(c.net_revenue) + ' in ' + X.N.cur + v3WalkVs(X, 'net_revenue') + '.'];
    const s = v3WalkSeason(X, 'net_revenue'); if (s) say.push(s);
    const o = v3WalkChg(c.orders, P.prev.orders), a = v3WalkChg(c.aov, P.prev.aov);
    if (o != null && a != null && (Math.abs(o) >= 0.05 || Math.abs(a) >= 0.05))
      say.push(Math.abs(o) >= Math.abs(a)
        ? 'The change came from the number of orders (' + v3WalkMove(o) + '), more than from what each order was worth (' + v3WalkMove(a) + ').'
        : 'The change came from what each order was worth (' + v3WalkMove(a) + '), more than from the number of orders (' + v3WalkMove(o) + ').');
    return { say, tbl: [['Sales', 'net_revenue', v3Gbp, 'up'], ['Orders', 'orders', fmtCount, 'up'], ['Average order', 'aov', v3Gbp, 'up']] };
  } },
  profit: { q: 'Is the business making money after ads?', dest: 'profit', build: X => {
    const { P } = X, c = P.cur;
    if (c.cm_after_marketing == null) return { say: ['Greta needs to know what your products cost before she can show profit for past periods.'],
      fix: ['goal', 'costs', 'Enter your product costs'] };
    const say = ['Profit after ads was ' + v3Gbp(c.cm_after_marketing) + ' in ' + X.N.cur + v3WalkVs(X, 'cm_after_marketing') + '.'];
    const sp = v3WalkChg(c.paid_spend, P.prev.paid_spend), sa = v3WalkChg(c.net_revenue, P.prev.net_revenue);
    if (sp != null && sa != null) {
      say.push('Ad spend went ' + v3WalkMove(sp) + ' while sales went ' + v3WalkMove(sa) + '.');
      if (sp - sa > 0.1) say.push('Spend grew faster than the sales it brought in — that gap is what came off profit.');
      else if (sa - sp > 0.1) say.push('Sales outgrew spend, which is the shape you want.');
    }
    const gaps = v3WalkGaps(X);
    return { say, tbl: [['Profit after ads', 'cm_after_marketing', v3Gbp, 'up'], ['Ad spend', 'paid_spend', v3Gbp, null],
                        ['Sales per £1 of ads', 'sales_per_ad_pound', v3WalkG2, 'up']],
      note: 'Every period is costed at today’s margin, so the year-ago profit is a close estimate rather than a count.' + (gaps ? ' ' + gaps : '') };
  } },
  customers: { q: 'Are you winning new customers and keeping old ones?', dest: 'customers', build: X => {
    const { P } = X, c = P.cur;
    const say = [fmtCount(c.new_orders) + ' new customers ordered in ' + X.N.cur + v3WalkVs(X, 'new_orders') + '.'];
    const s = v3WalkSeason(X, 'new_orders'); if (s) say.push(s);
    const tot = Number(c.new_revenue) + Number(c.returning_revenue);
    if (tot > 0) say.push('Customers who had bought before brought in ' + v3Gbp(c.returning_revenue) + ' — ' + fmtPctN(c.returning_revenue / tot) + ' of sales' + v3WalkVs(X, 'returning_revenue') + '.');
    return { say, tbl: [['New customers', 'new_orders', fmtCount, 'up'], ['Repeat orders', 'returning_orders', fmtCount, 'up'],
                        ['Sales from repeat customers', 'returning_revenue', v3Gbp, 'up']] };
  } },
  efficiency: { q: 'Is ad money working as hard as it did?', dest: 'marketing', cat: 'paid', build: X => {
    const { P } = X, c = P.cur;
    if (!(Number(c.paid_spend) > 0)) return { say: ['No ad spend was recorded in ' + X.N.cur + ', so there is nothing to measure here.'] };
    const say = ['Each £1 of ads came back as ' + v3WalkG2(c.sales_per_ad_pound) + ' of sales in ' + X.N.cur
      + ', against ' + v3WalkG2(P.prev.sales_per_ad_pound) + ' in ' + X.N.prev
      + (P.ly.has_history && P.ly.sales_per_ad_pound != null ? ' and ' + v3WalkG2(P.ly.sales_per_ad_pound) + ' in ' + X.N.ly : '') + '.'];
    if (c.cost_per_new_customer != null) say.push('Spread over new customers, ads cost about ' + v3Gbp(c.cost_per_new_customer) + ' for each one' + v3WalkVs(X, 'cost_per_new_customer') + '.');
    const sc = X.score;
    if (sc && sc.length) {
      const under = sc.filter(r => r.avg_iroas != null && r.break_even_iroas != null && Number(r.avg_iroas) < Number(r.break_even_iroas));
      say.push(under.length
        ? 'Over the last 30 days, ' + under.length + ' of ' + sc.length + ' ad channels returned less than they need to break even: ' + under.map(r => v3ChanName(r.platform, r.channel_type)).join(', ') + '.'
        : 'Over the last 30 days, every ad channel returned at least what it needs to break even.');
    }
    return { say, tbl: [['Sales per £1 of ads', 'sales_per_ad_pound', v3WalkG2, 'up'], ['Cost per new customer', 'cost_per_new_customer', v3Gbp, 'down'],
                        ['Ad spend', 'paid_spend', v3Gbp, null]], note: v3WalkGaps(X) };
  } },
  spend: { q: 'What did the ad spend buy?', dest: 'marketing', cat: 'paid', build: X => {
    const { P } = X, c = P.cur;
    if (!(Number(c.paid_spend) > 0)) return { say: ['No ad spend was recorded in ' + X.N.cur + '.'] };
    const parts = [['Meta', c.meta_spend], ['Google', c.google_spend], ['TikTok', c.tiktok_spend]].filter(x => Number(x[1]) > 0);
    const say = ['You spent ' + v3Gbp(c.paid_spend) + ' on ads in ' + X.N.cur + v3WalkVs(X, 'paid_spend') + '.'];
    if (parts.length > 1) say.push(parts[0][0] + ' took ' + v3Gbp(parts[0][1]) + ' of it, ' + parts.slice(1).map(x => x[0] + ' ' + v3Gbp(x[1])).join(' and ') + '.');
    say.push('It came back as ' + v3WalkG2(c.sales_per_ad_pound) + ' of sales per £1' + v3WalkVs(X, 'sales_per_ad_pound')
      + (c.cost_per_new_customer != null ? ', at about ' + v3Gbp(c.cost_per_new_customer) + ' per new customer.' : '.'));
    return { say, tbl: [['Ad spend', 'paid_spend', v3Gbp, null], ['Meta', 'meta_spend', v3Gbp, null], ['Google', 'google_spend', v3Gbp, null],
                        ['Sales per £1 of ads', 'sales_per_ad_pound', v3WalkG2, 'up'], ['Cost per new customer', 'cost_per_new_customer', v3Gbp, 'down']],
      note: v3WalkGaps(X) };
  } },
  channels: { q: 'Which channels pay their way?', dest: 'marketing', cat: 'paid', build: X => {
    const sc = X.score;
    if (!sc) return { loading: true };
    if (!sc.length) return { say: ['Greta has no ad channel with spend in the last 30 days to score.'] };
    const under = sc.filter(r => r.avg_iroas != null && r.break_even_iroas != null && Number(r.avg_iroas) < Number(r.break_even_iroas));
    const say = [under.length
      ? under.length + ' of your ' + sc.length + ' ad channels are returning less than they need to break even — ' + under.map(r => v3ChanName(r.platform, r.channel_type)).join(', ') + '.'
      : 'All ' + sc.length + ' of your ad channels are returning at least what they need to break even.'];
    return { say, list: { head: ['Channel', 'Returns', 'Needs', 'Spend'], rows: sc.map(r => [v3ChanName(r.platform, r.channel_type),
      r.avg_iroas != null ? Number(r.avg_iroas).toFixed(2) + '×' : '—', r.break_even_iroas != null ? Number(r.break_even_iroas).toFixed(2) + '×' : '—',
      v3Gbp(r.spend_30d), r.avg_iroas != null && r.break_even_iroas != null ? (Number(r.avg_iroas) < Number(r.break_even_iroas) ? 'bad' : 'good') : null]) },
      note: 'Last 30 days, whatever the horizon: channel returns need a month of spend to read.' };
  } },
  stock: { q: 'Will anything run out?', dest: 'stock', build: X => {
    const rows = X.stock;
    if (!rows) return { loading: true };
    if (!rows.length) return { say: ['Greta has no stock levels for your products yet.'], fix: ['settings', null, 'Check your connections'] };
    const risk = rows.filter(r => Number(r.cm_at_risk_before_resupply) > 0)
      .sort((a, b) => Number(b.cm_at_risk_before_resupply) - Number(a.cm_at_risk_before_resupply));
    const at = risk.reduce((s, r) => s + Number(r.cm_at_risk_before_resupply), 0);
    const say = [risk.length
      ? risk.length + (risk.length === 1 ? ' product runs' : ' products run') + ' out before a restock could arrive, putting about ' + v3Gbp(at) + ' of profit at risk.'
      : 'Nothing is set to run out before a restock could arrive.'];
    return { say, list: risk.length ? { head: ['Product', 'Runs out', 'At risk'], rows: risk.slice(0, 5).map(r => [v3WalkTitle(r.product_title),
      r.projected_days_to_stockout != null ? (Number(r.projected_days_to_stockout) <= 0 ? 'Out now' : 'in ' + Math.round(r.projected_days_to_stockout) + ' days') : '—',
      v3Gbp(r.cm_at_risk_before_resupply), 'bad']) } : null,
      note: 'Stock is today’s reading, whatever the horizon.' };
  } },
  reorder: { q: 'What needs ordering?', dest: 'stock', build: X => {
    const rows = X.stock;
    if (!rows) return { loading: true };
    const lim = v3IsoAdd(new Date().toISOString().slice(0, 10), 14);
    const due = rows.filter(r => r.reorder_by_date && r.reorder_by_date <= lim && Number(r.suggested_order_units) > 0)
      .sort((a, b) => String(a.reorder_by_date).localeCompare(String(b.reorder_by_date)));
    const say = [due.length
      ? due.length + (due.length === 1 ? ' product needs' : ' products need') + ' ordering in the next two weeks to land before they run out.'
      : 'Nothing needs ordering in the next two weeks.'];
    return { say, list: due.length ? { head: ['Product', 'Order by', 'Units'], rows: due.slice(0, 6).map(r => [v3WalkTitle(r.product_title),
      v3Day(r.reorder_by_date), fmtCount(r.suggested_order_units), r.reorder_by_date < new Date().toISOString().slice(0, 10) ? 'bad' : null]) } : null };
  } },
  cash: { q: 'Is cash stuck on the shelf?', dest: 'stock', build: X => {
    const rows = X.stock;
    if (!rows) return { loading: true };
    const slow = rows.filter(r => Number(r.trapped_cash) > 0).sort((a, b) => Number(b.trapped_cash) - Number(a.trapped_cash));
    const tot = slow.reduce((s, r) => s + Number(r.trapped_cash), 0);
    const say = [slow.length
      ? 'About ' + v3Gbp(tot) + ' of cash is sitting in stock that will not sell through soon, across ' + slow.length + ' products.'
      : 'No cash is tied up in slow stock.'];
    if (slow.length) say.push('The top five hold ' + v3Gbp(slow.slice(0, 5).reduce((s, r) => s + Number(r.trapped_cash), 0)) + ' of it — a bundle, a feature or a gentle markdown frees it faster than waiting.');
    return { say, list: slow.length ? { head: ['Product', 'Weeks of cover', 'Cash held'], rows: slow.slice(0, 5).map(r => [v3WalkTitle(r.product_title),
      r.weeks_of_cover != null ? fmtCount(r.weeks_of_cover) : '—', v3Gbp(r.trapped_cash), null]) } : null };
  } },
  leaks: { q: 'Are discounts and refunds eating sales?', dest: 'products', anchor: 'promos', build: X => {
    const { P } = X, c = P.cur;
    const say = [];
    if (c.discount_rate != null) say.push('Discounts took ' + fmtPctN(c.discount_rate) + ' off full-price sales in ' + X.N.cur
      + ', against ' + fmtPctN(P.prev.discount_rate) + ' in ' + X.N.prev + (P.ly.has_history ? ' and ' + fmtPctN(P.ly.discount_rate) + ' in ' + X.N.ly : '') + '.');
    if (c.return_rate != null) say.push('Refunds came to ' + fmtPctN(c.return_rate) + ' of sales, against ' + fmtPctN(P.prev.return_rate) + ' in ' + X.N.prev + '.');
    if (!say.length) say.push('There were no sales in ' + X.N.cur + ' to measure discounts or refunds against.');
    return { say, tbl: [['Discounts', 'discount_rate', fmtPctN, 'down', true], ['Refunds', 'return_rate', fmtPctN, 'down', true]],
      note: 'Discounts are as Shopify records them, so customer-service adjustments count too.' };
  } },
  topProducts: { q: 'Which products carry the business?', dest: 'products', cat: 'product', build: X => {
    const pr = (X.prods || []).filter(p => Number(p.cur_rev) > 0).sort((a, b) => Number(b.cur_rev) - Number(a.cur_rev)).slice(0, 5);
    if (!pr.length) return { say: ['No product sales were recorded in ' + X.N.cur + '.'] };
    const top = pr.reduce((s, p) => s + Number(p.cur_rev), 0), all = Number(X.P.cur.net_revenue) || 0;
    const lead = pr[0], lm = v3WalkMove(v3WalkChg(lead.cur_rev, lead.prev_rev));
    const say = ['Your five best sellers made ' + v3Gbp(top) + ' in ' + X.N.cur + (all > 0 ? ' — about ' + fmtPctN(Math.min(top / all, 1)) + ' of sales' : '') + '.',
      v3WalkTitle(lead.title) + ' led with ' + v3Gbp(lead.cur_rev) + (lm ? ', ' + lm + ' on ' + X.N.prev : '') + '.'];
    return { say, ptbl: pr };
  } },
  movers: { q: 'What is rising, and what is slipping?', dest: 'products', cat: 'product', build: X => {
    const pr = (X.prods || []).map(p => ({ ...p, d: Number(p.cur_rev) - Number(p.prev_rev) }));
    const up = pr.filter(p => p.d > 0).sort((a, b) => b.d - a.d).slice(0, 3), dn = pr.filter(p => p.d < 0).sort((a, b) => a.d - b.d).slice(0, 3);
    if (!up.length && !dn.length) return { say: ['Nothing moved much between ' + X.N.prev + ' and ' + X.N.cur + '.'] };
    const say = [];
    if (dn.length) say.push('The biggest fall was ' + v3WalkTitle(dn[0].title) + ', ' + v3Gbp(Math.abs(dn[0].d)) + ' less than ' + X.N.prev + '.');
    if (up.length) say.push('The biggest gain was ' + v3WalkTitle(up[0].title) + ', ' + v3Gbp(up[0].d) + ' more.');
    say.push('Check the fallers against stock first: a product that ran out looks exactly like one that stopped selling.');
    return { say, list: { head: ['Product', 'Change', 'Now'], rows: dn.concat(up).map(p => [v3WalkTitle(p.title),
      (p.d > 0 ? '+' : '') + v3Gbp(p.d), v3Gbp(p.cur_rev), p.d < 0 ? 'bad' : 'good']) },
      note: 'Among your 20 best-selling products across the two periods.' };
  } },
  traffic: { q: 'Is the website turning visitors into buyers?', dest: 'website', cat: 'site', build: X => {
    const { P } = X, c = P.cur;
    if (!c.ga_ok || !P.prev.ga_ok) return { say: ['Your website tracking (GA4) was broken during part of this window, so Greta will not compare visits or conversion across it.',
      'Try the other horizons: a window clear of the break compares cleanly.'], held: true };
    const say = [fmtCount(c.sessions) + ' visits in ' + X.N.cur + v3WalkVs(X, 'sessions') + '.'];
    if (c.cvr != null) say.push(fmtPctN(c.cvr) + ' of visits ended in an order' + (P.prev.cvr != null ? ', against ' + fmtPctN(P.prev.cvr) + ' in ' + X.N.prev : '') + '.');
    return { say, tbl: [['Visits', 'sessions', fmtCount, 'up'], ['Conversion', 'cvr', fmtPctN, 'up', true]] };
  } },
  retention: { q: 'Do customers come back?', dest: 'customers', build: X => {
    const r = X.ret;
    if (!r) return { loading: true };
    if (r.repeat_rate == null) return { say: ['Greta does not have enough order history to measure repeat buying yet.'] };
    const say = [fmtPctN(r.repeat_rate) + ' of your ' + fmtCount(r.customers) + ' customers have ordered more than once.'];
    if (r.median_days_between_orders != null) say.push('The typical gap before a second order is ' + fmtCount(r.median_days_between_orders) + ' days — the window for a nudge.');
    if (r.repeat_rate_90d != null) say.push(fmtPctN(r.repeat_rate_90d) + ' come back within 90 days.');
    return { say, note: 'Across every customer you have had, not just ' + X.N.cur + ': repeat buying takes months to show.' };
  } },
  newProducts: { q: 'What is new, and is it selling?', dest: 'products', cat: 'product', build: X => {
    const pr = (X.prods || []).filter(p => Number(p.cur_rev) > 0 && Number(p.ly_rev) === 0).sort((a, b) => Number(b.cur_rev) - Number(a.cur_rev));
    if (!X.P.ly.has_history) return { say: ['Greta needs a year of sales to tell new products from old ones.'] };
    if (!pr.length) return { say: ['None of your best sellers in ' + X.N.cur + ' is new since ' + X.N.ly + '.'] };
    const tot = pr.reduce((s, p) => s + Number(p.cur_rev), 0), all = Number(X.P.cur.net_revenue) || 0;
    const say = [pr.length + ' of your best sellers in ' + X.N.cur + ' did not sell at all in ' + X.N.ly + ' — together ' + v3Gbp(tot)
      + (all > 0 ? ', ' + fmtPctN(Math.min(tot / all, 1)) + ' of sales' : '') + '.'];
    const slip = pr.filter(p => v3WalkChg(p.cur_rev, p.prev_rev) != null && v3WalkChg(p.cur_rev, p.prev_rev) < -0.2);
    if (slip.length) say.push(slip.length + ' of them sold less than in ' + X.N.prev + ' — early fade, or stock running thin.');
    return { say, ptbl: pr.slice(0, 6) };
  } },
  adFit: { q: 'Which products can carry ad spend?', dest: 'products', cat: 'product', build: X => {
    const rows = X.npd;
    if (!rows) return { loading: true };
    const by = k => rows.filter(r => r.paid === k);
    const yes = by('yes'), test = by('test_with_holdout'), no = by('no');
    if (!yes.length && !test.length && !no.length) return { say: ['Greta has not yet checked which products can pay back an ad on their own.'] };
    const say = ['Greta checked which products can pay back an ad on their own first order: ' + yes.length + ' can, '
      + test.length + (test.length === 1 ? ' is' : ' are') + ' worth a test with a holdout, and ' + no.length + ' cannot.',
      'The ones that cannot still earn — as add-ons to a basket or as repeat buys — so sell them to customers you already have, not to cold audiences.'];
    return { say, list: { head: ['Product', 'Ads', 'Sales'], rows: yes.slice(0, 3).map(r => [v3WalkTitle(r.title), 'Can carry ads', v3Gbp(r.revenue), 'good'])
      .concat(no.slice(0, 3).map(r => [v3WalkTitle(r.title), 'Not on ads', v3Gbp(r.revenue), 'bad'])) } };
  } },
};
const V3_WALK_END = { q: 'What to do now', dest: 'actions' };

function V3WalkTable({ X, rows }) {
  const { P, N } = X;
  const cell = (r, k) => {
    const [, key, fmt, better, isRate] = r;
    if (!P[k] || !P[k].has_history) return <td className="v3-walk-d">—</td>;
    const c = P.cur[key], o = P[k][key];
    if (c == null || o == null) return <td className="v3-walk-d">—</td>;
    const d = isRate ? (Number(c) - Number(o)) : v3WalkChg(c, o);
    const txt = d == null ? '—' : isRate
      ? (Math.abs(d) < 0.0005 ? 'same' : (d > 0 ? '+' : '−') + (Math.abs(d) * 100).toFixed(1) + ' pts')
      : (Math.abs(d) < 0.02 ? 'flat' : (d > 0 ? '+' : '−') + fmtPctN(Math.abs(d)));
    const tone = d == null || !better || Math.abs(d) < (isRate ? 0.0005 : 0.02) ? '' : ((d > 0) === (better === 'up') ? ' good' : ' bad');
    return <td className="v3-walk-d"><span className={'v3-walk-chg' + tone}>{txt}</span><span className="v3-walk-was">{fmt(o)}</span></td>;
  };
  return (<table className="v3-walk-tbl">
    <thead><tr><th scope="col"/><th scope="col">{N.col[0]}</th><th scope="col">vs {N.col[1]}</th><th scope="col">vs {N.col[2]}</th></tr></thead>
    <tbody>{rows.map(r => (<tr key={r[1]}>
      <th scope="row">{r[0]}</th>
      <td className="v3-walk-v">{r[2](P.cur[r[1]])}</td>
      {cell(r, 'prev')}{cell(r, 'ly')}
    </tr>))}</tbody>
  </table>);
}
function V3WalkProducts({ X, rows }) {
  const { N } = X;
  const chg = (c, o, has) => {
    if (!has) return <td className="v3-walk-d">—</td>;
    const d = v3WalkChg(c, o);
    const txt = Number(o) === 0 ? (Number(c) > 0 ? 'new' : '—') : (Math.abs(d) < 0.02 ? 'flat' : (d > 0 ? '+' : '−') + fmtPctN(Math.abs(d)));
    const tone = Number(o) === 0 || Math.abs(d) < 0.02 ? '' : (d > 0 ? ' good' : ' bad');
    return <td className="v3-walk-d"><span className={'v3-walk-chg' + tone}>{txt}</span><span className="v3-walk-was">{v3Gbp(o)}</span></td>;
  };
  return (<table className="v3-walk-tbl">
    <thead><tr><th scope="col">Product</th><th scope="col">{N.col[0]}</th><th scope="col">vs {N.col[1]}</th><th scope="col">vs {N.col[2]}</th></tr></thead>
    <tbody>{rows.map(p => (<tr key={p.title}>
      <th scope="row">{v3WalkTitle(p.title)}</th>
      <td className="v3-walk-v">{v3Gbp(p.cur_rev)}</td>
      {chg(p.cur_rev, p.prev_rev, X.P.prev.has_history)}{chg(p.cur_rev, p.ly_rev, X.P.ly.has_history)}
    </tr>))}</tbody>
  </table>);
}
function V3WalkList({ list }) {
  return (<table className="v3-walk-tbl v3-walk-list">
    <thead><tr>{list.head.map((h, i) => <th key={i} scope="col">{h}</th>)}</tr></thead>
    <tbody>{list.rows.map((r, i) => {
      const tone = r[list.head.length];
      return (<tr key={i}>
        <th scope="row">{r[0]}</th>
        {r.slice(1, list.head.length).map((v, j) => <td key={j} className={'v3-walk-v' + (j === list.head.length - 2 && tone ? ' v3-walk-' + tone : '')}>{v}</td>)}
      </tr>);
    })}</tbody>
  </table>);
}
function V3WalkActs({ rows, head }) {
  if (!rows.length) return null;
  return (<div className="v3-walk-acts">
    <div className="v3-kick">{head}</div>
    {rows.map((a, i) => (<div key={a.external_id || i} className="v3-walk-act">
      <span className="v3-num">{i + 1}</span>
      <span>{v3PlainAction(a).title}</span>
      <span className="v3-num">{a.cm_gbp ? v3Gbp(a.cm_gbp) + v3Per(a, true) : ''}</span>
    </div>))}
  </div>);
}

// ── What it means for the business ──────────────────────────────────────────
// The D2C anatomy, applied to the chosen periods (docs/framework/d2c-metric-relationships.md,
// anatomy.html): sales = orders × order value (= visits × conversion × order value when GA4 is
// clean); profit after ads = sales × margin − ad spend, so its share of sales = margin − 1/MER and
// ads pay for themselves above 1/margin of sales per £1; a new customer pays back when the first
// order's profit covers what it cost to win; lifetime profit against that cost is the scale test.
// Every figure is one the server already counted (0230, vw_brand_unit_economics) — this only works
// out which of them moved and says what that is worth in pounds.
// One decimal formatter for the walkthrough's sentences (the house rule: no bare toFixed).
const v3WalkDp = (v, d) => Number(v).toLocaleString('en-GB', { minimumFractionDigits: d, maximumFractionDigits: d });
const v3WalkPct = v => (v == null || !isFinite(v)) ? '—' : fmtPctN(v);
const v3WalkX = v => (v == null || !isFinite(v)) ? '—' : v3WalkDp(v, 2) + '×';
const v3WalkSigned = v => (v >= 0 ? '+' : '−') + v3Gbp(Math.abs(v));
function v3WalkBreakEven(X) { return X.cm > 0 ? 1 / X.cm : null; }
// Visits × conversion × order value, when both periods' GA4 can be trusted (ChangeBridge's
// split, on Shopify orders ÷ GA4 sessions — the canonical site conversion).
function v3WalkBridge(X) {
  const c = X.P.cur, p = X.P.prev;
  if (!c.ga_ok || !p.ga_ok || !(c.sessions > 0) || !(p.sessions > 0) || !(c.orders > 0) || !(p.orders > 0)) return null;
  const S0 = Number(p.sessions), S1 = Number(c.sessions), C0 = p.orders / S0, C1 = c.orders / S1, A0 = Number(p.aov), A1 = Number(c.aov);
  return [['visits', (S1 - S0) * C0 * A0], ['conversion', S1 * (C1 - C0) * A0], ['order value', S1 * C1 * (A1 - A0)]];
}
function v3WalkMeansSales(X) {
  const c = X.P.cur, p = X.P.prev, out = [];
  if (!p.has_history) return out;
  const d = c.net_revenue - p.net_revenue;
  if (X.cm > 0 && Math.abs(d) > 0) out.push('Your products keep about ' + Math.round(X.cm * 100) + 'p of every £1 of sales after product and order costs, so the '
    + v3Gbp(Math.abs(d)) + (d < 0 ? ' drop' : ' rise') + ' in sales is about ' + v3Gbp(Math.abs(d * X.cm)) + ' of profit before ads ' + (d < 0 ? 'lost.' : 'gained.'));
  const br = v3WalkBridge(X);
  if (br) {
    const top = br.slice().sort((a, b) => Math.abs(b[1]) - Math.abs(a[1]))[0];
    out.push('Split by where it came from: ' + br.map(x => x[0] + ' ' + v3WalkSigned(x[1])).join(', ') + '. The biggest part was ' + top[0] + '.');
  } else if (!c.ga_ok || !p.ga_ok) {
    out.push('Greta cannot split this into visits and conversion for these periods — website tracking (GA4) was broken in part of them — so the orders and order value split is the one to trust.');
  }
  return out;
}
function v3WalkMeansProfit(X) {
  const c = X.P.cur, p = X.P.prev, out = [], be = v3WalkBreakEven(X);
  if (!(c.net_revenue > 0) || X.cm == null) return out;
  const adShare = c.paid_spend / c.net_revenue, keep = c.cm_after_marketing / c.net_revenue;
  out.push('Out of every £1 of sales in ' + X.N.cur + ', your products kept ' + Math.round(X.cm * 100) + 'p, ads took ' + Math.round(adShare * 100)
    + 'p, and the business kept ' + Math.round(keep * 100) + 'p — ' + v3Gbp(c.cm_after_marketing) + '.');
  if (be && c.sales_per_ad_pound != null) out.push('Taking all sales against all ad spend, the business covers its ads while each £1 of ads is matched by at least £' + v3WalkDp(be, 2) + ' of sales. In ' + X.N.cur + ' it was £'
    + v3WalkDp(c.sales_per_ad_pound, 2) + (c.sales_per_ad_pound >= be
      ? ' — covered, but that includes repeat and organic sales, so it does not show that every channel earns its spend.'
      : ' — not covered: ad spend is costing more than all the sales it sits against.'));
  if (p.has_history && p.cm_after_marketing != null) {
    const vol = X.cm * (c.net_revenue - p.net_revenue), sp = -(c.paid_spend - p.paid_spend), tot = c.cm_after_marketing - p.cm_after_marketing;
    out.push('Against ' + X.N.prev + ', profit after ads moved ' + v3WalkSigned(tot) + ': ' + v3WalkSigned(vol) + ' from sales and ' + v3WalkSigned(sp) + ' from ad spend.');
  }
  return out;
}
function v3WalkMeansCustomers(X) {
  const c = X.P.cur, out = [], ue = X.ue;
  if (c.new_orders > 0 && c.cost_per_new_customer != null && X.cm > 0) {
    const foc = (c.new_revenue / c.new_orders) * X.cm, cac = Number(c.cost_per_new_customer);
    out.push('Winning a new customer cost about ' + v3Gbp(cac) + ' of ad spend in ' + X.N.cur + ' (all ad spend over new customers). Their first order brings about '
      + v3Gbp(foc) + ' of profit before ads, so ' + (foc >= cac ? 'they pay for themselves on the first order.' : 'it takes about ' + v3WalkDp(cac / foc, 1) + ' orders to earn back what they cost.'));
  }
  if (ue && ue.ltv_contribution != null && ue.ltv_cac != null) out.push('Over ' + (ue.ltv_horizon_months || 12) + ' months the average customer earns you about ' + v3Gbp(ue.ltv_contribution)
    + ' of profit — ' + v3WalkDp(ue.ltv_cac, 1) + '× what one costs to win today. ' + (ue.ltv_cac >= 3 ? 'That is healthy room to spend on growth.' : ue.ltv_cac >= 2 ? 'Workable, but there is little room to pay more for customers.' : 'That is thin: growth bought on ads barely pays back.'));
  return out;
}
function v3WalkMeansEfficiency(X) {
  const c = X.P.cur, p = X.P.prev, out = [], be = v3WalkBreakEven(X);
  if (be && c.sales_per_ad_pound != null) out.push('At your margin the business needs £' + v3WalkDp(be, 2) + ' of sales for every £1 of ads just to cover them; ' + X.N.cur + ' ran at £' + v3WalkDp(c.sales_per_ad_pound, 2)
    + (c.sales_per_ad_pound >= be ? '. That is all sales, repeat and organic included — whether each channel earns its own spend is the scoreboard\u2019s job.' : ', so ads cost more than all the sales they sit against.'));
  if (p.has_history && c.paid_spend > 0 && p.paid_spend > 0) {
    const mc = c.new_revenue / c.paid_spend, mp = p.new_revenue / p.paid_spend;
    const vol = (c.paid_spend - p.paid_spend) * mp, eff = c.paid_spend * (mc - mp);
    out.push('New-customer sales moved ' + v3WalkSigned(c.new_revenue - p.new_revenue) + ': ' + v3WalkSigned(vol) + ' from spending ' + (c.paid_spend >= p.paid_spend ? 'more' : 'less')
      + ', and ' + v3WalkSigned(eff) + ' because each £1 worked ' + (mc >= mp ? 'harder.' : 'less hard.') + (vol > 0 && eff < 0 && Math.abs(eff) > vol * 0.5 ? ' Most of the extra spend was soaked up rather than turned into customers.' : ''));
  }
  return out;
}
function v3WalkMeansStock(X) {
  const rows = X.stock || [], c = X.P.cur, out = [];
  const risk = rows.reduce((s, r) => s + (Number(r.cm_at_risk_before_resupply) || 0), 0);
  const perDay = rows.filter(r => Number(r.cm_at_risk_before_resupply) > 0).reduce((s, r) => s + (Number(r.lost_cm_per_day) || 0), 0);
  if (risk > 0 && c.cm_after_marketing > 0) out.push('The ' + v3Gbp(risk) + ' at risk is about ' + fmtPctN(risk / (c.cm_after_marketing * 30 / c.days)) + ' of a month’s profit after ads at ' + X.N.cur + '’s rate.');
  if (perDay > 0) out.push('While they are out, each day costs about ' + v3Gbp(perDay) + ' of profit — and ad spend pointed at them keeps running.');
  return out;
}
function v3WalkMeansCash(X) {
  const rows = X.stock || [], c = X.P.cur, out = [];
  const tot = rows.reduce((s, r) => s + (Number(r.trapped_cash) || 0), 0);
  if (tot > 0 && c.paid_spend > 0) out.push('That ' + v3Gbp(tot) + ' would fund about ' + Math.round(tot / (c.paid_spend / c.days * 7)) + ' weeks of ad spend at ' + X.N.cur + '’s rate. Cash on the shelf is growth you have already paid for and cannot use.');
  return out;
}
function v3WalkMeansLeaks(X) {
  const c = X.P.cur, p = X.P.prev, out = [];
  if (c.discount_rate == null) return out;
  const gross = c.net_revenue / (1 - c.discount_rate);
  out.push('A discount comes straight off profit. On ' + v3Gbp(gross) + ' of full-price sales in ' + X.N.cur + ', each point of discount is about ' + v3Gbp(gross * 0.01) + '.');
  if (p.has_history && p.discount_rate != null) {
    const d = c.discount_rate - p.discount_rate;
    if (Math.abs(d) >= 0.005) out.push('Against ' + X.N.prev + ' the discount rate moved ' + (d > 0 ? 'up' : 'down') + ' ' + v3WalkDp(Math.abs(d) * 100, 1) + ' points — about ' + v3Gbp(Math.abs(d) * gross)
      + (d > 0 ? ' of profit given away.' : ' of profit kept.'));
  }
  if (c.return_rate != null && c.return_rate > 0) out.push('Refunds took ' + v3Gbp(c.return_rate * c.net_revenue) + ' back out of sales in ' + X.N.cur + '.');
  return out;
}
function v3WalkMeansProducts(X) {
  const pr = (X.prods || []).filter(p => Number(p.cur_rev) > 0).sort((a, b) => Number(b.cur_rev) - Number(a.cur_rev)), all = Number(X.P.cur.net_revenue) || 0, out = [];
  if (pr.length && all > 0) {
    const s1 = pr[0].cur_rev / all;
    out.push(v3WalkTitle(pr[0].title) + ' alone was ' + fmtPctN(Math.min(s1, 1)) + ' of sales in ' + X.N.cur + (s1 > 0.15 ? '. A stock-out or a bad review on it is a business-level risk, not a product one.' : '.'));
  }
  return out;
}
function v3WalkMeansRetention(X) {
  const c = X.P.cur, ue = X.ue, out = [];
  const tot = Number(c.new_revenue) + Number(c.returning_revenue);
  if (tot > 0) out.push('Repeat customers made ' + fmtPctN(c.returning_revenue / tot) + ' of sales in ' + X.N.cur + ' at no ad cost — every point of that is profit that did not have to be bought.');
  if (ue && ue.payback_orders != null) out.push('A new customer pays back after about ' + v3WalkDp(ue.payback_orders, 1) + ' orders (today’s figure)' + (ue.payback_orders <= 2 ? ', so the second order is where the profit starts.' : ' — a slow payback, so retention is where the money is.'));
  return out;
}
function v3WalkMeansAdFit(X) {
  const ue = X.ue, out = [];
  if (ue && ue.cac != null) out.push('To win a customer on an ad, a product’s first order has to bring in at least ' + v3Gbp(ue.cac) + ' of profit — today’s cost of a new customer. Below that, it belongs in baskets and emails, not in cold ads.');
  return out;
}
// The chart each stop draws from the series, and what the panel it lights always shows.
const V3_WALK_VIEW = {
  sales:       { chart: ['net_revenue', v3Gbp, 'Sales'], means: v3WalkMeansSales },
  profit:      { chart: ['cm_after_marketing', v3Gbp, 'Profit after ads'], means: v3WalkMeansProfit },
  customers:   { chart: ['new_orders', fmtCount, 'New customers'], means: v3WalkMeansCustomers },
  efficiency:  { chart: ['sales_per_ad_pound', n => fmtMoney(n, 2), 'Sales per £1 of ads'], means: v3WalkMeansEfficiency, why: true },
  spend:       { chart: ['paid_spend', v3Gbp, 'Ad spend'], means: v3WalkMeansEfficiency },
  channels:    { chart: ['sales_per_ad_pound', n => fmtMoney(n, 2), 'Sales per £1 of ads'], means: null, why: true },
  creative:    { chart: ['paid_spend', v3Gbp, 'Ad spend'], means: null },
  stock:       { chart: null, means: v3WalkMeansStock },
  reorder:     { chart: null, means: v3WalkMeansStock },
  cash:        { chart: null, means: v3WalkMeansCash },
  leaks:       { chart: ['discount_rate', v3WalkPct, 'Discount rate'], means: v3WalkMeansLeaks },
  topProducts: { chart: ['net_revenue', v3Gbp, 'Sales'], means: v3WalkMeansProducts },
  movers:      { chart: ['net_revenue', v3Gbp, 'Sales'], means: v3WalkMeansProducts },
  traffic:     { chart: ['sessions', fmtCount, 'Visits'], means: v3WalkMeansSales },
  retention:   { chart: ['returning_revenue', v3Gbp, 'Sales from repeat customers'], means: v3WalkMeansRetention },
  newProducts: { chart: ['net_revenue', v3Gbp, 'Sales'], means: v3WalkMeansProducts },
  adFit:       { chart: null, means: v3WalkMeansAdFit },
};
// What the lit panel always shows, whatever the horizon — so the pop-out never pretends a fixed
// 30-day panel has changed when the owner switches to a year.
const V3_WALK_PANEL = {
  profit: 'the last 30 days', sales: 'the last 30 days', spend: 'the last 30 days', customers: 'week by week',
  efficiency: 'the last 30 days', channels: 'the last 30 days', creative: 'recent weeks', stock: 'today', reorder: 'today',
  cash: 'today', topProducts: 'the last 28 days', movers: 'the last 28 days', newProducts: 'the last 28 days', adFit: 'the last 28 days',
  traffic: 'this month against a normal month', retention: 'every customer since their first order',
};
function v3WalkGrain(h) { return h === 'week' ? 'week' : h === 'quarter' ? 'quarter' : h === 'year' ? '12 months' : 'month'; }
function v3WalkBucket(h, b) {
  if (!b) return '';
  const mo = iso => V3_MON[Number(String(iso).slice(5, 7)) - 1], yy = iso => '’' + String(iso).slice(2, 4);
  if (h === 'week') return v3Day(b.start);
  if (h === 'quarter') return 'Q' + (Math.floor((Number(String(b.start).slice(5, 7)) - 1) / 3) + 1) + ' ' + yy(b.start);
  if (h === 'year') return mo(b.start) + ' ' + yy(b.start) + '–' + mo(b.end) + ' ' + yy(b.end);
  return mo(b.start) + ' ' + yy(b.start);
}
// The pop-out's own picture, drawn from the run of periods at the chosen grain: the current
// period in the accent colour, the same period last year marked, gaps where data is missing or
// untrustworthy. It redraws when the owner switches horizon, which a fixed 30-day panel cannot.
function V3WalkChart({ X, metric }) {
  const [key, fmt, label] = metric;
  const S = X.series || [];
  if (S.length < 2) return null;
  const ok = b => b && b.has_history && !(key === 'sessions' && !b.ga_ok);
  const vals = S.map(b => (ok(b) && b[key] != null && isFinite(Number(b[key]))) ? Number(b[key]) : null);
  const hi = Math.max(0, ...vals.filter(v => v != null)), lo = Math.min(0, ...vals.filter(v => v != null));
  if (hi === lo) return null;
  const W = 300, H = 64, gap = S.length > 9 ? 2 : 6, bw = (W - gap * (S.length - 1)) / S.length;
  const y0 = H * hi / (hi - lo), sc = H / (hi - lo);
  const last = S.length - 1, lyIdx = X.P.ly ? S.findIndex(b => b && b.start === X.P.ly.start) : -1;
  return (<figure className="v3-walk-chart">
    <svg viewBox={'0 0 ' + W + ' ' + H} preserveAspectRatio="none" role="img"
         aria-label={label + ' by ' + v3WalkGrain(X.h) + ', ' + v3WalkBucket(X.h, S[0]) + ' to ' + v3WalkBucket(X.h, S[last])}>
      <line x1="0" x2={W} y1={y0} y2={y0} stroke={PAL.line} strokeWidth="1"/>
      {vals.map((v, i) => {
        const x = i * (bw + gap);
        if (v == null) return <rect key={i} x={x} y={y0 - 2} width={bw} height="2" fill={PAL.line}/>;
        const h = Math.max(1, Math.abs(v) * sc);
        return <rect key={i} x={x} y={v >= 0 ? y0 - h : y0} width={bw} height={h}
          fill={i === last ? PAL.accent : i === lyIdx ? PAL.data3 : PAL.quiet}><title>{v3WalkBucket(X.h, S[i]) + ': ' + fmt(v)}</title></rect>;
      })}
    </svg>
    <figcaption>
      <span>{v3WalkBucket(X.h, S[0])}</span>
      <span className="v3-walk-chart-t">{label}{X.h === 'year' ? ', 12 months at a time' : ' by ' + v3WalkGrain(X.h)}</span>
      <span>{v3WalkBucket(X.h, S[last])}</span>
    </figcaption>
    <div className="v3-walk-chart-key">
      <span><i className="k-cur"/>{X.N.cur} {fmt(vals[last])}</span>
      {lyIdx >= 0 && vals[lyIdx] != null && <span><i className="k-ly"/>{X.N.ly} {fmt(vals[lyIdx])}</span>}
    </div>
  </figure>);
}

// ── Why a channel is below break-even ──────────────────────────────────────
// fn_channel_diagnosis (0231): the change in a channel's reported return split exactly into
// order value × purchases per click ÷ (cost per 1,000 views ÷ click-through), each in pounds of
// profit, plus the checks that turn "what moved" into "why": did extra spend buy anything, would
// more budget even buy reach, did people searching for the brand by name convert less too (then
// it is the site, not the channel), and how much of the platform's claim Greta counts as real.
const V3_DRIVER = {
  cvr: ['Purchases per click', v => v3WalkPct(v)], ctr: ['Click-through', v => v3WalkPct(v)],
  cpm: ['Cost per 1,000 views', v => fmtMoney(v, 2)], aov: ['Order value', v => v3Gbp(v)],
};
function V3WalkWhy({ X, diag, focus }) {
  if (!diag) return <V3SkeletonRows n={2}/>;
  const chs = diag.channels || {};
  const below = Object.keys(chs).filter(k => {
    const x = chs[k].context; return x && x.avg_iroas != null && x.break_even_iroas != null && Number(x.avg_iroas) < Number(x.break_even_iroas);
  }).sort((a, b) => (Number((chs[b].periods.cur || {}).spend) || 0) - (Number((chs[a].periods.cur || {}).spend) || 0));
  if (!below.length) return <p className="v3-walk-say">No ad channel is below break-even, so there is nothing to diagnose here.</p>;
  const brand = chs.google_brand && chs.google_brand.periods;
  return (<>{below.slice(0, focus ? 1 : 2).map(k => {
    const ch = chs[k], c = ch.periods.cur || {}, p = ch.periods.prev || {}, d = ch.drivers, x = ch.context || {};
    const name = v3ChanName(x.platform, k);
    if (!c.has_detail || !p.has_detail || !d) return (<div key={k} className="v3-why-ch">
      <div className="v3-tour-h">Why {name} is below break-even</div>
      <p className="v3-walk-say">Greta’s campaign-level detail does not cover all of {X.N.prev}, so it cannot split this change yet. Switch to Week or Month to see the drivers.</p>
    </div>);
    const terms = ['cvr', 'ctr', 'cpm', 'aov'].map(t => ({ t, v: Number(d[t]), gbp: Number((d.gbp || {})[t]) || 0 }))
      .sort((a, b) => Math.abs(b.gbp) - Math.abs(a.gbp));
    const mx = Math.max(1, ...terms.map(t => Math.abs(t.gbp)));
    const hurt = terms.filter(t => t.gbp < 0), help = terms.filter(t => t.gbp > 0);
    const fromTo = t => {
      const f = V3_DRIVER[t.t][1], before = p[t.t], after = c[t.t];
      return V3_DRIVER[t.t][0].toLowerCase() + ' ' + (Number(after) > Number(before) ? 'rose' : 'fell') + ' from ' + f(before) + ' to ' + f(after);
    };
    const checks = [];
    const plat = x.platform === 'google' ? 'Google' : 'Meta';
    // 0245: the drivers above come from the platform's own conversion count. When that count moved
    // differently from the orders the shop recorded from the platform, the driver that looks biggest
    // can be the wrong one (frkl, Aug -> Sep: Google showed conversion rate falling; against real
    // orders the change was in impressions per click). Say so first, before reading the drivers.
    const countChanged = x.count_check && x.count_check.state === 'changed' && x.count_check.text;
    if (countChanged) checks.push(x.count_check.text);
    if (d.spend_growth > 0.2 && d.value_growth < 0) checks.push('Spend went up ' + fmtPctN(d.spend_growth) + ' while the sales ' + plat + ' credits fell ' + fmtPctN(-d.value_growth)
      + ': the extra ' + v3Gbp(d.extra_spend) + ' of spend came with ' + v3Gbp(-d.extra_value) + ' less in sales. The extra budget bought pricier, less ready-to-buy clicks.');
    else if (d.spend_growth > 0.2 && d.value_growth < d.spend_growth / 2) checks.push('Spend went up ' + fmtPctN(d.spend_growth) + ' but the sales ' + plat + ' credits went up only ' + fmtPctN(d.value_growth)
      + ': the extra ' + v3Gbp(d.extra_spend) + ' brought in ' + v3Gbp(d.extra_value) + '. The extra budget bought pricier, less ready-to-buy clicks.');
    if (c.lost_to_rank != null && c.lost_to_budget != null) checks.push(c.lost_to_rank > c.lost_to_budget
      ? 'It showed in ' + fmtPctN(c.impression_share) + ' of the auctions it could enter, losing ' + fmtPctN(c.lost_to_rank) + ' to ad rank and only ' + fmtPctN(c.lost_to_budget) + ' to budget — so more money will not buy more reach. Better bids, a sharper product feed and stronger assets would.'
      : 'It lost ' + fmtPctN(c.lost_to_budget) + ' of its auctions to budget — reach is limited by spend, not by ad quality.');
    if (k.indexOf('facebook') === 0 && c.frequency != null && p.frequency != null && c.frequency > p.frequency * 1.15 && d.ctr < 0)
      checks.push('The same people saw the ads ' + v3WalkDp(c.frequency, 1) + ' times on average, up from ' + v3WalkDp(p.frequency, 1) + ', while click-through fell — the creative is wearing out.');
    if (c.atc_rate != null && p.atc_rate != null && c.atc_rate < p.atc_rate * 0.8)
      checks.push('Fewer people who clicked added to basket (' + v3WalkPct(p.atc_rate) + ' → ' + v3WalkPct(c.atc_rate) + ') — the landing page or the offer is not landing.');
    if (k !== 'google_brand' && brand && brand.cur && brand.prev && brand.cur.has_detail && brand.prev.has_detail && brand.cur.cvr != null && brand.prev.cvr != null && brand.cur.cvr < brand.prev.cvr * 0.75)
      checks.push('Even people searching for you by name converted less (' + v3WalkPct(brand.prev.cvr) + ' → ' + v3WalkPct(brand.cur.cvr) + '). They are the most ready-to-buy visitors you have, so part of this is the site, not the channel — check the open site fixes first.');
    if (x.phi != null && x.phi_source !== 'measured') checks.push((Number(x.phi) < 1
        ? 'Greta counts about ' + fmtPctN(x.phi) + ' of the sales ' + plat + ' claims as truly caused by these ads'
        : 'Greta reckons these ads cause about ' + fmtPctN(x.phi - 1) + ' more sales than ' + plat + ' reports, because it misses some (other devices, later orders)')
      + ' — a standard figure for this kind of campaign, not yet measured for you. So it needs about '
      + v3WalkX(x.break_even_reported_roas) + ' in ' + plat + '’s own numbers to break even. A two-week holdout would measure it.');
    if (x.saturation_read === 'still scaling efficiently' && d.spend_growth > 0.2) checks.push('Over the longer run this platform has scaled well for you, so this looks like a recent problem with this campaign rather than a ceiling.');
    return (<div key={k} className="v3-why-ch">
      <div className="v3-tour-h">Why {name} is below break-even</div>
      <p className="v3-walk-say lead">{(x.platform === 'google' ? 'Google' : 'Meta')} reports its return went from {v3WalkX(p.roas_reported)} in {X.N.prev} to {v3WalkX(c.roas_reported)} in {X.N.cur}.
        {hurt.length ? ' The main reason: ' + fromTo(hurt[0]) + ', worth about ' + v3Gbp(Math.abs(hurt[0].gbp)) + ' of profit.' : ''}</p>
      <ul className="v3-why-drivers" aria-label="What moved the return">
        {terms.map(t => (<li key={t.t}>
          <span>{V3_DRIVER[t.t][0]}</span>
          <span className="v3-why-ft">{V3_DRIVER[t.t][1](p[t.t])} → {V3_DRIVER[t.t][1](c[t.t])}</span>
          <span className="v3-why-track"><i className={t.gbp < 0 ? 'neg' : 'pos'} style={{ width: (Math.abs(t.gbp) / mx * 100) + '%' }}/></span>
          <span className={'v3-why-gbp ' + (t.gbp < 0 ? 'neg' : 'pos')}>{v3WalkSigned(t.gbp)}</span>
        </li>))}
      </ul>
      {help.length > 0 && hurt.length > 0 && <p className="v3-note">{help.map(fromTo).join('; ').replace(/^./, s => s.toUpperCase())}, which helped — but not enough to cover the rest.</p>}
      {checks.length > 0 && <ul className="v3-why-checks">{checks.map((s, i) => <li key={i}>{s}</li>)}</ul>}
      <p className="v3-note">{countChanged
        ? 'The drivers are counted by ' + plat + ', and ' + plat + '’s count moved differently from your real orders this time — read them with the first point above in mind.'
        : 'The drivers are counted by ' + plat + '; the reasons are Greta’s reading of them.'}</p>
    </div>);
  })}</>);
}

// ── The tour ─────────────────────────────────────────────────────────────────
// A walkthrough is a guided tour of the app itself, not a report about it. Each stop opens the
// page, finds the real panel that answers the stop's question, scrolls to it, lights it and dims
// the rest, and puts a caption beside it: what the panel is and how to read it, what it says for
// this business over the chosen horizon, and what to do. The menu item for the page is marked too,
// so the owner learns where things live and can come back without the guide.
//
// The spotlight never blocks the page — the panel stays live, so "tap a segment to open it" can be
// tried there and then. Targets are found by a selector plus a phrase from the panel's own title,
// so no page had to change to be toured; if a panel is not on screen for this brand (no data yet),
// the caption says so and the stop still reads.
const V3_WALK_TOUR = {
  profit: { dest: 'today', target: { sel: '.v3-hero' },
    what: 'The big number is your profit after ads over the last 30 days — what the business kept after product costs and ad spend. Tap it to see exactly what went into it; the bar underneath is your pace against your goal.' },
  sales: { dest: 'profit', target: { sel: '.v3-flow' },
    what: 'This bar is every £1 of sales and where it went: product costs, order costs and ads come out, and the last segment is what you keep. Tap any segment to open the page behind it.' },
  customers: { dest: 'customers', target: { sel: 'figure.v3-chart', has: 'New and returning' }, fallback: { sel: '.v3-stat-grid' },
    what: 'Sales split by who placed them, week by week: first-time customers against people who have bought before. A healthy shop grows both; a business living on new customers alone has to keep paying to replace them.' },
  efficiency: { dest: 'marketing', target: { sel: '.v3-score' },
    what: 'Every ad channel on one scale. The bar is what each £1 of spend brings back; the tick is what it needs to bring back to pay for itself at your margins. A bar short of its tick is losing money, whatever the platform reports.' },
  spend: { dest: 'profit', target: { sel: '.v3-flow' },
    what: 'The ads segment of this bar is how many pence of every £1 of sales went on ads over the last 30 days. Tap it to open Marketing, where the spend is split by channel.' },
  channels: { dest: 'marketing', target: { sel: '.v3-score' },
    what: 'Read the tick before the bar: it is the return each channel needs to break even. Rows are ordered by spend, because falling short at £300 is not the same as at £6,000.' },
  creative: { dest: 'marketing', target: { sel: '.card', has: 'Spend sitting on the weaker ads' }, fallback: { sel: '.v3-score' },
    what: 'Ads whose last 28 days have broken down, against their own past or against your other ads, and what that money cost you — and whether moving it to the ads that are holding up would actually help.' },
  stock: { dest: 'stock', target: { sel: '.v3-sec', has: 'What to order, product by product' }, fallback: { sel: '.v3-verdict' },
    what: 'Each row is a product: the solid bar is the days of stock left, the hatched part is days you would have nothing to sell before a new order could land. The longer the hatching, the more it costs you.' },
  reorder: { dest: 'stock', target: { sel: '.v3-sec', has: 'What to order, product by product' }, fallback: { sel: '.v3-verdict' },
    what: 'The same table, read for ordering: the tick on each row is when an order placed today would arrive. Anything whose bar ends before its tick needs ordering now.' },
  cash: { dest: 'stock', target: { sel: '.v3-sec', has: 'Where cash is sitting' }, fallback: { sel: '.v3-stat-grid' },
    what: 'Money tied up in stock that will not sell through soon. It is cash you have already spent and cannot use for ads or new lines until it sells.' },
  leaks: { dest: 'products', target: { sel: '.v3-more', has: 'Promotions and discount codes' },
    what: 'Every discount code, what it was used for and what it cost you, sits behind this heading. Open it to see which codes earn their keep.' },
  topProducts: { dest: 'products', target: { sel: '.v3-ptable' },
    what: 'Your products ranked by sales over the last 28 days. The bar is size, the change column is against the 28 days before, and a "Low stock" tag means sales may be held back by stock rather than demand.' },
  movers: { dest: 'products', target: { sel: '.v3-movers' }, fallback: { sel: '.v3-ptable' },
    what: 'What gained and lost the most in pounds. Before acting on a faller, check it against stock — a product that ran out looks exactly like one that stopped selling.' },
  traffic: { dest: 'website', target: { sel: 'figure.v3-chart' }, fallback: { sel: '.v3-sec', has: 'Each stage against its normal' },
    what: 'Your shop as a funnel — visits, product views, baskets, checkouts, orders — against a normal month. The stage that has slipped furthest is where buyers are being lost.' },
  retention: { dest: 'customers', target: { sel: 'figure.v3-chart', has: 'What a customer spends over time' }, fallback: { sel: '.v3-stat-grid' },
    what: 'How much the average customer has spent with you as the months go by after their first order. The steeper the early climb, the more a new customer is really worth.' },
  newProducts: { dest: 'products', target: { sel: '.v3-ptable' },
    what: 'Your products ranked by sales. A change marked "New" had no sales in the period before — that is where launches show up first.' },
  adFit: { dest: 'products', target: { sel: '.v3-ptable' },
    what: 'Not every product can win a new customer on an ad by itself. Greta checks each one: can its first order pay back what an ad costs, or does it earn its place as an add-on or a repeat buy?' },
};
Object.keys(V3_WALK_TOUR).forEach(k => { if (V3_WALK_STEP[k]) Object.assign(V3_WALK_STEP[k], V3_WALK_TOUR[k]); });
// Stops that read today's state rather than the chosen periods, and stops whose lit panel already
// lists the rows — the caption interprets those panels instead of copying them.
['channels', 'stock', 'reorder', 'cash', 'retention', 'adFit'].forEach(k => { V3_WALK_STEP[k].now = true; });
['channels', 'stock', 'reorder', 'cash'].forEach(k => { V3_WALK_STEP[k].onPage = true; });
V3_WALK_STEP.creative = Object.assign({ q: 'Is money sitting on weak ads?', cat: 'paid', build: X => {
  const rows = v3LiveRows(X.board || []).filter(r => r.category === 'paid' && /creative|never convert|weak/i.test(String(r.external_id) + ' ' + String(r.description)));
  if (!rows.length) return { say: ['Greta has not flagged any ad that is taking budget without earning it.'] };
  const t = rows.reduce((s, r) => s + (Number(r.cm_gbp) || 0), 0);
  return { say: [rows.length + (rows.length === 1 ? ' fix here is' : ' fixes here are') + ' worth about ' + v3Gbp(t) + ' a month: ' + rows.map(r => v3PlainAction(r).title.replace(/\.$/, '')).join('; ') + '.'] };
}, now: true }, V3_WALK_TOUR.creative);
Object.assign(V3_WALK_END, { target: { sel: '.v3-board' }, fallback: { sel: '.v3-main .v3-page-head' },
  what: 'Every action Greta has, biggest pound value first. The chips at the top filter by area; open a row to see the steps, and press Mark done when it is done — Greta then checks whether it worked.' });
V3_WALKS.find(w => w.id === 'business').steps = ['profit', 'sales', 'customers', 'efficiency', 'stock'];
V3_WALKS.find(w => w.id === 'paid').steps = ['spend', 'channels', 'creative', 'profit'];

function v3TourFind(t) {
  if (!t) return null;
  const root = document.querySelector('.v3-main') || document;
  const all = [...root.querySelectorAll(t.sel)];
  const hit = t.has ? all.find(e => (e.textContent || '').indexOf(t.has) >= 0) : all[0];
  return hit && hit.getBoundingClientRect().height > 0 ? hit : null;
}
// The menu item for the page being toured, so the owner sees where it lives.
function v3TourNav(dest) {
  const lab = V3_BY_ID[dest] && V3_BY_ID[dest].label;
  document.querySelectorAll('.v3-nav-item.v3-tour-here').forEach(e => e.classList.remove('v3-tour-here'));
  if (!lab) return;
  const it = [...document.querySelectorAll('.v3-nav-item')].find(e => (e.textContent || '').trim().indexOf(lab) === 0);
  if (it) it.classList.add('v3-tour-here');
}

// The guide. Mounted in the shell so it survives navigation; it renders nothing until a walkthrough
// is running, and the reads below only start once one is.
function V3WalkDock() {
  const w = useV3Walk();
  React.useEffect(() => {
    document.body.classList.toggle('v3-walking', !!w.id && !w.min);
    if (!w.id || w.min) document.querySelectorAll('.v3-nav-item.v3-tour-here').forEach(e => e.classList.remove('v3-tour-here'));
  });
  if (!w.id) return null;
  return <V3Boundary where="walkthrough" resetKey={w.id + ':' + w.step} label="The walkthrough"><V3WalkRun w={w}/></V3Boundary>;
}
function V3WalkRun({ w }) {
  const walk = V3_WALKS.find(x => x.id === w.id) || V3_WALKS[0];
  const h = w.horizon || v3WalkHorizon();
  const H = V3_WALK_H.find(o => o.id === h) || V3_WALK_H[1];
  // All reads up front and unconditional (hooks), shared with the pages through useV3Rows keys.
  const cmp = useV3Rows('walk-' + h, (sb, b) => sb.rpc('fn_brand_period_compare', { p_brand_id: b, p_horizon: h }));
  const stock = useV3Rows('stock-plan', V3_STOCK_Q);
  const ret = useV3Rows('cust-ret', V3_RET_Q);
  const score = useV3Rows('walk-score', (sb, b) => sb.from('vw_channel_scoreboard')
    .select('platform,channel_type,spend_30d,avg_iroas,break_even_iroas').eq('brand_id', b).gt('spend_30d', 0)
    .order('spend_30d', { ascending: false, nullsFirst: false }).limit(8));
  const npd = useV3Rows('walk-npd', (sb, b) => sb.from('vw_product_npd_verdict')
    .select('title,revenue,paid:verdict->>paid_status').eq('brand_id', b)
    .order('revenue', { ascending: false, nullsFirst: false }).limit(300));
  const ue = useV3Rows('cust-ue', V3_UE_Q);
  // Channel diagnosis is per horizon; campaign-level detail cannot cover a year yet, and the
  // pop-out says so rather than asking.
  const diag = useV3Rows('walk-diag-' + h, (sb, b) => sb.rpc('fn_channel_diagnosis', { p_brand_id: b, p_horizon: h }));
  const board = useV3Board();
  const steps = walk.steps.concat(['end']);
  const i = Math.max(0, Math.min(w.step, steps.length - 1));
  const sid = steps[i];
  const def = sid === 'end' ? V3_WALK_END : V3_WALK_STEP[sid];
  // The pages that have a date control follow the walkthrough: the owner sees the page itself for
  // the period being discussed, not the last 30 days. Restored when the walkthrough ends.
  const follows = V3_PERIOD_PAGES.indexOf(def.dest) >= 0;
  const curP = cmp.rows && !Array.isArray(cmp.rows) && cmp.rows.periods ? cmp.rows.periods.cur : null;
  React.useEffect(() => {
    if (!curP || !follows || !window.__oiSetRange) return;
    if (V3_WALK.savedRange === undefined && window.__oiGetRange) V3_WALK.savedRange = window.__oiGetRange();
    window.__oiSetRange(curP.start, curP.end);
  }, [sid, h, curP && curP.start, follows]);
  const cardRef = React.useRef(null);
  const elRef = React.useRef(null);
  const lastDest = React.useRef(null);   // smooth-scroll only when the next stop is on the same page
  // spot: the lit rectangle (viewport px) · mode: where the caption sits · found: false once we gave up
  const [pos, setPos] = React.useState(() => ({ spot: null, mode: window.innerWidth <= 760 ? 'sheet' : 'corner', card: null, arrow: null, found: null }));
  // The comparison tables sit behind "Show the numbers", so the pop-out stays small enough to sit
  // beside the panel it is talking about.
  const [nums, setNums] = React.useState(false);

  // Arrive: open the page, wait for the panel to render, scroll it into view, then keep the
  // spotlight on it as the page settles or the owner scrolls.
  React.useEffect(() => {
    if (w.min) return;
    elRef.current = null;
    setPos(p => ({ spot: null, mode: p.mode, card: null, arrow: null, found: null }));
    setNums(false);
    // Same page only if the owner has not wandered off it between stops (the page stays live).
    const tNow = document.querySelector('.v3-page-title');
    const samePage = lastDest.current === def.dest && !!tNow && !!V3_BY_ID[def.dest] && tNow.textContent === V3_BY_ID[def.dest].label;
    lastDest.current = def.dest;
    if (window.__oiGo && !samePage) window.__oiGo(def.dest, null);
    v3TourNav(def.dest);
    let dead = false, tries = 0;
    // The caption pops out beside the lit panel — under it when there is room, over it when there
    // is room there, otherwise in the corner — and on a phone it rises from the bottom. The page
    // itself never moves or narrows for it.
    const place = () => {
      v3TourNav(def.dest);   // the nav re-renders its classes, so keep re-marking the item
      const el = elRef.current, vw = window.innerWidth, vh = window.innerHeight, phone = vw <= 760;
      if (!el || !el.isConnected) { const m = phone ? 'sheet' : 'corner'; setPos(p => p.mode === m ? p : { ...p, mode: m }); return; }
      const r = el.getBoundingClientRect(), pad = 8, gap = 16;
      const spot = { top: Math.round(r.top - pad), left: Math.round(r.left - pad), width: Math.round(r.width + pad * 2), height: Math.round(r.height + pad * 2) };
      const c = cardRef.current, cw = c ? c.offsetWidth : 384, ch = c ? c.offsetHeight : 320;
      let mode = phone ? 'sheet' : 'corner', card = null, arrow = null;
      if (!phone) {
        const left = Math.round(Math.max(16, Math.min(r.left, vw - cw - 16)));
        arrow = Math.round(Math.max(16, Math.min(r.left + 40 - left, cw - 32)));
        // Beside the panel whenever at least a short pop-out fits; it scrolls inside if it must.
        const below = vh - (spot.top + spot.height + gap) - 16, above = spot.top - gap - 16, MIN = 260;
        if (below >= Math.min(ch, MIN)) { mode = 'below'; card = { top: spot.top + spot.height + gap, left, max: Math.round(below) }; }
        else if (above >= Math.min(ch, MIN)) { mode = 'above'; const hgt = Math.min(ch, above); card = { top: Math.round(spot.top - gap - hgt), left, max: Math.round(above) }; }
      }
      setPos(p => {
        const same = p.spot && p.spot.top === spot.top && p.spot.left === spot.left && p.spot.height === spot.height
          && p.spot.width === spot.width && p.mode === mode && p.arrow === arrow
          && (!!p.card === !!card) && (!card || (p.card.top === card.top && p.card.left === card.left && p.card.max === card.max));
        return same ? p : { spot, mode, card, arrow, found: true };
      });
    };
    const onPage = () => { const t = document.querySelector('.v3-page-title'); return !!t && !!V3_BY_ID[def.dest] && t.textContent === V3_BY_ID[def.dest].label; };
    const arrive = () => {
      // The page we came from can hold the same kind of panel (Today has a money flow too), so
      // only look once the page we asked for is the one on screen.
      const el = onPage() ? (v3TourFind(def.target) || v3TourFind(def.fallback)) : null;
      if (!el) {
        if (++tries > 50) { if (!dead) setPos({ spot: null, mode: window.innerWidth <= 760 ? 'sheet' : 'corner', card: null, arrow: null, found: false }); return; }
        return setTimeout(() => { if (!dead) arrive(); }, 200);
      }
      elRef.current = el;
      const sticky = document.querySelector('.v3-askbar');
      const off = 24 + (sticky && getComputedStyle(sticky).position === 'sticky' ? sticky.offsetHeight : 0);
      const align = smooth => {
        const top = el.getBoundingClientRect().top - off;
        if (Math.abs(top) > 24) window.scrollTo({ top: Math.max(0, window.scrollY + top), behavior: smooth ? 'smooth' : 'auto' });
      };
      // A new page jumps straight to the panel; a stop further down the same page glides there,
      // so the owner sees where it sits relative to the last one.
      align(samePage);
      // The page above the panel is usually still loading, so its position moves after the first
      // scroll. Re-align as it settles (as V3Anchor does) — unless the owner has started scrolling.
      let touched = false;
      const stop = () => { touched = true; };
      ['wheel', 'touchmove', 'keydown'].forEach(ev => window.addEventListener(ev, stop, { once: true, passive: true }));
      [700, 1600, 3000].forEach(ms => setTimeout(() => { if (!dead && !touched && el.isConnected) align(false); }, ms));
      setTimeout(() => { if (!dead) place(); }, 40);
    };
    const t0 = setTimeout(arrive, 120);
    const iv = setInterval(place, 150);
    const key = e => { if (e.key === 'Escape') v3WalkSet({ min: true }); };
    window.addEventListener('scroll', place, { passive: true });
    window.addEventListener('resize', place);
    window.addEventListener('keydown', key);
    return () => { dead = true; clearTimeout(t0); clearInterval(iv); window.removeEventListener('scroll', place);
      window.removeEventListener('resize', place); window.removeEventListener('keydown', key); };
  }, [w.id, sid, w.min]);

  const end = () => { document.querySelectorAll('.v3-nav-item.v3-tour-here').forEach(e => e.classList.remove('v3-tour-here')); v3WalkEnd(false); };
  const go = k => v3WalkSet({ step: k });

  if (w.min) return (<button type="button" className="v3-tour-resume" onClick={() => v3WalkSet({ min: false })}>
    Resume walkthrough · stop {i + 1} of {steps.length}</button>);

  const data = cmp.rows && !Array.isArray(cmp.rows) ? cmp.rows : null;
  const P = data && data.periods;
  const X = P && P.cur ? { P, N: v3WalkNames(h, P), h, prods: data.products || [], stock: stock.rows,
    score: score.rows, ret: ret.rows ? (ret.rows[0] || {}) : null, npd: npd.rows, board: board.rows,
    series: data.series || [], cm: data.cm_ratio != null ? Number(data.cm_ratio) : null,
    ue: ue.rows ? (ue.rows[0] || null) : null } : null;
  const view = V3_WALK_VIEW[sid] || {};
  let means = [];
  if (X && view.means) { try { means = view.means(X) || []; } catch (e) { means = []; } }
  const live = v3LiveRows(board.rows || []);
  const inCats = (r, cats) => !cats || cats.indexOf(r.category) >= 0;
  let out = null;
  if (X && sid !== 'end') { try { out = def.build(X); } catch (e) { out = { say: ['Greta could not read this one just now.'] }; } }
  const stepActs = def.cat ? live.filter(r => r.category === def.cat).slice(0, 2) : [];
  const page = V3_BY_ID[def.dest];

  let says;
  if (cmp.err) {
    says = <p className="v3-walk-say">{/fn_brand_period_compare|schema cache|does not exist/i.test(cmp.err)
      ? 'The comparisons for this walkthrough need a server update that has not been switched on yet. The tour of the page still works.'
      : 'Greta couldn’t load the comparison just now.'}</p>;
  } else if (!X || (out && out.loading)) {
    says = <V3SkeletonRows n={2}/>;
  } else if (sid === 'end') {
    const take = walk.steps.map(s => { let o = null; try { o = V3_WALK_STEP[s].build(X); } catch (e) {}
      return o && o.say && o.say[0] && !o.loading ? [V3_WALK_STEP[s].q, o.say[0], s] : null; }).filter(Boolean);
    const acts = live.filter(r => inCats(r, walk.cats)).slice(0, 5);
    const ask = 'I just walked through ' + walk.label.toLowerCase() + ', ' + H.sub + ' (' + X.N.line + '). ' + take.map(t => t[1]).join(' ') + ' What should I do first, and why?';
    says = (<>
      <ul className="v3-walk-take">{take.map((t, k) => (<li key={k}><button type="button" className="v3-walk-link" onClick={() => go(k)}>{t[0]}</button><span>{t[1]}</span></li>))}</ul>
      {acts.length
        ? <V3WalkActs rows={acts} head="Do these, biggest £ first"/>
        : <><p className="v3-note">{walk.cats && walk.cats.length === 0 ? 'Greta has no open actions about customers. The biggest ones overall:' : 'Nothing on the board belongs to this area right now. The biggest ones overall:'}</p>
            <V3WalkActs rows={live.slice(0, 3)} head="The biggest actions overall"/></>}
      <div className="v3-btns">
        <button type="button" className="v3-btn v3-btn-p v3-btn-sm" onClick={end}>Finish here</button>
        <button type="button" className="v3-btn v3-btn-sm" onClick={() => { end(); window.__oiAsk && window.__oiAsk(ask); }}>Ask Greta a follow-up</button>
      </div>
    </>);
  } else {
    says = (<>
      {out.say.map((s, k) => <p key={k} className={'v3-walk-say' + (k === 0 ? ' lead' : '')}>{s}</p>)}
      {((out.tbl && !out.held) || out.ptbl || (out.list && !(def.onPage && pos.found))) && (
        <button type="button" className="v3-walk-link v3-tour-more" aria-expanded={nums} onClick={() => setNums(n => !n)}>
          {nums ? 'Hide the numbers' : 'Show the numbers'}</button>)}
      {nums && out.tbl && !out.held && <V3WalkTable X={X} rows={out.tbl}/>}
      {nums && out.ptbl && <V3WalkProducts X={X} rows={out.ptbl}/>}
      {nums && out.list && !(def.onPage && pos.found) && <V3WalkList list={out.list}/>}
      {out.note && <p className="v3-note">{out.note}</p>}
      {out.fix && <button type="button" className="v3-btn v3-btn-sm" onClick={() => window.__oiNav && window.__oiNav(out.fix[0], out.fix[1])}>{out.fix[2]}</button>}
    </>);
  }

  return (<>
    {pos.spot && (() => {
      // Four plain panels dim everything around the lit rectangle; none of them takes clicks.
      const t = Math.max(0, pos.spot.top), l = Math.max(0, pos.spot.left), bt = pos.spot.top + pos.spot.height, rt = pos.spot.left + pos.spot.width;
      return (<div aria-hidden="true">
        <i className="v3-tour-dim" style={{ top: 0, left: 0, right: 0, height: t }}/>
        <i className="v3-tour-dim" style={{ top: Math.max(0, bt), left: 0, right: 0, bottom: 0 }}/>
        <i className="v3-tour-dim" style={{ top: t, left: 0, width: l, height: Math.max(0, bt - t) }}/>
        <i className="v3-tour-dim" style={{ top: t, left: rt, right: 0, height: Math.max(0, bt - t) }}/>
        <div className="v3-tour-spot" style={{ top: pos.spot.top, left: pos.spot.left, width: pos.spot.width, height: pos.spot.height }}>
          <span className="v3-tour-tag">{i + 1}</span></div>
      </div>);
    })()}
    {pos.found === false && <div className="v3-tour-scrim" aria-hidden="true"/>}
    <aside ref={cardRef} className={'v3-tour-card v3-tour-' + pos.mode} role="dialog" aria-label={'Walkthrough: ' + walk.label}
      style={pos.card ? { top: pos.card.top, left: pos.card.left, maxHeight: pos.card.max } : undefined}>
      {pos.card && pos.arrow != null && <i className={'v3-tour-arrow ' + (pos.mode === 'above' ? 'down' : 'up')} style={{ left: pos.arrow }} aria-hidden="true"/>}
      <div className="v3-tour-top">
        <span className="v3-kick">{walk.label} · {i + 1} of {steps.length}</span>
        <div className="v3-seg v3-walk-h" role="group" aria-label="Compare over">
          {V3_WALK_H.map(o => <button key={o.id} type="button" aria-pressed={o.id === h} title={o.label + ' — ' + o.sub + ', and against last year'}
            onClick={() => v3WalkSetHorizon(o.id)}>{o.short}</button>)}
        </div>
        <button type="button" className="v3-btn v3-btn-q v3-btn-sm" onClick={() => v3WalkSet({ min: true })}>Hide</button>
        <button type="button" className="v3-btn v3-btn-q v3-btn-sm" aria-label="End walkthrough" onClick={end}><Icon name="close" size={14}/></button>
      </div>
      <div className="v3-tour-body">
        <h2 className="v3-walk-q">{sid === 'end' ? 'What you learned, and what to do' : def.q}</h2>
        {page && <p className="v3-tour-where">You are on <b>{page.label}</b> — it lives in the menu under {page.group}.</p>}
        {pos.found === false
          ? <p className="v3-note">This part of {page ? page.label : 'the page'} is not showing for your data yet, so there is nothing to point at — here is what Greta can tell you.</p>
          : def.what && <div className="v3-tour-sec"><div className="v3-tour-h">What you are looking at</div><p className="v3-walk-say">{def.what}</p>
              {X && sid !== 'end' && <p className="v3-tour-view">{follows
                ? <>The page is now set to {X.N.cur}{V3_WALK_PANEL[sid] ? <>; this panel always shows {V3_WALK_PANEL[sid]}</> : null}.</>
                : V3_WALK_PANEL[sid] ? <>This panel always shows {V3_WALK_PANEL[sid]}{view.chart ? '; the chart below follows your choice.' : '.'}</> : null}</p>}</div>}
        <div className="v3-tour-sec">
          {sid !== 'end' && <div className="v3-tour-h">What it says{def.now ? ' · right now' : X ? ' · ' + X.N.line : ''}</div>}
          {X && view.chart && !cmp.err && <V3WalkChart X={X} metric={view.chart}/>}
          {says}
        </div>
        {X && means.length > 0 && <div className="v3-tour-sec"><div className="v3-tour-h">What it means for the business</div>
          {means.map((m, k) => <p key={k} className="v3-walk-say">{m}</p>)}</div>}
        {X && view.why && <div className="v3-tour-sec">
          {h === 'year'
            ? <p className="v3-walk-say">Campaign-level ad detail does not go back a full two years yet, so Greta can explain why a channel moved for a week, month or quarter, not a year.</p>
            : diag.err ? <p className="v3-note">Greta could not load the channel detail just now.</p>
            : <V3WalkWhy X={X} diag={diag.rows && !Array.isArray(diag.rows) ? diag.rows : null} focus={sid === 'efficiency'}/>}</div>}
        {stepActs.length > 0 && <V3WalkActs rows={stepActs} head="What to do about it"/>}
      </div>
      <div className="v3-tour-foot">
        <button type="button" className="v3-btn v3-btn-sm" disabled={i === 0} onClick={() => go(i - 1)}>Back</button>
        <ol className="v3-walk-steps" aria-label="Stops">
          {steps.map((s, k) => (<li key={s}><button type="button" aria-current={k === i ? 'step' : undefined}
            className={'v3-walk-dot' + (k < i ? ' done' : '')} onClick={() => go(k)}
            title={(s === 'end' ? V3_WALK_END : V3_WALK_STEP[s]).q}>{k + 1}</button></li>))}
        </ol>
        {sid !== 'end' && <button type="button" className="v3-btn v3-btn-p v3-btn-sm" onClick={() => go(i + 1)}>
          {steps[i + 1] === 'end' ? 'What to do' : 'Next'} <Icon name="arrowRight" size={13}/></button>}
      </div>
    </aside>
  </>);
}

// On Today: one floating button. It pops the picker out over the page — nothing is built into the
// page and nothing on it moves. Pick a horizon and an area and the tour starts.
function V3WalkFab({ dest }) {
  const w = useV3Walk();
  const [open, setOpen] = React.useState(false);
  const [h, setH] = React.useState(v3WalkHorizon);
  const ref = React.useRef(null);
  React.useEffect(() => {
    if (!open) return;
    const off = e => { if (ref.current && !ref.current.contains(e.target)) setOpen(false); };
    const key = e => { if (e.key === 'Escape') setOpen(false); };
    document.addEventListener('mousedown', off);
    window.addEventListener('keydown', key);
    return () => { document.removeEventListener('mousedown', off); window.removeEventListener('keydown', key); };
  }, [open]);
  if (w.id || dest !== 'today') return null;
  return (<div className="v3-walk-fab" ref={ref}>
    {open && (<div className="v3-walk-pop" role="dialog" aria-labelledby="v3-walk-pop-t">
      <div className="v3-walk-pop-head">
        <h2 className="v3-walk-pop-t" id="v3-walk-pop-t">Walk me through</h2>
        <button type="button" className="v3-btn v3-btn-q v3-btn-sm" aria-label="Close" onClick={() => setOpen(false)}><Icon name="close" size={14}/></button>
      </div>
      <p className="v3-note">Greta takes you round the app panel by panel: what each one shows, what it says against the period before and the same time last year, and what to do about it.</p>
      <div className="v3-walk-hgroups" role="group" aria-label="Compare over">
        {V3_WALK_HGROUPS.map(g => (<div key={g} className="v3-walk-hgroup">
          <span className="v3-walk-hlab">{g}</span>
          <div className="v3-seg">{V3_WALK_H.filter(o => o.label === g).map(o => <button key={o.id} type="button" aria-pressed={h === o.id}
            title={o.sub + (o.id === 'year' ? '' : ', and against last year')} onClick={() => setH(o.id)}>{o.short}</button>)}</div>
        </div>))}
      </div>
      <div className="v3-walk-pick">
        {V3_WALKS.map(x => (<button key={x.id} type="button" className="v3-walk-opt" onClick={() => { setOpen(false); v3WalkStart(x.id, h); }}>
          <span className="v3-walk-opt-t">{x.label}</span>
          <span className="v3-walk-opt-q">{x.q}</span>
        </button>))}
      </div>
    </div>)}
    <button type="button" className="v3-walk-fab-btn" aria-expanded={open} onClick={() => setOpen(o => !o)}>
      <Icon name="spark" size={15}/> Walk me through</button>
  </div>);
}

function V3App({ dest, go, children, start, periodCtl }) {
  const d = V3_BY_ID[dest] || V3_NAV[0];
  const sig = useV3NavSignals();
  useFigureTypography(dest);
  return (<div className="v3-root">
    {/* First thing in the tab order on every page: the nav has 16 items and a keyboard
        user had to walk all of them to reach the content. */}
    <a className="v3-skip" href="#v3-content">Skip to content</a>
    <div className="v3-shell">
      <nav className="v3-nav" aria-label="Main">
        <button type="button" className="v3-nav-search" onClick={() => window.__oiCommandOpen && window.__oiCommandOpen()}>
          <Icon name="search" size={14}/> Search… <kbd>{V3_KBD}</kbd>
        </button>
        {(() => { let prev = null; return V3_NAV.map(e => {
          const head = e.group !== prev ? <div key={'h' + e.group} className="v3-nav-group">{e.group}</div> : null;
          prev = e.group;
          const n = e.id === 'actions' ? sig.actions : 0;
          const alert = e.id === 'settings' && sig.feedAlert;
          return (<React.Fragment key={e.id}>{head}
            <button type="button" className={'v3-nav-item' + (e.id === dest ? ' active' : '')} onClick={() => go(e.id)} aria-current={e.id === dest ? 'page' : undefined}>
              <Icon name={e.icon} size={17}/>{e.label}
              {n > 0 && <span className="v3-nav-n" aria-label={n + ' actions worth doing'}>{n}</span>}
              {alert && <span className="v3-nav-alert" aria-label="A data source has stopped reporting"/>}
            </button>
          </React.Fragment>);
        }); })()}
      </nav>
      <main className="v3-main" id="v3-content" tabIndex={-1}>
        {/* Ask sits on Today; everywhere else it is one keystroke away (nav item, ⌘K). On every
            page it was a sticky bar above the title, so the first thing on each screen was an
            input rather than the page's own question. */}
        {dest === 'today' && <V3AskBar dest={dest}/>}
        <header className="v3-page-head">
          <div className="v3-page-head-row">
            <div>
              <h1 className="v3-page-title">{d.label}</h1>
              <p className="v3-page-q">{d.q}</p>
            </div>
            {V3_PERIOD_PAGES.indexOf(dest) >= 0 ? periodCtl : null}
          </div>
          <V3Thread dest={dest} go={go}/>
        </header>
        <BrandAgeBanner/>
        <MarginNudge/>
        {children}
      </main>
    </div>
    <nav className="v3-mobile" aria-label="Main (mobile)">
      {V3_MOBILE.map(e => (
        <button key={e.id} type="button" className={'v3-mb' + (e.id === dest ? ' active' : '')} onClick={() => go(e.id)}>
          <Icon name={e.icon} size={19}/><span>{e.label}</span>
        </button>
      ))}
      <button type="button" className="v3-mb" onClick={() => window.__oiCommandOpen && window.__oiCommandOpen()}>
        <Icon name="search" size={19}/><span>More</span>
      </button>
    </nav>
    <V3WalkDock/>
    <V3WalkFab dest={dest}/>
  </div>);
}

function App(){
  const [section, setSection] = useState('home');
  // V3: one destination at a time, no sub-tab state. Old (section, sub) deep links
  // are translated by v3Route, so every existing call site still lands somewhere real.
  const [v3dest, setV3dest] = useState('today');
  // Today-first gate (page head): any other page releases the start-up reads straight away
  React.useEffect(() => { if (v3dest !== 'today') { try { window.GRETA_TODAY_DONE && window.GRETA_TODAY_DONE(); } catch (e) {} } }, [v3dest]);
  const [subTabBySection, setSubTabBySection] = useState(
    Object.fromEntries(NAV.map(s => [s.id, s.subtabs[0].id]))
  );
  const [period, setPeriod] = useState('30d');
  const [rangeStart, setRangeStart] = useState('');
  const [rangeEnd, setRangeEnd] = useState('');
  const customActive = !!(rangeStart && rangeEnd && rangeStart <= rangeEnd);
  // Re-read the data bounds first: the live loader may have replaced D.shopify since the last
  // render (it fires frkl-data-updated, which re-renders App).
  refreshRealBounds();
  // Resolve the active window (named period or custom range), then set it BEFORE
  // computing start / rendering panels so every panel reads the same window.
  const win = customActive ? {start: rangeStart, end: rangeEnd} : periodRange(period);
  setActiveEnd(win.end);
  const start = win.start;
  const activeSection = NAV.find(s => s.id === section) || NAV[0];
  const activeSubId = subTabBySection[section] || activeSection.subtabs[0].id;
  const activeSubTab = activeSection.subtabs.find(t => t.id === activeSubId) || activeSection.subtabs[0];

  // Decision-led rail: a rail entry is active when its section is active AND (if it
  // targets a sub-tab) that sub is active; otherwise when the section's default sub
  // is active — so "Today"/"AI Analyst" (and "Growth"/"Creative") stay distinct.
  const railActive = (e) => {
    if (e.section !== section) return false;
    const def = (NAV_BY_ID[e.section]?.subtabs[0]?.id);
    return e.sub ? (activeSubId === e.sub) : (activeSubId === def);
  };
  const goRail = (e) => {
    setSection(e.section);
    const sub = e.sub || (NAV_BY_ID[e.section]?.subtabs[0]?.id);
    if (sub) setSubTabBySection(p => ({...p, [e.section]: sub}));
    window.scrollTo({top: 0, behavior: 'smooth'});
  };

  // A completed OAuth round trip is the single most important activation step, and it is
  // only observable here: the provider redirects to oauth-*-callback, which is server-side
  // and carries no session, and it hands back ?connected=<provider>. Recorded once and the
  // param is then stripped, so a refresh or a bookmarked URL cannot double-count it.
  React.useEffect(() => {
    let provider = null;
    try { provider = new URLSearchParams(window.location.search).get('connected'); } catch (e) {}
    if (!provider) return;
    // The brand id arrives with the membership round trip, which usually lands after this
    // effect; track() queues until then, so firing immediately is safe.
    track('source_connected', { provider: provider }, 'settings');
    // Today announces the reconnection (V3Reconnected). It renders long after this
    // effect has stripped the param, so the provider is handed forward rather than
    // read twice — one reader, one strip, no race over who gets there first.
    try { window.GRETA_JUST_CONNECTED = provider; } catch (e) {}
    try {
      const u = new URL(window.location.href);
      u.searchParams.delete('connected');
      u.searchParams.delete('shop');
      window.history.replaceState({}, '', u.toString());
    } catch (e) {}
  }, []);

  // The arrival itself was never counted. Both other page_view call sites sit in navigation
  // handlers, so a session that landed on Today and stayed there wrote nothing at all: no
  // denominator for time-to-first-action, and vw_product_activation undercounting sessions
  // by every visitor who never changed page. Found the hard way -- signed in, three minutes
  // on Today, product_events still empty.
  //
  // Guarded on window rather than a module-level flag because greta-app.js is a classic
  // top-level script sharing one global scope with the embeds, and a new top-level binding
  // there is how cost-entry.build.js took the whole app down. Once per tab is the right
  // grain: the tracker's session id is per-tab too, so a remount is the same visit and must
  // not read as a second arrival, while navigating away and back is a real page_view and
  // still fires through __oiGo.
  //
  // brand_id has not resolved this early. track() queues and flushes on frkl-brand-ready,
  // which is precisely what that queue was built for -- the first page_view of a session
  // fires while membership is still in flight.
  React.useEffect(() => {
    if (window.__oiArrivalSeen) return;
    try { window.__oiArrivalSeen = true; } catch (e) {}
    // v3dest is deliberately read once, as the landing destination, not tracked as a dep.
    track('page_view', { dest: v3dest, arrival: true }, v3dest);
  }, []);

  // The walkthrough sets the date range on the pages that have one, and restores it afterwards.
  React.useEffect(() => {
    window.__oiSetRange = (s, e, p) => { setRangeStart(s || ''); setRangeEnd(e || ''); if (p) setPeriod(p); };
    window.__oiGetRange = () => ({ s: rangeStart, e: rangeEnd, p: period });
  }, [rangeStart, rangeEnd, period]);

  // Global deep-link helper so findings can jump to their evidence tab (clickable cross-refs).
  React.useEffect(() => {
    window.__oiGo = (dest, anchor) => {
      setV3dest(dest);
      track('page_view', { dest: dest }, dest);
      window.__oiV3Anchor = anchor || null;
      window.scrollTo({top: 0, behavior: 'smooth'});
      if (anchor) setTimeout(() => { try { window.dispatchEvent(new Event('oi-v3-anchor')); } catch (e) {} }, 0);
    };
    window.__oiNav = (sec, sub) => {
      if (UI_V3) { const r = v3Route(sec, sub); window.__oiGo(r[0], r[1]); return; }
      setSection(sec);
      if (sub) setSubTabBySection(p => ({...p, [sec]: sub}));
      window.scrollTo({top: 0, behavior: 'smooth'});
    };
    // "Ask about this" — any card can hand a question to the AI panel: stash it,
    // jump to Home › Ask, and let AskPanel pick it up (prefilled, ready to send).
    window.__oiAsk = (q) => {
      try { window.__oiAskPending = q || ''; } catch(e){}
      window.__oiNav('home', 'ask');
      try { window.dispatchEvent(new Event('oi-ask-prefill')); } catch(e){}
    };
  }, []);

  // Scroll to top whenever section or sub-tab changes — premium-feel small touch
  React.useEffect(() => {
    window.scrollTo({top: 0, behavior: 'smooth'});
  }, [section, activeSubId, v3dest]);

  // Re-render whenever the live-data loader fetches fresh data from Supabase.
  // The loader mutates window.FRKL_* in place; bumping a state forces React to
  // re-read those globals via the child components' next render pass.
  const [dataVersion, setDataVersion] = useState(0);
  React.useEffect(() => {
    const handler = () => setDataVersion(v => v + 1);
    window.addEventListener('frkl-data-updated', handler);
    return () => window.removeEventListener('frkl-data-updated', handler);
  }, []);

  // ── V3 render: one nav, one destination, no sub-tab strip, no plan rail.
  // The plan rail's goal/pace content lives on Today and Goal & costs; the sticky
  // health bar folds into the Today headline (Phase 2 parity rows C032–C035, C038).
  if (UI_V3) {
    const page = (V3_PAGES[v3dest] || V3_PAGES.today)({start, period, customActive});
    return (
      <div>
        <V3App dest={v3dest} go={(d)=>{ setV3dest(d); track('page_view', { dest: d }, d); }} start={start}
               periodCtl={<V3Period period={period} setPeriod={setPeriod} rangeStart={rangeStart} rangeEnd={rangeEnd}
                                    setRangeStart={setRangeStart} setRangeEnd={setRangeEnd} customActive={customActive}/>}><V3Boundary where={'page:' + v3dest} resetKey={v3dest} label="This page">{page}</V3Boundary></V3App>
        <footer className="app-footer">
          <div className="app-footer-brand"><span>greta</span></div>
          <span className="app-footer-dot"/>
          <span title={D.meta.source}>{(OI_BRAND.name||'your')} workspace · {(D.meta.source||'').split('—')[0].trim()||'Live data'}</span>
          <span className="app-footer-dot"/>
          {D.meta.captured && <span>Updated {v3Stamp(D.meta.captured)}</span>}
          <div style={{flex:1}}/>
          <span>Auto-updates daily</span>
        </footer>
        <ToastHost/>
        <CommandMenu/>
        <EvidenceDrawer/>
      </div>
    );
  }

  return (
    <div>
      {/* Inner app bar removed — the app shell (app/index.html) is now the SINGLE top bar
          (brand + workspace + account nav + theme + log out). Search lives in the sidebar
          below; the redundant per-dashboard "Last N days" date selector was removed. */}
      <div className="app-shell">
        <nav className="sidebar">
          <button className="nav-cmd" onClick={()=>window.__oiCommandOpen&&window.__oiCommandOpen()}>
            <Icon name="search" size={14}/> Search… <kbd>{V3_KBD}</kbd>
          </button>
          {(()=>{ let prev=null; return RAIL.map((e,i) => {
            const head = (e.group && e.group!==prev) ? <div className="nav-label">{e.group}</div> : null;
            prev = e.group;
            return (<React.Fragment key={i}>
              {head}
              <div className={'nav-item' + (railActive(e) ? ' active' : '')} onClick={()=>goRail(e)} style={e.pin?{marginTop:'auto',borderTop:'1px solid var(--border-subtle)',borderRadius:'var(--radius-none)',paddingTop:'13px',marginLeft:2,marginRight:2}:undefined}>
                <Icon name={e.icon||'info'} size={17}/>{e.label}
              </div>
            </React.Fragment>);
          }); })()}
        </nav>
        <main className="app-main">
          <div className="wrap">
        {/* Sub-nav: only render when the section has >1 sub-tab */}
        {activeSection.subtabs.length > 1 && (
          <div className="subnav">
            {activeSection.subtabs.map(t => (
              <div key={t.id}
                   className={'subtab' + (activeSubId === t.id ? ' active' : '')}
                   onClick={()=>setSubTabBySection({...subTabBySection, [section]: t.id})}>
                {t.label}
              </div>
            ))}
            <div style={{flex:1}}/>
            <div className="meta" style={{fontSize:'var(--text-xs)'}} title={D.meta.source}>{(D.meta.source||'').split('—')[0].trim()||'Live data'} · updated {D.meta.captured}</div>
          </div>
        )}

        {/* Freshness now lives as a compact chip in the app bar (FreshnessChip). */}
        <BrandAgeBanner/>

        {/* Nudge: if gross_margin isn't set, the engine skips this brand — surface it everywhere. */}
        <MarginNudge/>

        {/* Active sub-tab */}
        {activeSubTab.component({start, period, customActive})}
          </div>
        </main>
        <aside className="plan-rail"><GretaPlanRail/></aside>
      </div>
      {/* Product footer — quiet, signals "real product" */}
      <footer className="app-footer">
        <div className="app-footer-brand">
          <div className="brand-mark" style={{width:18, height:18}}>
            <svg viewBox="0 0 256 256" xmlns="http://www.w3.org/2000/svg" aria-label="Greta">
              <defs>
                <linearGradient id="ffpb" x1="0" y1="0" x2="1" y2="0"><stop offset="0" stopColor={PAL.accent}/><stop offset="1" stopColor={PAL.data4}/></linearGradient>
                <linearGradient id="ffgm" x1="0" y1="0" x2="1" y2="0"><stop offset="0" stopColor={PAL.accent}/><stop offset="1" stopColor={PAL.accent}/></linearGradient>
              </defs>
              <rect x="49" y="30" width="138" height="41" rx="20.5" transform="rotate(-45 118 50.5)" fill="url(#ffpb)"/>
              <rect x="71" y="177" width="138" height="41" rx="20.5" transform="rotate(-45 140 197.5)" fill="url(#ffgm)"/>
              <circle cx="97" cy="132" r="24" fill={PAL.ink}/>
            </svg>
          </div>
          <span>greta</span>
        </div>
        <span className="app-footer-dot"/>
        <span title={D.meta.source}>{(OI_BRAND.name||'frkl')} workspace · {(D.meta.source||'').split('—')[0].trim()||'Live data'}</span>
        <span className="app-footer-dot"/>
        {D.meta.captured && <span>Updated {v3Stamp(D.meta.captured)}</span>}
        <div style={{flex:1}}/>
        <span>Auto-updates daily</span>
      </footer>
      <ToastHost/>
      <CommandMenu/>
      <EvidenceDrawer/>
      <StickyHealthBar/>
      <nav className="mobile-botnav">
        {MOBILE_NAV.map((e,i)=>(
          <button key={i} className={'mb-item'+(railActive(e)?' active':'')} onClick={()=>goRail(e)}>
            <Icon name={e.icon} size={19}/><span>{e.label}</span>
          </button>
        ))}
        <button className="mb-item" onClick={()=>window.__oiCommandOpen&&window.__oiCommandOpen()}>
          <Icon name="search" size={19}/><span>More</span>
        </button>
      </nav>
    </div>
  );
}
ReactDOM.createRoot(document.getElementById('root')).render(<App/>);
